// Setup Nav Tabs
function setupNavigation() {
  document.querySelectorAll('.nav-link').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.preventDefault();
      document.querySelectorAll('.nav-link').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      activeTab = btn.getAttribute('data-tab');
      renderApp();
      // On mobile, close sidebar if open
      const sidebar = document.getElementById('sidebar');
      const backdrop = document.getElementById('sidebar-backdrop');
      if (window.innerWidth < 1024 && sidebar) {
        sidebar.classList.add('-translate-x-full');
        if (backdrop) backdrop.classList.add('hidden');
      }
    });
  });

  // Universal menu toggle is handled via inline onclick="toggleSidebarCollapse(event)" on #sidebar-toggle-btn

  // Keyboard shortcut (Alt + M or Ctrl + B) & Window Resize listener
  if (!window._sidebarListenersBound) {
    window._sidebarListenersBound = true;
    window.addEventListener('resize', () => {
      applySidebarState();
    });
    document.addEventListener('keydown', (e) => {
      if ((e.altKey && (e.key === 'm' || e.key === 'M')) || (e.ctrlKey && (e.key === 'b' || e.key === 'B'))) {
        const activeTag = document.activeElement ? document.activeElement.tagName : '';
        if (!['INPUT', 'TEXTAREA', 'SELECT'].includes(activeTag)) {
          e.preventDefault();
          toggleSidebarCollapse();
        }
      }
    });
  }
}

// Switch tab programmatically
function switchTab(tabName, unitId = null) {
  activeTab = tabName;
  if (unitId) selectedUnitId = unitId;
  updateLayoutForActiveTab();
  document.querySelectorAll('.nav-link').forEach(b => {
    if (b.getAttribute('data-tab') === tabName) {
      b.classList.add('active');
    } else {
      b.classList.remove('active');
    }
  });
  renderApp();
  window.scrollTo({ top: 0, behavior: 'smooth' });
}

