// 0. PANEL DE EMPRESAS & GESTIÓN DE CONTRATOS / COBROS (MASTER)
// ----------------------------------------------------
let companiesViewMode = 'list'; // 'list' (default) o 'grid'
let activeCompanyFilter = 'todas'; // 'todas', 'al_dia', 'por_cobrar', 'vencidos', 'mensuales', 'anuales', 'inactivas'
let currentManagingContractCompanyId = null;
let currentContractModalTab = 'cobros'; // 'cobros', 'historial', 'terminos', 'baja'

function renderEmpresas() {
  if (!isMasterUser()) {
    activeTab = 'dashboard';
    renderDashboard();
    return;
  }

  const container = document.getElementById('main-content');
  if (!appData.companies) appData.companies = [];

  const todayStr = new Date().toISOString().slice(0, 10);
  const totalEmpresas = appData.companies.length;
  const totalEstanques = appData.companies.reduce((sum, c) => sum + (parseInt(c.earthenPondsCount, 10) || 10), 0);
  const totalGeos = appData.companies.reduce((sum, c) => sum + (parseInt(c.geomembranesCount, 10) || 3), 0);
  const activeEmpresas = appData.companies.filter(c => c.status === 'activo').length;

  // Compute Contract & Financial Metrics for DC Asesorías
  let totalMRR = 0; // Mensual Recurrente
  let totalARR = 0; // Anualizado
  let contractsAlDia = 0;
  let contractsPorCobrar = 0; // ≤ 7 días
  let contractsVencidos = 0; // < 0 días
  let totalRecaudadoGlobal = 0;

  appData.companies.forEach(c => {
    if (!c.contract) {
      c.contract = {
        planName: "Asesoría Técnica Zootécnica",
        billingCycle: "mensual",
        feeAmount: 2000000,
        startDate: c.createdAt || "2024-01-01",
        billingDay: 5,
        nextBillingDate: new Date(Date.now() + 10 * 86400000).toISOString().slice(0, 10),
        status: c.status === 'activo' ? 'al_dia' : 'finalizado'
      };
    }
    if (!c.billingPayments) c.billingPayments = [];

    const contract = c.contract;
    const cycle = contract.billingCycle || 'mensual';
    const fee = parseFloat(contract.feeAmount) || 0;

    let monthlyEquiv = fee;
    if (cycle === 'anual') monthlyEquiv = Math.round(fee / 12);
    else if (cycle === 'trimestral') monthlyEquiv = Math.round(fee / 3);
    else if (cycle === 'semestral') monthlyEquiv = Math.round(fee / 6);

    if (c.status === 'activo' && contract.status !== 'finalizado') {
      totalMRR += monthlyEquiv;
      totalARR += (monthlyEquiv * 12);
    }

    const payments = c.billingPayments || [];
    totalRecaudadoGlobal += payments.reduce((sum, p) => sum + (parseFloat(p.amount) || 0), 0);

    if (contract.status === 'finalizado' || c.status !== 'activo') {
      // Inactiva
    } else if (contract.nextBillingDate) {
      const diffDays = Math.ceil((new Date(contract.nextBillingDate) - new Date(todayStr)) / (1000 * 60 * 60 * 24));
      if (diffDays < 0) {
        contractsVencidos++;
      } else if (diffDays <= 7) {
        contractsPorCobrar++;
      } else {
        contractsAlDia++;
      }
    } else {
      contractsAlDia++;
    }
  });

  let html = `
    <div class="space-y-6">
      <!-- Master Header Banner with "Crear Empresa" Button -->
      <div class="bg-gradient-to-r from-slate-950 via-slate-900 to-amber-950 text-white p-6 sm:p-8 rounded-3xl shadow-xl border border-amber-900/30 relative overflow-hidden">
        <div class="absolute -right-10 -bottom-10 w-72 h-72 bg-amber-500/10 rounded-full blur-3xl pointer-events-none"></div>
        <div class="relative z-10 flex flex-col md:flex-row md:items-center justify-between gap-6">
          <div class="space-y-2">
            <div class="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-amber-500/20 text-amber-300 border border-amber-500/30 text-xs font-bold uppercase tracking-wider">
              <i class="fa-solid fa-crown text-amber-400"></i> Panel Maestro Multigranja (DC Asesorías)
            </div>
            <h1 class="text-2xl sm:text-3xl font-extrabold tracking-tight text-white">
              Gestión de Empresas, Contratos & Cobros
            </h1>
            <p class="text-slate-300 text-sm max-w-2xl leading-relaxed">
              Supervisión técnica integral de piscícolas asesoradas. Administre empresas clientes, contratos mensuales o anuales, controle fechas de vencimiento y registre recaudos de facturación.
            </p>
          </div>
          <div class="flex flex-wrap items-center gap-3">
            ${isMasterUser() ? `
              <button onclick="openBackupManagerModal()" class="px-5 py-3.5 bg-slate-800 hover:bg-slate-700 text-emerald-400 font-extrabold rounded-2xl text-sm shadow-md flex items-center gap-2 border border-slate-700 transition cursor-pointer" title="Gestor de Copias de Seguridad y Protección de Datos">
                <i class="fa-solid fa-shield-halved text-base text-emerald-400"></i> Copias & Seguridad
              </button>
              <button onclick="openModal('modal-new-company')" class="px-6 py-3.5 bg-gradient-to-r from-amber-500 to-orange-600 hover:from-amber-400 hover:to-orange-500 text-slate-950 font-black rounded-2xl text-sm shadow-lg shadow-amber-600/30 flex items-center gap-2.5 transition transform hover:scale-[1.02] cursor-pointer">
                <i class="fa-solid fa-circle-plus text-base text-slate-950"></i> Crear Empresa
              </button>
            ` : `
              <span class="text-xs bg-slate-800 text-slate-300 px-4 py-2.5 rounded-2xl font-bold flex items-center gap-2 border border-slate-700">
                <i class="fa-solid fa-eye text-cyan-400"></i> Directorio en Modo Consulta
              </span>
            `}
          </div>
        </div>
      </div>

      <!-- Financial & Contract KPI Cards for DC Asesorías -->
      <div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        <!-- KPI 1: MRR (Facturación Mensual Recurrente) -->
        <div class="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm relative overflow-hidden flex flex-col justify-between">
          <div class="flex items-center justify-between">
            <span class="text-xs font-bold text-slate-400 uppercase tracking-wider">Facturación Mensual (MRR)</span>
            <div class="w-8 h-8 rounded-lg bg-emerald-50 text-emerald-600 flex items-center justify-center text-sm font-bold">
              <i class="fa-solid fa-money-bill-wave"></i>
            </div>
          </div>
          <div class="mt-2">
            <div class="text-2xl font-black text-emerald-700">${formatCurrency(totalMRR)}</div>
            <p class="text-xs text-slate-500 mt-1">
              Proyección anual: <strong>${formatCurrency(totalARR)}</strong> / año
            </p>
          </div>
        </div>

        <!-- KPI 2: Estado de Cobros y Cartera -->
        <div class="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm relative overflow-hidden flex flex-col justify-between">
          <div class="flex items-center justify-between">
            <span class="text-xs font-bold text-slate-400 uppercase tracking-wider">Estado de Cartera</span>
            <div class="w-8 h-8 rounded-lg ${contractsVencidos > 0 ? 'bg-rose-50 text-rose-600 animate-pulse' : 'bg-sky-50 text-sky-600'} flex items-center justify-center text-sm font-bold">
              <i class="fa-solid fa-file-invoice-dollar"></i>
            </div>
          </div>
          <div class="mt-2">
            <div class="text-2xl font-black ${contractsVencidos > 0 ? 'text-rose-600' : 'text-slate-900'}">
              ${contractsAlDia} Al Día
            </div>
            <div class="flex items-center gap-2 mt-1 text-xs font-semibold">
              <span class="text-amber-600">${contractsPorCobrar} Por Cobrar</span>
              ${contractsVencidos > 0 ? `<span class="text-rose-600">| ${contractsVencidos} En Mora</span>` : ''}
            </div>
          </div>
        </div>

        <!-- KPI 3: Recaudo Histórico -->
        <div class="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm relative overflow-hidden flex flex-col justify-between">
          <div class="flex items-center justify-between">
            <span class="text-xs font-bold text-slate-400 uppercase tracking-wider">Recaudo Acumulado</span>
            <div class="w-8 h-8 rounded-lg bg-amber-50 text-amber-600 flex items-center justify-center text-sm font-bold">
              <i class="fa-solid fa-vault"></i>
            </div>
          </div>
          <div class="mt-2">
            <div class="text-2xl font-black text-slate-900">${formatCurrency(totalRecaudadoGlobal)}</div>
            <p class="text-xs text-slate-500 mt-1">Total cobros registrados en plataforma</p>
          </div>
        </div>

        <!-- KPI 4: Infraestructura Técnica Global -->
        <div class="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm relative overflow-hidden flex flex-col justify-between">
          <div class="flex items-center justify-between">
            <span class="text-xs font-bold text-slate-400 uppercase tracking-wider">Empresas & Unidades</span>
            <div class="w-8 h-8 rounded-lg bg-cyan-50 text-cyan-600 flex items-center justify-center text-sm font-bold">
              <i class="fa-solid fa-layer-group"></i>
            </div>
          </div>
          <div class="mt-2">
            <div class="text-2xl font-black text-slate-900">${totalEmpresas} <span class="text-xs font-bold text-slate-500">Empresas</span></div>
            <p class="text-xs text-slate-500 mt-1">
              ${totalEstanques} Estanques + ${totalGeos} Geos = <strong>${totalEstanques + totalGeos} Unidades</strong>
            </p>
          </div>
        </div>
      </div>

      <!-- Companies List Container -->
      <div class="bg-white rounded-3xl border border-slate-200 shadow-sm p-4 sm:p-6 space-y-6">
        <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-4 pb-4 border-b border-slate-100">
          <div>
            <h2 class="text-lg font-bold text-slate-900 flex items-center gap-2">
              <i class="fa-solid fa-building-user text-amber-500"></i> Directorio de Empresas Piscícolas
            </h2>
            <p class="text-xs text-slate-500">Gestione contratos mensuales/anuales, registre pagos o elimine empresas que ya no trabajen en la plataforma</p>
          </div>
          <div class="flex items-center gap-3">
            <div class="relative w-full sm:w-80">
              <i class="fa-solid fa-magnifying-glass absolute left-3.5 top-3 text-slate-400 text-xs"></i>
              <input type="text" id="search-companies-input" onkeyup="filterCompaniesTable(this.value)" placeholder="Buscar empresa, NIT, cliente o plan..." class="w-full pl-9 pr-3 py-2 bg-slate-50 border border-slate-200 rounded-xl text-xs font-semibold focus:bg-white focus:border-amber-500 transition">
            </div>

            <!-- Selector de Vista: Modo Lista / Modo Cuadrícula -->
            <div class="flex items-center bg-slate-100 p-1 rounded-xl border border-slate-200 shrink-0 shadow-2xs">
              <button onclick="setCompanyViewMode('list')" class="px-3 py-1.5 rounded-lg text-xs font-extrabold transition flex items-center gap-1.5 cursor-pointer ${companiesViewMode === 'list' ? 'bg-white text-slate-900 shadow-xs' : 'text-slate-500 hover:text-slate-800'}" title="Ver directorio en Modo Lista">
                <i class="fa-solid fa-list-ul"></i>
                <span class="hidden sm:inline">Lista</span>
              </button>
              <button onclick="setCompanyViewMode('grid')" class="px-3 py-1.5 rounded-lg text-xs font-extrabold transition flex items-center gap-1.5 cursor-pointer ${companiesViewMode === 'grid' ? 'bg-white text-slate-900 shadow-xs' : 'text-slate-500 hover:text-slate-800'}" title="Ver directorio en Modo Cuadrícula">
                <i class="fa-solid fa-table-cells-large"></i>
                <span class="hidden sm:inline">Cuadrícula</span>
              </button>
            </div>
          </div>
        </div>

        <!-- Filter Sub-Tabs for Companies / Contracts -->
        <div class="flex items-center gap-2 overflow-x-auto pb-1 text-xs font-bold">
          <button onclick="switchCompanyFilter('todas')" class="px-3.5 py-2 rounded-xl transition flex items-center gap-1.5 ${activeCompanyFilter === 'todas' ? 'bg-slate-900 text-white shadow-xs' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}">
            <span>Todas</span>
            <span class="text-[10px] px-1.5 py-0.5 rounded-full ${activeCompanyFilter === 'todas' ? 'bg-slate-700 text-white' : 'bg-slate-200 text-slate-700'}">${totalEmpresas}</span>
          </button>
          <button onclick="switchCompanyFilter('al_dia')" class="px-3.5 py-2 rounded-xl transition flex items-center gap-1.5 ${activeCompanyFilter === 'al_dia' ? 'bg-emerald-600 text-white shadow-xs' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}">
            <i class="fa-solid fa-circle-check text-emerald-400"></i>
            <span>Al Día</span>
            <span class="text-[10px] px-1.5 py-0.5 rounded-full ${activeCompanyFilter === 'al_dia' ? 'bg-emerald-700 text-white' : 'bg-slate-200 text-slate-700'}">${contractsAlDia}</span>
          </button>
          <button onclick="switchCompanyFilter('por_cobrar')" class="px-3.5 py-2 rounded-xl transition flex items-center gap-1.5 ${activeCompanyFilter === 'por_cobrar' ? 'bg-amber-600 text-white shadow-xs' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}">
            <i class="fa-solid fa-clock text-amber-300"></i>
            <span>Por Cobrar / Vencidas</span>
            <span class="text-[10px] px-1.5 py-0.5 rounded-full ${activeCompanyFilter === 'por_cobrar' ? 'bg-amber-700 text-white' : 'bg-slate-200 text-slate-700'}">${contractsPorCobrar + contractsVencidos}</span>
          </button>
          <button onclick="switchCompanyFilter('mensuales')" class="px-3.5 py-2 rounded-xl transition flex items-center gap-1.5 ${activeCompanyFilter === 'mensuales' ? 'bg-sky-600 text-white shadow-xs' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}">
            <i class="fa-solid fa-calendar-days text-sky-300"></i>
            <span>Contratos Mensuales</span>
          </button>
          <button onclick="switchCompanyFilter('anuales')" class="px-3.5 py-2 rounded-xl transition flex items-center gap-1.5 ${activeCompanyFilter === 'anuales' ? 'bg-purple-600 text-white shadow-xs' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}">
            <i class="fa-solid fa-calendar text-purple-300"></i>
            <span>Contratos Anuales</span>
          </button>
          <button onclick="switchCompanyFilter('inactivas')" class="px-3.5 py-2 rounded-xl transition flex items-center gap-1.5 ${activeCompanyFilter === 'inactivas' ? 'bg-slate-600 text-white shadow-xs' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}">
            <i class="fa-solid fa-ban text-slate-400"></i>
            <span>Inactivas / Retiradas</span>
          </button>
        </div>

        <!-- Grid of Companies -->
        <div id="companies-cards-container" class="${companiesViewMode === 'list' ? 'w-full' : 'grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5'}">
          ${renderCompanyCardsList(appData.companies)}
        </div>
      </div>
    </div>
  `;

  container.innerHTML = html;
}


function setCompanyViewMode(mode) {
  companiesViewMode = mode;
  renderEmpresas();
}

function switchCompanyFilter(filter) {
  activeCompanyFilter = filter;
  renderEmpresas();
}

function renderCompanyCardsList(companies) {
  if (!companies || companies.length === 0) {
    return `
      <div class="col-span-full py-12 px-6 text-center bg-white rounded-2xl border-2 border-dashed border-slate-200 shadow-sm">
        <div class="w-16 h-16 bg-amber-100 text-amber-600 rounded-full flex items-center justify-center mx-auto mb-4 text-2xl">
          <i class="fa-solid fa-building-circle-exclamation"></i>
        </div>
        <h4 class="text-base font-bold text-slate-800">No se encontraron empresas registradas</h4>
        <p class="text-xs text-slate-500 max-w-sm mx-auto mt-1 mb-5">
          Registre una empresa cliente para comenzar a administrar sus estanques, geomembranas, cosechas, contratos y cobros.
        </p>
        ${isMasterUser() ? `
          <button onclick="openModal('modal-new-company')" class="px-5 py-2.5 bg-amber-600 hover:bg-amber-500 text-white font-bold rounded-xl text-xs shadow-md transition inline-flex items-center gap-2 cursor-pointer">
            <i class="fa-solid fa-plus"></i> Registrar Empresa
          </button>
        ` : ''}
      </div>
    `;
  }

  const todayStr = new Date().toISOString().slice(0, 10);

  // Apply active sub-filter
  let filtered = companies.filter(c => {
    const contract = c.contract || {};
    const cycle = contract.billingCycle || 'mensual';
    const nextDate = contract.nextBillingDate;
    const diffDays = nextDate ? Math.ceil((new Date(nextDate) - new Date(todayStr)) / (1000 * 60 * 60 * 24)) : 999;

    if (activeCompanyFilter === 'al_dia') {
      return c.status === 'activo' && contract.status !== 'finalizado' && diffDays > 7;
    }
    if (activeCompanyFilter === 'por_cobrar') {
      return c.status === 'activo' && contract.status !== 'finalizado' && diffDays <= 7;
    }
    if (activeCompanyFilter === 'mensuales') {
      return cycle === 'mensual';
    }
    if (activeCompanyFilter === 'anuales') {
      return cycle === 'anual';
    }
    if (activeCompanyFilter === 'inactivas') {
      return c.status === 'inactivo' || contract.status === 'finalizado';
    }
    return true;
  });

  if (filtered.length === 0) {
    return `
      <div class="col-span-full py-10 px-6 text-center bg-white rounded-2xl border border-slate-200 shadow-sm">
        <p class="text-xs font-semibold text-slate-500">No hay empresas que coincidan con el filtro seleccionado.</p>
        <button onclick="switchCompanyFilter('todas')" class="mt-3 px-3.5 py-1.5 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-lg text-xs font-bold transition cursor-pointer">
          Ver todas las empresas
        </button>
      </div>
    `;
  }

  // =========================================================================
  // RENDER: MODO LISTA -> TABLA ESTRUCTURADA PROFESIONAL (Clean Data Table)
  // =========================================================================
  if (companiesViewMode === 'list') {
    const rowsHtml = filtered.map(comp => {
      const isCurrentActive = (appData.activeCompanyId === comp.id) || 
        (!appData.activeCompanyId && appData.farmInfo && appData.farmInfo.nit === comp.nit);

      const contract = comp.contract || {
        planName: "Asesoría Técnica Zootécnica",
        billingCycle: "mensual",
        feeAmount: 2000000,
        nextBillingDate: "2026-10-05",
        status: "al_dia"
      };

      const cycle = contract.billingCycle || 'mensual';
      const cycleLabel = cycle === 'anual' ? 'Anual' : cycle === 'trimestral' ? 'Trimestral' : cycle === 'semestral' ? 'Semestral' : 'Mensual';
      const fee = parseFloat(contract.feeAmount) || 0;
      const nextDate = contract.nextBillingDate;
      const diffDays = nextDate ? Math.ceil((new Date(nextDate) - new Date(todayStr)) / (1000 * 60 * 60 * 24)) : null;

      let billingBadge = '';
      if (contract.status === 'finalizado' || comp.status === 'inactivo') {
        billingBadge = `<span class="px-2 py-0.5 bg-slate-100 text-slate-600 rounded-full text-[10px] font-bold whitespace-nowrap"><i class="fa-solid fa-ban"></i> Finalizado</span>`;
      } else if (diffDays !== null && diffDays < 0) {
        billingBadge = `<span class="px-2 py-0.5 bg-rose-100 text-rose-800 border border-rose-300 rounded-full text-[10px] font-black inline-flex items-center gap-1 animate-pulse whitespace-nowrap"><i class="fa-solid fa-triangle-exclamation"></i> En Mora (${Math.abs(diffDays)}d)</span>`;
      } else if (diffDays !== null && diffDays <= 7) {
        billingBadge = `<span class="px-2 py-0.5 bg-amber-100 text-amber-800 border border-amber-300 rounded-full text-[10px] font-bold inline-flex items-center gap-1 whitespace-nowrap"><i class="fa-solid fa-clock"></i> Cobro en ${diffDays}d</span>`;
      } else {
        billingBadge = `<span class="px-2 py-0.5 bg-emerald-100 text-emerald-800 border border-emerald-300 rounded-full text-[10px] font-bold inline-flex items-center gap-1 whitespace-nowrap"><i class="fa-solid fa-circle-check text-emerald-600"></i> Al Día</span>`;
      }

      const payments = comp.billingPayments || [];
      const totalCobrado = payments.reduce((sum, p) => sum + (parseFloat(p.amount) || 0), 0);

      const users = Array.isArray(comp.assignedUsers) && comp.assignedUsers.length > 0 
        ? comp.assignedUsers 
        : [{ id: `USR-${comp.id}-1`, email: comp.clientEmail, name: comp.clientName, role: comp.userRole || 'lite' }];
      
      const hasMaster = users.some(u => u.role === 'master');
      const hasLite = users.some(u => u.role === 'lite');
      const hasSameEmailBoth = users.length >= 2 && users.some((u, i) => users.some((u2, i2) => i !== i2 && (u.email || '').toLowerCase() === (u2.email || '').toLowerCase() && u.role !== u2.role));

      let userRoleBadge = '';
      if (hasSameEmailBoth) {
        userRoleBadge = `<span class="px-2 py-0.5 bg-purple-100 text-purple-900 border border-purple-300 rounded-md text-[10px] font-black inline-flex items-center gap-1 whitespace-nowrap shadow-2xs"><i class="fa-solid fa-users"></i> Master + Lite</span>`;
      } else if (hasMaster && hasLite) {
        userRoleBadge = `<span class="px-2 py-0.5 bg-indigo-100 text-indigo-800 border border-indigo-200 rounded-md text-[10px] font-bold inline-flex items-center gap-1 whitespace-nowrap shadow-2xs"><i class="fa-solid fa-users"></i> Multi-User</span>`;
      } else if (hasMaster) {
        userRoleBadge = `<span class="px-2 py-0.5 bg-amber-100 text-amber-800 border border-amber-200 rounded-md text-[10px] font-bold inline-flex items-center gap-1 whitespace-nowrap shadow-2xs"><i class="fa-solid fa-crown text-amber-600"></i> Master</span>`;
      } else {
        userRoleBadge = `<span class="px-2 py-0.5 bg-sky-100 text-sky-800 border border-sky-200 rounded-md text-[10px] font-bold inline-flex items-center gap-1 whitespace-nowrap shadow-2xs"><i class="fa-solid fa-user-check text-sky-600"></i> Lite</span>`;
      }

      return `
        <tr class="transition ${isCurrentActive ? 'bg-amber-50/50 hover:bg-amber-50/80 font-medium' : 'hover:bg-slate-50/90'}">
          <!-- 1. Empresa & Identidad -->
          <td class="py-4 px-4 align-middle">
            <div class="flex items-center gap-3">
              <div class="w-10 h-10 rounded-xl ${isCurrentActive ? 'bg-gradient-to-tr from-amber-500 to-orange-500 text-white shadow-xs' : 'bg-slate-100 text-slate-700'} flex items-center justify-center text-base font-black shrink-0">
                <i class="fa-solid fa-fish"></i>
              </div>
              <div class="min-w-0">
                <div class="flex items-center gap-2 flex-wrap">
                  <span class="font-extrabold text-slate-900 text-sm hover:text-amber-600 transition cursor-pointer" onclick="openViewCompanyModal('${comp.id}')" title="Ver detalles de ${comp.name}">
                    ${comp.name}
                  </span>
                  <span class="text-[10px] font-bold text-slate-500 bg-slate-100 px-1.5 py-0.5 rounded border border-slate-200/60 uppercase whitespace-nowrap">
                    ${comp.id}
                  </span>
                </div>
                <div class="text-[11px] text-slate-500 flex items-center gap-2 mt-0.5 whitespace-nowrap">
                  <span>NIT: <strong class="text-slate-700 font-bold">${comp.nit}</strong></span>
                  ${comp.location ? `<span class="text-slate-400">• <i class="fa-solid fa-location-dot text-rose-500 text-[10px]"></i> ${comp.location}</span>` : ''}
                </div>
              </div>
            </div>
          </td>

          <!-- 2. Contacto & Representante -->
          <td class="py-4 px-4 align-middle whitespace-nowrap">
            <div class="font-bold text-slate-800 text-xs flex items-center gap-1.5">
              <i class="fa-solid fa-user text-slate-400 text-[11px]"></i>
              <span>${comp.clientName || 'Sin contacto'}</span>
            </div>
            <div class="text-[11px] text-slate-500 flex items-center gap-1.5 mt-0.5">
              <i class="fa-regular fa-envelope text-slate-400 text-[10px]"></i>
              <span class="truncate max-w-[180px]">${comp.clientEmail || 'Sin correo'}</span>
            </div>
          </td>

          <!-- 3. Infraestructura & Perfil -->
          <td class="py-4 px-4 align-middle whitespace-nowrap">
            <div class="flex items-center gap-1.5">
              <span class="inline-flex items-center gap-1 px-2 py-0.5 bg-sky-50 text-sky-800 border border-sky-200/80 rounded-md text-[11px] font-bold" title="Estanques en tierra">
                <i class="fa-solid fa-water text-sky-500 text-[10px]"></i> ${comp.earthenPondsCount || 10} Est.
              </span>
              <span class="inline-flex items-center gap-1 px-2 py-0.5 bg-cyan-50 text-cyan-800 border border-cyan-200/80 rounded-md text-[11px] font-bold" title="Geomembranas circulares">
                <i class="fa-solid fa-compact-disc text-cyan-500 text-[10px]"></i> ${comp.geomembranesCount || 3} Geos
              </span>
            </div>
            <div class="mt-1">
              ${userRoleBadge}
            </div>
          </td>

          <!-- 4. Contrato & Cobro -->
          <td class="py-4 px-4 align-middle whitespace-nowrap">
            <div class="font-extrabold text-slate-900 text-xs flex items-center gap-1.5 whitespace-nowrap">
              <i class="fa-solid fa-file-contract text-sky-600 text-xs"></i>
              <span>${cycleLabel}:</span>
              <span class="text-emerald-700 font-black">${formatCurrency(fee)}</span>
            </div>
            <div class="text-[11px] text-slate-500 flex items-center gap-2 mt-0.5 whitespace-nowrap font-medium">
              <span>Próx: <strong class="text-slate-700 font-bold">${nextDate ? formatDate(nextDate) : 'N/A'}</strong></span>
              <span>• Cobrado: <strong class="text-emerald-700 font-bold">${formatCurrency(totalCobrado)}</strong></span>
            </div>
          </td>

          <!-- 5. Estado -->
          <td class="py-4 px-4 align-middle text-center whitespace-nowrap">
            <div class="inline-flex flex-col items-center gap-1">
              ${isCurrentActive ? `
                <span class="px-2.5 py-0.5 bg-emerald-100 text-emerald-800 border border-emerald-300 rounded-full text-[10px] font-black uppercase tracking-wider flex items-center gap-1 shadow-2xs whitespace-nowrap">
                  <span class="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse"></span> EN SESIÓN
                </span>
              ` : comp.status === 'inactivo' ? `
                <span class="px-2.5 py-0.5 bg-slate-100 text-slate-600 rounded-full text-[10px] font-bold whitespace-nowrap">INACTIVA</span>
              ` : `
                <span class="px-2.5 py-0.5 bg-emerald-50 text-emerald-700 border border-emerald-200 rounded-full text-[10px] font-bold whitespace-nowrap flex items-center gap-1">
                  <span class="w-1.5 h-1.5 rounded-full bg-emerald-500"></span> ACTIVA
                </span>
              `}
              ${billingBadge}
            </div>
          </td>

          <!-- 6. Botones de Acción Organizados -->
          <td class="py-4 px-4 align-middle text-right whitespace-nowrap">
            <div class="inline-flex items-center justify-end gap-1.5">
              <!-- ENTRAR -->
              <button onclick="selectCompanyToManage('${comp.id}')" class="px-3.5 py-1.5 rounded-xl text-xs font-black flex items-center gap-1.5 transition cursor-pointer shadow-xs ${isCurrentActive ? 'bg-emerald-600 hover:bg-emerald-500 text-white shadow-emerald-600/20' : 'bg-slate-900 hover:bg-amber-600 text-white'}" title="${isCurrentActive ? 'Esta granja está en sesión activa' : 'Ingresar al panel de la granja'}">
                <i class="fa-solid fa-arrow-right-to-bracket ${isCurrentActive ? 'text-white' : 'text-amber-400'}"></i>
                <span>${isCurrentActive ? 'En Sesión' : 'Entrar'}</span>
              </button>

              <!-- VER -->
              <button onclick="openViewCompanyModal('${comp.id}')" class="px-2.5 py-1.5 bg-white hover:bg-sky-50 text-slate-700 hover:text-sky-700 border border-slate-200 hover:border-sky-300 font-bold rounded-xl text-xs flex items-center gap-1 transition cursor-pointer shadow-2xs" title="Ver ficha técnica completa">
                <i class="fa-solid fa-eye text-sky-600"></i>
                <span>Ver</span>
              </button>

              <!-- EDITAR -->
              <button onclick="openEditCompanyModal('${comp.id}')" class="px-2.5 py-1.5 bg-white hover:bg-amber-50 text-slate-700 hover:text-amber-700 border border-slate-200 hover:border-amber-300 font-bold rounded-xl text-xs flex items-center gap-1 transition cursor-pointer shadow-2xs" title="Editar empresa">
                <i class="fa-solid fa-pen-to-square text-amber-600"></i>
                <span>Editar</span>
              </button>

              <!-- USUARIOS -->
              <button onclick="openCompanyUsersModal('${comp.id}')" class="px-2.5 py-1.5 bg-white hover:bg-indigo-50 text-slate-700 hover:text-indigo-700 border border-slate-200 hover:border-indigo-300 font-bold rounded-xl text-xs flex items-center gap-1 transition cursor-pointer shadow-2xs" title="Usuarios asignados">
                <i class="fa-solid fa-users text-indigo-600"></i>
                <span>Usuarios (${users.length})</span>
              </button>

              <!-- COBROS -->
              <button onclick="openCompanyContractModal('${comp.id}')" class="px-2.5 py-1.5 bg-white hover:bg-purple-50 text-slate-700 hover:text-purple-700 border border-slate-200 hover:border-purple-300 font-bold rounded-xl text-xs flex items-center gap-1 transition cursor-pointer shadow-2xs" title="Contrato y pagos">
                <i class="fa-solid fa-receipt text-purple-600"></i>
                <span>Cobros</span>
              </button>

              ${isMasterUser() ? `
                <!-- REINICIAR (Master) -->
                <button onclick="resetCompanyData('${comp.id}')" class="w-8 h-8 flex items-center justify-center text-slate-400 hover:text-amber-600 hover:bg-amber-50 rounded-xl border border-slate-200 transition cursor-pointer" title="Reiniciar datos operativos de la empresa">
                  <i class="fa-solid fa-rotate-left text-xs"></i>
                </button>

                <!-- ELIMINAR (Master) -->
                <button onclick="deleteCompany('${comp.id}')" class="w-8 h-8 flex items-center justify-center text-slate-400 hover:text-rose-600 hover:bg-rose-50 rounded-xl border border-slate-200 transition cursor-pointer" title="Eliminar empresa definitivamente">
                  <i class="fa-regular fa-trash-can text-xs"></i>
                </button>
              ` : ''}
            </div>
          </td>
        </tr>
      `;
    }).join('');

    return `
      <div class="col-span-full bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
        <div class="overflow-x-auto">
          <table class="w-full text-left border-collapse min-w-[1020px]">
            <thead>
              <tr class="bg-slate-50/90 border-b border-slate-200 text-[11px] font-black text-slate-500 uppercase tracking-wider whitespace-nowrap">
                <th class="py-3.5 px-4">Empresa</th>
                <th class="py-3.5 px-4">Contacto</th>
                <th class="py-3.5 px-4">Capacidad</th>
                <th class="py-3.5 px-4">Contrato & Cobro</th>
                <th class="py-3.5 px-4 text-center">Estado</th>
                <th class="py-3.5 px-4 text-right">Acciones</th>
              </tr>
            </thead>
            <tbody class="divide-y divide-slate-100 text-xs">
              ${rowsHtml}
            </tbody>
          </table>
        </div>
      </div>
    `;
  }

  // =========================================================================
  // RENDER: MODO CUADRÍCULA (Grid Card)
  // =========================================================================
  return filtered.map(comp => {
    const isCurrentActive = (appData.activeCompanyId === comp.id) || 
      (!appData.activeCompanyId && appData.farmInfo && appData.farmInfo.nit === comp.nit);

    const contract = comp.contract || {
      planName: "Asesoría Técnica Zootécnica",
      billingCycle: "mensual",
      feeAmount: 2000000,
      nextBillingDate: "2026-10-05",
      status: "al_dia"
    };

    const cycle = contract.billingCycle || 'mensual';
    const cycleLabel = cycle === 'anual' ? 'Anual' : cycle === 'trimestral' ? 'Trimestral' : cycle === 'semestral' ? 'Semestral' : 'Mensual';
    const fee = parseFloat(contract.feeAmount) || 0;
    const nextDate = contract.nextBillingDate;
    const diffDays = nextDate ? Math.ceil((new Date(nextDate) - new Date(todayStr)) / (1000 * 60 * 60 * 24)) : null;

    let billingBadge = '';
    if (contract.status === 'finalizado' || comp.status === 'inactivo') {
      billingBadge = `<span class="px-2 py-0.5 bg-slate-200 text-slate-700 rounded-full text-[10px] font-bold whitespace-nowrap"><i class="fa-solid fa-ban"></i> Finalizado</span>`;
    } else if (diffDays !== null && diffDays < 0) {
      billingBadge = `<span class="px-2 py-0.5 bg-rose-100 text-rose-800 border border-rose-300 rounded-full text-[10px] font-black inline-flex items-center gap-1 animate-pulse whitespace-nowrap"><i class="fa-solid fa-triangle-exclamation"></i> En Mora (${Math.abs(diffDays)}d)</span>`;
    } else if (diffDays !== null && diffDays <= 7) {
      billingBadge = `<span class="px-2 py-0.5 bg-amber-100 text-amber-800 border border-amber-300 rounded-full text-[10px] font-bold inline-flex items-center gap-1 whitespace-nowrap"><i class="fa-solid fa-clock"></i> Cobro en ${diffDays}d</span>`;
    } else {
      billingBadge = `<span class="px-2 py-0.5 bg-emerald-100 text-emerald-800 border border-emerald-300 rounded-full text-[10px] font-bold inline-flex items-center gap-1 whitespace-nowrap"><i class="fa-solid fa-circle-check text-emerald-600"></i> Al Día</span>`;
    }

    const payments = comp.billingPayments || [];
    const totalCobrado = payments.reduce((sum, p) => sum + (parseFloat(p.amount) || 0), 0);

    const users = Array.isArray(comp.assignedUsers) && comp.assignedUsers.length > 0 
      ? comp.assignedUsers 
      : [{ id: `USR-${comp.id}-1`, email: comp.clientEmail, name: comp.clientName, role: comp.userRole || 'lite' }];
    
    const hasMaster = users.some(u => u.role === 'master');
    const hasLite = users.some(u => u.role === 'lite');
    const hasSameEmailBoth = users.length >= 2 && users.some((u, i) => users.some((u2, i2) => i !== i2 && (u.email || '').toLowerCase() === (u2.email || '').toLowerCase() && u.role !== u2.role));

    let userRoleBadge = '';
    if (hasSameEmailBoth) {
      userRoleBadge = `<span class="px-2 py-0.5 bg-purple-100 text-purple-900 border border-purple-300 rounded-full text-[10px] font-black inline-flex items-center gap-1 shadow-2xs whitespace-nowrap"><i class="fa-solid fa-users"></i> Master + Lite</span>`;
    } else if (hasMaster && hasLite) {
      userRoleBadge = `<span class="px-2 py-0.5 bg-indigo-100 text-indigo-800 border border-indigo-200 rounded-full text-[10px] font-bold inline-flex items-center gap-1 shadow-2xs whitespace-nowrap"><i class="fa-solid fa-users"></i> Multi-User</span>`;
    } else if (hasMaster) {
      userRoleBadge = `<span class="px-2 py-0.5 bg-amber-100 text-amber-800 border border-amber-200 rounded-full text-[10px] font-bold inline-flex items-center gap-1 shadow-2xs whitespace-nowrap"><i class="fa-solid fa-crown text-amber-600"></i> Master</span>`;
    } else {
      userRoleBadge = `<span class="px-2 py-0.5 bg-sky-100 text-sky-800 border border-sky-200 rounded-full text-[10px] font-bold inline-flex items-center gap-1 shadow-2xs whitespace-nowrap"><i class="fa-solid fa-user-check text-sky-600"></i> Lite</span>`;
    }

    return `
      <div class="bg-slate-50/90 hover:bg-white rounded-2xl p-4 border ${isCurrentActive ? 'border-amber-400 ring-2 ring-amber-400/20 shadow-md bg-amber-50/20' : 'border-slate-200 shadow-2xs'} transition hover-lift flex flex-col justify-between overflow-hidden">
        <div>
          <!-- Top Toolbar: ID, Status Badge & Quick Actions -->
          <div class="flex items-center justify-between gap-2 mb-2.5 pb-2 border-b border-slate-200/60">
            <div class="flex items-center gap-2">
              <span class="text-[10px] font-black text-slate-500 bg-slate-200/80 px-2 py-0.5 rounded-md uppercase tracking-wider">${comp.id}</span>
              ${isCurrentActive ? `
                <span class="px-2 py-0.5 bg-emerald-100 text-emerald-800 border border-emerald-300 rounded-full text-[10px] font-black uppercase tracking-wider flex items-center gap-1 shadow-2xs whitespace-nowrap">
                  <span class="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse"></span> ACTIVA
                </span>
              ` : comp.status === 'inactivo' ? `
                <span class="px-2 py-0.5 bg-slate-200 text-slate-600 rounded-full text-[10px] font-bold whitespace-nowrap">INACTIVA</span>
              ` : `
                <span class="px-2 py-0.5 bg-emerald-50 text-emerald-700 border border-emerald-200 rounded-full text-[10px] font-bold whitespace-nowrap flex items-center gap-1">
                  <span class="w-1.5 h-1.5 rounded-full bg-emerald-500"></span> ACTIVA
                </span>
              `}
            </div>

            <!-- Quick Action Icons -->
            <div class="flex items-center gap-1">
              <button onclick="openViewCompanyModal('${comp.id}')" title="Ver ficha técnica de la empresa" class="w-7 h-7 flex items-center justify-center text-slate-500 hover:text-sky-700 hover:bg-sky-100/80 rounded-lg border border-slate-200/80 transition cursor-pointer">
                <i class="fa-solid fa-eye text-xs"></i>
              </button>
              ${isMasterUser() ? `
                <button onclick="openEditCompanyModal('${comp.id}')" title="Editar datos de la empresa" class="w-7 h-7 flex items-center justify-center text-slate-500 hover:text-amber-700 hover:bg-amber-100/80 rounded-lg border border-slate-200/80 transition cursor-pointer">
                  <i class="fa-solid fa-pen-to-square text-xs"></i>
                </button>
                <button onclick="resetCompanyData('${comp.id}')" title="Reiniciar datos de la empresa (iniciar de cero)" class="w-7 h-7 flex items-center justify-center text-slate-400 hover:text-rose-600 hover:bg-rose-50 rounded-lg border border-slate-200/80 transition cursor-pointer">
                  <i class="fa-solid fa-rotate-left text-xs"></i>
                </button>
                <button onclick="deleteCompany('${comp.id}')" title="Eliminar empresa definitivamente" class="w-7 h-7 flex items-center justify-center text-slate-400 hover:text-rose-600 hover:bg-rose-50 rounded-lg border border-slate-200/80 transition cursor-pointer">
                  <i class="fa-regular fa-trash-can text-xs"></i>
                </button>
              ` : ''}
            </div>
          </div>

          <!-- Full Company Name Header -->
          <div class="flex items-start gap-2.5 mb-2.5">
            <div class="w-9 h-9 rounded-xl ${isCurrentActive ? 'bg-gradient-to-tr from-amber-500 to-orange-500 text-white shadow-xs' : 'bg-slate-200 text-slate-700'} flex items-center justify-center text-sm font-black shrink-0 mt-0.5">
              <i class="fa-solid fa-fish"></i>
            </div>
            <div class="min-w-0 flex-1">
              <h3 class="font-extrabold text-slate-900 text-sm sm:text-base leading-snug break-words" title="${comp.name}">
                ${comp.name}
              </h3>
              <div class="text-[11px] text-slate-500 flex flex-wrap items-center gap-x-2 gap-y-0.5 mt-0.5 font-medium">
                <span>NIT: <strong class="text-slate-700 font-bold">${comp.nit}</strong></span>
                ${comp.location ? `<span>• <i class="fa-solid fa-location-dot text-rose-500 text-[10px]"></i> ${comp.location}</span>` : ''}
              </div>
            </div>
          </div>

          <!-- Client & Farm Contact Card -->
          <div class="bg-white p-2.5 rounded-xl border border-slate-200/70 text-xs mb-2.5 space-y-1.5">
            <div class="flex items-center justify-between gap-2">
              <div class="flex items-center gap-1.5 truncate text-slate-800 font-bold text-xs">
                <i class="fa-solid fa-user-tie text-slate-400 text-xs"></i>
                <span class="truncate">${comp.clientName || 'Sin contacto asignado'}</span>
              </div>
              <div class="shrink-0">${userRoleBadge}</div>
            </div>

            <div class="flex items-center justify-between text-[11px] text-slate-500 pt-1 border-t border-slate-100">
              <div class="flex items-center gap-1.5 truncate max-w-[62%]">
                <i class="fa-solid fa-envelope text-slate-400 text-[10px]"></i>
                <span class="truncate font-medium">${comp.clientEmail || 'Sin correo'}</span>
              </div>
              <div class="flex items-center gap-1.5 shrink-0 text-[10px] font-extrabold">
                <span class="text-sky-800 bg-sky-50 px-1.5 py-0.5 rounded border border-sky-100" title="Estanques en tierra">
                  <i class="fa-solid fa-water text-sky-500 text-[9px]"></i> ${comp.earthenPondsCount || 10} Est.
                </span>
                <span class="text-cyan-800 bg-cyan-50 px-1.5 py-0.5 rounded border border-cyan-100" title="Geomembranas">
                  <i class="fa-solid fa-compact-disc text-cyan-500 text-[9px]"></i> ${comp.geomembranesCount || 3} Geos
                </span>
              </div>
            </div>
          </div>

          <!-- Compact Contract & Billing Strip -->
          <div class="bg-gradient-to-br from-sky-50/80 to-slate-50 px-3 py-2 rounded-xl border border-sky-200/70 mb-3 text-xs">
            <div class="flex items-center justify-between gap-1">
              <span class="text-[11px] font-black text-sky-950 uppercase tracking-wider flex items-center gap-1 whitespace-nowrap">
                <i class="fa-solid fa-file-contract text-sky-600"></i> ${cycleLabel}: <span class="font-black text-slate-900">${formatCurrency(fee)}</span>
              </span>
              ${billingBadge}
            </div>
            <div class="flex items-center justify-between text-[10px] text-slate-500 mt-1 pt-1 border-t border-sky-100">
              <span>Próx: <strong class="text-slate-800 font-bold">${nextDate ? formatDate(nextDate) : 'N/A'}</strong></span>
              <span>Cobrado: <strong class="text-emerald-700 font-bold">${formatCurrency(totalCobrado)}</strong></span>
            </div>
          </div>
        </div>

        <!-- Action Buttons Grid -->
        <div class="pt-2.5 border-t border-slate-200/70 space-y-1.5">
          <div class="grid grid-cols-2 gap-1.5">
            <button onclick="selectCompanyToManage('${comp.id}')" class="py-2 px-3 rounded-xl text-xs font-black flex items-center justify-center gap-1.5 transition cursor-pointer shadow-xs ${isCurrentActive ? 'bg-emerald-600 hover:bg-emerald-500 text-white' : 'bg-slate-900 hover:bg-amber-600 text-white'}">
              <i class="fa-solid fa-arrow-right-to-bracket ${isCurrentActive ? 'text-white' : 'text-amber-400'}"></i>
              <span>${isCurrentActive ? 'En Sesión' : 'Entrar'}</span>
            </button>
            <button onclick="openViewCompanyModal('${comp.id}')" class="py-2 px-3 rounded-xl text-xs font-bold bg-white hover:bg-sky-50 text-slate-800 hover:text-sky-700 border border-slate-200 flex items-center justify-center gap-1.5 transition cursor-pointer shadow-2xs">
              <i class="fa-solid fa-eye text-sky-600"></i>
              <span>Ver</span>
            </button>
          </div>

          ${isMasterUser() ? `
            <div class="grid grid-cols-3 gap-1">
              <button onclick="openEditCompanyModal('${comp.id}')" class="py-1.5 px-1.5 rounded-lg text-[11px] font-bold bg-white hover:bg-amber-50 text-amber-900 border border-slate-200 shadow-2xs flex items-center justify-center gap-1 transition cursor-pointer truncate" title="Editar empresa">
                <i class="fa-solid fa-pen-to-square text-amber-600 text-[10px]"></i>
                <span class="truncate">Editar</span>
              </button>

              <button onclick="openCompanyUsersModal('${comp.id}')" class="py-1.5 px-1.5 rounded-lg text-[11px] font-bold bg-white hover:bg-indigo-50 text-indigo-900 border border-slate-200 shadow-2xs flex items-center justify-center gap-1 transition cursor-pointer truncate" title="Administrar usuarios">
                <i class="fa-solid fa-users text-indigo-600 text-[10px]"></i>
                <span class="truncate">Users (${users.length})</span>
              </button>

              <button onclick="openCompanyContractModal('${comp.id}')" class="py-1.5 px-1.5 rounded-lg text-[11px] font-bold bg-white hover:bg-purple-50 text-purple-900 border border-slate-200 shadow-2xs flex items-center justify-center gap-1 transition cursor-pointer truncate" title="Gestionar contrato y cobros">
                <i class="fa-solid fa-receipt text-purple-600 text-[10px]"></i>
                <span class="truncate">Cobros</span>
              </button>
            </div>
          ` : ''}
        </div>
      </div>
    `;
  }).join('');
}

function openViewCompanyModal(companyId) {
  const comp = (appData.companies || []).find(c => c.id === companyId);
  if (!comp) return;

  const modal = document.getElementById('modal-view-company');
  const title = document.getElementById('view-company-modal-title');
  const badge = document.getElementById('view-company-modal-badge');
  const subtitle = document.getElementById('view-company-modal-subtitle');
  const content = document.getElementById('view-company-modal-content');
  const footer = document.getElementById('view-company-modal-footer');

  if (!modal || !content) return;

  const isCurrentActive = (appData.activeCompanyId === comp.id);
  const contract = comp.contract || {};
  const cycle = contract.billingCycle || 'mensual';
  const cycleLabel = cycle === 'anual' ? 'Anual' : cycle === 'trimestral' ? 'Trimestral' : cycle === 'semestral' ? 'Semestral' : 'Mensual';
  const fee = parseFloat(contract.feeAmount) || 0;
  const payments = comp.billingPayments || [];
  const totalCobrado = payments.reduce((sum, p) => sum + (parseFloat(p.amount) || 0), 0);
  const users = Array.isArray(comp.assignedUsers) ? comp.assignedUsers : [];

  if (title) title.innerText = comp.name;
  if (badge) {
    if (isCurrentActive) {
      badge.className = 'px-2.5 py-0.5 rounded-full text-[10px] font-black uppercase bg-emerald-400 text-slate-950 shadow-xs';
      badge.innerText = 'EN SESIÓN ACTIVA';
    } else if (comp.status === 'inactivo') {
      badge.className = 'px-2.5 py-0.5 rounded-full text-[10px] font-black uppercase bg-slate-600 text-slate-200';
      badge.innerText = 'INACTIVA';
    } else {
      badge.className = 'px-2.5 py-0.5 rounded-full text-[10px] font-black uppercase bg-emerald-500/20 text-emerald-300 border border-emerald-400/30';
      badge.innerText = 'ACTIVA';
    }
  }
  if (subtitle) {
    subtitle.innerText = `NIT: ${comp.nit} • ID: ${comp.id} • ${comp.location || 'Colombia'}`;
  }

  const store = (appData.companyStores && appData.companyStores[comp.id]) ? appData.companyStores[comp.id] : null;
  const activeBatches = store && Array.isArray(store.batches) ? store.batches.filter(b => b.status === 'activo').length : 0;

  content.innerHTML = `
    <!-- General Info Cards -->
    <div class="grid grid-cols-1 sm:grid-cols-2 gap-3.5">
      <!-- Card 1: Contacto Comercial -->
      <div class="bg-slate-50 p-4 rounded-2xl border border-slate-200 space-y-2">
        <div class="flex items-center gap-2 text-slate-900 font-extrabold text-xs">
          <i class="fa-solid fa-address-card text-sky-600"></i>
          <span>Información de Contacto</span>
        </div>
        <div class="space-y-1.5 text-slate-600 text-xs">
          <div><strong class="text-slate-800">Representante:</strong> ${comp.clientName || 'N/A'}</div>
          <div><strong class="text-slate-800">Correo Electrónico:</strong> ${comp.clientEmail || 'N/A'}</div>
          <div><strong class="text-slate-800">Teléfono / WhatsApp:</strong> ${comp.phone || 'N/A'}</div>
          <div><strong class="text-slate-800">Ubicación de Granja:</strong> ${comp.location || 'N/A'}</div>
        </div>
      </div>

      <!-- Card 2: Capacidad e Infraestructura -->
      <div class="bg-slate-50 p-4 rounded-2xl border border-slate-200 space-y-2">
        <div class="flex items-center gap-2 text-slate-900 font-extrabold text-xs">
          <i class="fa-solid fa-water text-cyan-600"></i>
          <span>Capacidad Instalada & Lotes</span>
        </div>
        <div class="space-y-2 text-slate-600 text-xs">
          <div class="flex items-center justify-between">
            <span>Estanques en Tierra:</span>
            <span class="font-extrabold text-sky-800 bg-sky-100 px-2 py-0.5 rounded-md">${comp.earthenPondsCount || 10} estanques</span>
          </div>
          <div class="flex items-center justify-between">
            <span>Geomembranas Circulares:</span>
            <span class="font-extrabold text-cyan-800 bg-cyan-100 px-2 py-0.5 rounded-md">${comp.geomembranesCount || 3} geos</span>
          </div>
          <div class="flex items-center justify-between">
            <span>Lotes / Siembras Activas:</span>
            <span class="font-extrabold text-emerald-800 bg-emerald-100 px-2 py-0.5 rounded-md">${activeBatches} lotes en curso</span>
          </div>
          <div><strong class="text-slate-800">Asesor Técnico:</strong> ${comp.technicalManager || 'DC Asesorías'}</div>
        </div>
      </div>
    </div>

    <!-- Contrato y Facturación -->
    <div class="bg-gradient-to-br from-sky-50 via-slate-50 to-emerald-50/40 p-4 rounded-2xl border border-sky-200/80 space-y-3">
      <div class="flex items-center justify-between flex-wrap gap-2">
        <div class="flex items-center gap-2 text-slate-900 font-extrabold text-xs">
          <i class="fa-solid fa-file-invoice-dollar text-emerald-600 text-sm"></i>
          <span>Contrato & Plan de Facturación</span>
        </div>
        <span class="px-2.5 py-1 bg-white border border-sky-200 rounded-lg text-xs font-black text-sky-900 shadow-2xs">
          ${contract.planName || 'Asesoría Zootécnica'}
        </span>
      </div>

      <div class="grid grid-cols-2 sm:grid-cols-4 gap-2 text-center">
        <div class="bg-white p-2.5 rounded-xl border border-slate-200 shadow-2xs">
          <div class="text-[10px] text-slate-400 font-bold uppercase">Tarifa (${cycleLabel})</div>
          <div class="text-sm font-black text-slate-900 mt-0.5">${formatCurrency(fee)}</div>
        </div>
        <div class="bg-white p-2.5 rounded-xl border border-slate-200 shadow-2xs">
          <div class="text-[10px] text-slate-400 font-bold uppercase">Día de Corte</div>
          <div class="text-sm font-black text-slate-900 mt-0.5">Día ${contract.billingDay || 5}</div>
        </div>
        <div class="bg-white p-2.5 rounded-xl border border-slate-200 shadow-2xs">
          <div class="text-[10px] text-slate-400 font-bold uppercase">Próximo Cobro</div>
          <div class="text-sm font-black text-sky-700 mt-0.5">${contract.nextBillingDate ? formatDate(contract.nextBillingDate) : 'N/A'}</div>
        </div>
        <div class="bg-white p-2.5 rounded-xl border border-slate-200 shadow-2xs">
          <div class="text-[10px] text-slate-400 font-bold uppercase">Total Cobrado</div>
          <div class="text-sm font-black text-emerald-700 mt-0.5">${formatCurrency(totalCobrado)}</div>
        </div>
      </div>

      ${contract.notes ? `
        <div class="text-[11px] text-slate-600 bg-white/80 p-2.5 rounded-xl border border-slate-200">
          <strong class="text-slate-800">Notas de Contrato:</strong> ${contract.notes}
        </div>
      ` : ''}
    </div>

    <!-- Usuarios Asignados -->
    <div class="space-y-2">
      <div class="flex items-center justify-between">
        <span class="font-extrabold text-slate-900 text-xs flex items-center gap-1.5">
          <i class="fa-solid fa-users text-indigo-600"></i> Usuarios Registrados con Acceso (${users.length})
        </span>
        <button onclick="closeModal('modal-view-company'); openCompanyUsersModal('${comp.id}')" class="text-xs font-bold text-indigo-600 hover:text-indigo-800 flex items-center gap-1 cursor-pointer">
          <i class="fa-solid fa-user-plus text-[10px]"></i> Administrar Usuarios
        </button>
      </div>

      <div class="grid grid-cols-1 sm:grid-cols-2 gap-2">
        ${users.length === 0 ? `
          <div class="col-span-full text-slate-400 text-xs py-2 text-center bg-slate-50 rounded-xl">Sin usuarios configurados</div>
        ` : users.map(u => `
          <div class="p-2.5 bg-slate-50 rounded-xl border border-slate-200 flex items-center justify-between gap-2">
            <div class="truncate">
              <div class="font-bold text-slate-800 truncate">${u.name || comp.clientName}</div>
              <div class="text-[11px] text-slate-500 truncate">${u.email}</div>
            </div>
            <span class="px-2 py-0.5 rounded-full text-[10px] font-black shrink-0 ${u.role === 'master' ? 'bg-amber-100 text-amber-800 border border-amber-200' : 'bg-sky-100 text-sky-800 border border-sky-200'}">
              ${u.role === 'master' ? '👑 Master' : '👁️ Lite'}
            </span>
          </div>
        `).join('')}
      </div>
    </div>
  `;

  if (footer) {
    footer.innerHTML = `
      <div class="flex items-center gap-2">
        <button onclick="closeModal('modal-view-company'); openEditCompanyModal('${comp.id}')" class="px-3.5 py-2 bg-slate-100 hover:bg-amber-50 text-slate-700 hover:text-amber-700 border border-slate-200 font-bold rounded-xl text-xs flex items-center gap-1.5 transition cursor-pointer">
          <i class="fa-solid fa-pen-to-square text-amber-600"></i> Editar Datos
        </button>
        <button onclick="closeModal('modal-view-company'); openCompanyContractModal('${comp.id}')" class="px-3.5 py-2 bg-slate-100 hover:bg-purple-50 text-slate-700 hover:text-purple-700 border border-slate-200 font-bold rounded-xl text-xs flex items-center gap-1.5 transition cursor-pointer">
          <i class="fa-solid fa-receipt text-purple-600"></i> Cobros & Pagos
        </button>
      </div>
      <div class="flex items-center gap-2">
        <button onclick="closeModal('modal-view-company')" class="px-4 py-2 bg-slate-200 hover:bg-slate-300 text-slate-700 font-bold rounded-xl text-xs transition cursor-pointer">
          Cerrar
        </button>
        <button onclick="closeModal('modal-view-company'); selectCompanyToManage('${comp.id}')" class="px-5 py-2 bg-emerald-600 hover:bg-emerald-500 text-white font-extrabold rounded-xl text-xs flex items-center gap-2 shadow-sm transition cursor-pointer">
          <i class="fa-solid fa-arrow-right-to-bracket"></i>
          <span>${isCurrentActive ? 'Granja en Sesión' : 'Entrar a la Granja'}</span>
        </button>
      </div>
    `;
  }

  openModal('modal-view-company');
}


function filterCompaniesTable(query) {
  const term = (query || '').toLowerCase().trim();
  const filtered = (appData.companies || []).filter(c => {
    const contract = c.contract || {};
    return (c.name || '').toLowerCase().includes(term) ||
           (c.nit || '').toLowerCase().includes(term) ||
           (c.clientName || '').toLowerCase().includes(term) ||
           (c.location || '').toLowerCase().includes(term) ||
           (contract.planName || '').toLowerCase().includes(term);
  });
  const container = document.getElementById('companies-cards-container');
  if (container) {
    container.innerHTML = renderCompanyCardsList(filtered);
  }
}

function selectCompanyToManage(companyId) {
  const comp = (appData.companies || []).find(c => c.id === companyId) || (appData.companies && appData.companies[0]);
  if (!comp) return;

  // 1. Establecer la nueva empresa activa
  appData.activeCompanyId = comp.id;
  if (!appData.companyStores) appData.companyStores = {};

  // 2. Garantizar que el almacén de destino exista y esté hidratado con datos completos
  const defaultEmpStore = (DEFAULT_DATA.companyStores && DEFAULT_DATA.companyStores[comp.id]) ? DEFAULT_DATA.companyStores[comp.id] : null;
  if (!appData.companyStores[comp.id]) {
    if (defaultEmpStore) {
      appData.companyStores[comp.id] = JSON.parse(JSON.stringify(defaultEmpStore));
    } else {
      appData.companyStores[comp.id] = PiscicolaStorage.createBlankCompanyStore(comp);
    }
  } else {
    // Si existe pero está vacío y tenemos defaultEmpStore con datos, restaurar inmediatamente
    const st = appData.companyStores[comp.id];
    if (defaultEmpStore && (!st.batches || st.batches.length === 0)) {
      appData.companyStores[comp.id] = JSON.parse(JSON.stringify(defaultEmpStore));
    } else {
      PiscicolaStorage.safeHydrateCompanyStore(appData.companyStores[comp.id], comp);
    }
  }

  // 3. Cargar dinámicamente todos los módulos de la empresa seleccionada en appData
  const store = appData.companyStores[comp.id];

  appData.farmInfo = {
    ...(store.farmInfo || {}),
    name: comp.name,
    nit: comp.nit,
    location: comp.location,
    technicalManager: comp.technicalManager || (store.farmInfo && store.farmInfo.technicalManager) || "Ing. Carlos Mendoza (DC Asesorías)",
    currency: "COP ($)",
    lastUpdate: new Date().toISOString()
  };

  PiscicolaStorage.getCompanyModuleKeys().forEach(mod => {
    if (store[mod] !== undefined) {
      appData[mod] = JSON.parse(JSON.stringify(store[mod]));
    } else {
      appData[mod] = [];
    }
  });

  PiscicolaStorage.save(appData);

  // Switch to dashboard
  switchTab('dashboard');
}

// Full Clean Deletion of Any Company
function deleteCompany(companyId) {
  if (!isMasterUser()) {
    showNotification('Acceso de Solo Lectura: Tu cuenta es de perfil Lite. No tienes permisos para registrar o modificar datos.', 'warning');
    return;
  }
  const comp = (appData.companies || []).find(c => c.id === companyId);
  if (!comp) return;

  const isDemo = (companyId === 'EMP-001');
  const confirmMsg = isDemo
    ? `⚠️ ATENCIÓN: Va a eliminar la empresa "${comp.name}" (EMP-001).\n\nEsta acción borrará irreversiblemente todos sus estanques, geomembranas, lotes, registros de alimentación, inventarios y contratos asociados.\n\n¿Confirma que desea eliminarla por completo de la plataforma?`
    : `⚠️ ATENCIÓN: ¿Confirma que desea eliminar definitivamente la empresa "${comp.name}" (${comp.nit})?\n\nEsta acción borrará por completo sus estanques, geomembranas, cosechas, kárdex y contratos.\n\n¿Desea continuar y eliminarla de forma permanente?`;

  if (!confirm(confirmMsg)) return;

  // 1. Remove from companies array
  appData.companies = appData.companies.filter(c => c.id !== companyId);

  // 2. Remove isolated store
  if (appData.companyStores && appData.companyStores[companyId]) {
    delete appData.companyStores[companyId];
  }

  // 3. Fallback active company if the deleted one was selected
  if (appData.activeCompanyId === companyId) {
    if (appData.companies.length > 0) {
      selectCompanyToManage(appData.companies[0].id);
    } else {
      appData.activeCompanyId = null;
      PiscicolaStorage.save(appData);
    }
  } else {
    PiscicolaStorage.save(appData);
  }

  PiscicolaStorage.syncDelete('companies', companyId);
  closeModal('modal-company-contract');
  applyUserPermissions();
  renderEmpresas();

  showNotification(`La empresa "${comp.name}" ha sido eliminada del sistema.`, 'success');
}

// Reiniciar a cero toda la información operativa de una empresa
function resetCompanyData(companyId) {
  if (!isMasterUser()) {
    showNotification('Acceso Denegado: Solo el Administrador Master puede reiniciar la información de una empresa.', 'warning');
    return;
  }

  const comp = (appData.companies || []).find(c => c.id === companyId);
  if (!comp) {
    showNotification('No se encontró la empresa especificada.', 'error');
    return;
  }

  const confirmMsg = `⚠️ ATENCIÓN - REINICIO TOTAL DE DATOS\n\n` +
    `¿Estás seguro de que deseas REINICIAR y BORRAR TODA la información de "${comp.name}" (${comp.nit})?\n\n` +
    `Esta acción eliminará definitivamente:\n` +
    `• Todos los lotes y siembras activas o finalizadas\n` +
    `• Todos los traslados y desdobles\n` +
    `• Todo el historial de alimentación y biometrías\n` +
    `• Todos los tratamientos sanitarios y muestreos de calidad de agua\n` +
    `• Facturas de compras, gastos y nómina\n` +
    `• Registros de inventario, cosechas y ventas\n\n` +
    `Los estanques y geomembranas quedarán limpios y en estado "EN DESCANSO", listos para iniciar desde cero.\n\n` +
    `Escribe la palabra REINICIAR para confirmar:`;

  const input = prompt(confirmMsg);
  if (!input || input.trim().toUpperCase() !== 'REINICIAR') {
    if (input !== null) {
      showNotification('Operación cancelada. Debes escribir exactamente "REINICIAR" para ejecutar el borrado.', 'info');
    }
    return;
  }

  // 1. Reset or clean units (preserve physical ponds & geos, set activeBatchId to null and status to descanso)
  let cleanUnits = [];
  const existingStore = (appData.companyStores && appData.companyStores[companyId]) ? appData.companyStores[companyId] : null;

  if (existingStore && Array.isArray(existingStore.units) && existingStore.units.length > 0) {
    cleanUnits = existingStore.units.map(u => ({
      ...u,
      status: 'descanso',
      activeBatchId: null
    }));
  } else {
    cleanUnits = generateBlankUnits(comp.earthenPondsCount || 10, comp.geomembranesCount || 3);
  }

  // 2. Clear isolated company store
  if (!appData.companyStores) appData.companyStores = {};
  const blankStore = PiscicolaStorage.createBlankCompanyStore(comp);
  blankStore.units = cleanUnits;
  if (comp.id === 'EMP-001') {
    blankStore.employees = [...(DEFAULT_DATA.employees || [])];
    blankStore.suppliers = JSON.parse(JSON.stringify(DEFAULT_DATA.suppliers || []));
    blankStore.clients = JSON.parse(JSON.stringify(DEFAULT_DATA.clients || []));
    blankStore.equipment = JSON.parse(JSON.stringify(DEFAULT_DATA.equipment || []));
    blankStore.maintenanceLogs = JSON.parse(JSON.stringify(DEFAULT_DATA.maintenanceLogs || []));
  }
  appData.companyStores[companyId] = blankStore;

  // 3. If this company is currently loaded in active session, sync live arrays immediately
  if (appData.activeCompanyId === companyId || (!appData.activeCompanyId && appData.farmInfo && appData.farmInfo.nit === comp.nit)) {
    PiscicolaStorage.getCompanyModuleKeys().forEach(mod => {
      appData[mod] = blankStore[mod];
    });
  }

  // 4. Save and persist
  PiscicolaStorage.save(appData);

  // 5. Re-render UI & notify
  renderEmpresas();
  showNotification(`¡La empresa "${comp.name}" ha sido reiniciada a cero con éxito! Toda la información operativa ha sido borrada y sus unidades están en descanso listas para nuevas siembras.`, 'success');
}

// ----------------------------------------------------
// 0.4. MODAL: EDITAR DATOS DE LA EMPRESA PISCÍCOLA
// ----------------------------------------------------
function openEditCompanyModal(companyId) {
  const comp = (appData.companies || []).find(c => c.id === companyId);
  if (!comp) {
    showNotification('No se encontró la información de la empresa seleccionada.', 'error');
    return;
  }

  const setVal = (id, val) => {
    const el = document.getElementById(id);
    if (el) el.value = (val !== undefined && val !== null) ? val : '';
  };

  setVal('edit-comp-id', comp.id);
  setVal('edit-comp-name', comp.name || '');
  setVal('edit-comp-nit', comp.nit || '');
  setVal('edit-comp-location', comp.location || '');
  setVal('edit-comp-client', comp.clientName || '');
  setVal('edit-comp-email', comp.clientEmail || '');
  setVal('edit-comp-user-role', comp.userRole || 'lite');
  const primaryUser = (Array.isArray(comp.assignedUsers) && comp.assignedUsers[0]) || {};
  setVal('edit-comp-password', primaryUser.password || '123456');
  setVal('edit-comp-phone', comp.phone || '');
  setVal('edit-comp-tech', comp.technicalManager || 'Ing. Carlos Mendoza (DC Asesorías)');
  setVal('edit-comp-status', comp.status || 'activo');
  setVal('edit-comp-ponds', comp.earthenPondsCount || 10);
  setVal('edit-comp-geos', comp.geomembranesCount || 3);
  setVal('edit-comp-notes', comp.notes || '');

  const contract = comp.contract || {};
  setVal('edit-comp-contract-cycle', contract.billingCycle || 'mensual');
  setVal('edit-comp-contract-fee', contract.feeAmount || 2000000);
  setVal('edit-comp-contract-billing-day', contract.billingDay || 5);
  setVal('edit-comp-contract-next', contract.nextBillingDate ? contract.nextBillingDate.slice(0, 10) : '');

  openModal('modal-edit-company');
}

function openEditActiveCompanyModal() {
  const currentId = appData.activeCompanyId || (appData.companies && appData.companies[0] ? appData.companies[0].id : null);
  if (currentId) {
    openEditCompanyModal(currentId);
  } else {
    showNotification('No hay una empresa activa seleccionada en este momento.', 'warning');
  }
}

function submitEditCompany(event) {
  if (event) event.preventDefault();
  if (!isMasterUser()) {
    showNotification('Acceso de Solo Lectura: Tu cuenta es de perfil Lite. No tienes permisos para registrar o modificar datos.', 'warning');
    return;
  }

  const getVal = (id) => {
    const el = document.getElementById(id);
    return el ? el.value.trim() : '';
  };

  const companyId = getVal('edit-comp-id');
  if (!companyId) return;

  const compIndex = (appData.companies || []).findIndex(c => c.id === companyId);
  if (compIndex === -1) {
    showNotification('Error: La empresa no existe en la base de datos.', 'error');
    return;
  }

  const name = getVal('edit-comp-name');
  const nit = getVal('edit-comp-nit');
  const location = getVal('edit-comp-location');
  const clientName = getVal('edit-comp-client');
  const clientEmail = getVal('edit-comp-email');
  const phone = getVal('edit-comp-phone');
  const technicalManager = getVal('edit-comp-tech') || 'Ing. Carlos Mendoza (DC Asesorías)';
  const status = document.getElementById('edit-comp-status') ? document.getElementById('edit-comp-status').value : 'activo';
  const earthenPondsCount = parseInt(document.getElementById('edit-comp-ponds').value, 10) || 10;
  const geomembranesCount = parseInt(document.getElementById('edit-comp-geos').value, 10) || 3;
  const notes = getVal('edit-comp-notes');
  const userRole = document.getElementById('edit-comp-user-role') ? document.getElementById('edit-comp-user-role').value : 'lite';
  const password = getVal('edit-comp-password') || '123456';

  const contractCycle = document.getElementById('edit-comp-contract-cycle') ? document.getElementById('edit-comp-contract-cycle').value : 'mensual';
  const contractFee = document.getElementById('edit-comp-contract-fee') ? (parseFloat(document.getElementById('edit-comp-contract-fee').value) || 0) : 0;
  const contractBillingDay = document.getElementById('edit-comp-contract-billing-day') ? (parseInt(document.getElementById('edit-comp-contract-billing-day').value, 10) || 5) : 5;
  const contractNextDate = document.getElementById('edit-comp-contract-next') ? document.getElementById('edit-comp-contract-next').value : '';

  const comp = appData.companies[compIndex];
  comp.name = name;
  comp.nit = nit;
  comp.location = location;
  comp.clientName = clientName;
  comp.clientEmail = clientEmail;
  comp.phone = phone;
  comp.technicalManager = technicalManager;
  comp.status = status;
  comp.earthenPondsCount = earthenPondsCount;
  comp.geomembranesCount = geomembranesCount;
  comp.notes = notes;
  comp.userRole = userRole;

  if (!Array.isArray(comp.assignedUsers)) comp.assignedUsers = [];

  if (userRole === 'both') {
    const hasM = comp.assignedUsers.some(u => u.email.toLowerCase() === clientEmail.toLowerCase() && u.role === 'master');
    const hasL = comp.assignedUsers.some(u => u.email.toLowerCase() === clientEmail.toLowerCase() && u.role === 'lite');
    if (!hasM) {
      comp.assignedUsers.push({
        id: `USR-${comp.id}-M`,
        email: clientEmail,
        name: `${clientName} (Master)`,
        role: 'master',
        password: password,
        companyId: comp.id
      });
    }
    if (!hasL) {
      comp.assignedUsers.push({
        id: `USR-${comp.id}-L`,
        email: clientEmail,
        name: `${clientName} (Lite)`,
        role: 'lite',
        password: password,
        companyId: comp.id
      });
    }
  } else {
    let found = false;
    comp.assignedUsers.forEach(u => {
      if (u.email.toLowerCase() === clientEmail.toLowerCase()) {
        u.role = userRole;
        u.password = password;
        found = true;
      }
    });
    if (!found) {
      comp.assignedUsers.push({
        id: `USR-${comp.id}-1`,
        email: clientEmail,
        name: clientName,
        role: userRole,
        password: password,
        companyId: comp.id
      });
    }
  }

  if (!comp.contract) comp.contract = {};
  comp.contract.billingCycle = contractCycle;
  comp.contract.feeAmount = contractFee;
  comp.contract.billingDay = contractBillingDay;
  if (contractNextDate) comp.contract.nextBillingDate = contractNextDate;

  // Actualizar en el almacén individual de la empresa si existe
  if (appData.companyStores && appData.companyStores[companyId]) {
    const store = appData.companyStores[companyId];
    if (!store.farmInfo) store.farmInfo = {};
    store.farmInfo.name = name;
    store.farmInfo.nit = nit;
    store.farmInfo.location = location;
    store.farmInfo.technicalManager = technicalManager;
    store.farmInfo.lastUpdate = new Date().toISOString();
  }

  // Si esta empresa es la actualmente activa en sesión, actualizar títulos y datos en caliente
  const isActive = (appData.activeCompanyId === companyId) || (!appData.activeCompanyId && appData.farmInfo && appData.farmInfo.nit === nit);
  if (isActive) {
    appData.farmInfo = {
      ...(appData.farmInfo || {}),
      name,
      nit,
      location,
      technicalManager,
      lastUpdate: new Date().toISOString()
    };
  }

  PiscicolaStorage.save(appData);
  PiscicolaStorage.syncPut(`companies/${comp.id}`, comp);

  closeModal('modal-edit-company');
  renderEmpresas();
  applyUserPermissions();

  showNotification(`¡Datos de la empresa "${name}" actualizados correctamente!`, 'success');
}

