  if (!comp.billingPayments) comp.billingPayments = [];

  const contract = comp.contract;
  const cycle = contract.billingCycle || 'mensual';
  const cycleLabel = cycle === 'anual' ? 'Anual' : cycle === 'trimestral' ? 'Trimestral' : cycle === 'semestral' ? 'Semestral' : 'Mensual';
  const fee = parseFloat(contract.feeAmount) || 0;
  const todayStr = new Date().toISOString().slice(0, 10);
  const nextDate = contract.nextBillingDate;
  const diffDays = nextDate ? Math.ceil((new Date(nextDate) - new Date(todayStr)) / (1000 * 60 * 60 * 24)) : null;

