function switchUnitDetailTab(tab) {
  const tabs = ['bio', 'feed', 'med', 'transfers'];
  tabs.forEach(t => {
    const btn = document.getElementById(`tab-btn-${t}`);
    const panel = document.getElementById(`unit-tab-${t}`);
    if (btn && panel) {
      if (t === tab) {
        btn.className = "pb-2 text-sky-600 border-b-2 border-sky-600 cursor-pointer font-bold";
        panel.classList.remove('hidden');
      } else {
        btn.className = "pb-2 hover:text-sky-600 text-slate-500 cursor-pointer";
        panel.classList.add('hidden');
      }
    }
  });
}

// ----------------------------------------------------
// CÓDIGOS DE LOTE Y TRAZABILIDAD DE TRASLADOS
// ----------------------------------------------------
function getSpeciesCode(speciesName) {
  if (!speciesName) return 'R';
  if (appData.speciesCatalog && Array.isArray(appData.speciesCatalog)) {
    const sLower = speciesName.toLowerCase();
    const found = appData.speciesCatalog.find(sp => {
      const spName = (sp.name || '').toLowerCase();
      const spSci = (sp.scientificName || '').toLowerCase();
      return (sp.code && (sLower.includes(spName) || spName.includes(sLower) || (spSci && sLower.includes(spSci))));
    });
    if (found && found.code) return found.code.trim().toUpperCase();
  }
  const s = speciesName.toLowerCase();
  if (s.includes('nilotica') || s.includes('nilótica')) return 'N'; // Mojarra Nilótica
  if (s.includes('roja')) return 'R';                             // Mojarra Roja
  if (s.includes('bocachico')) return 'B';                         // Bocachico
  if (s.includes('cachama')) return 'C';                           // Cachama
  if (s.includes('trucha')) return 'T';                             // Trucha
  return speciesName.trim().charAt(0).toUpperCase();
}

function generateBatchCode(dateStr, speciesName) {
  let mm = '10';
  let dd = '01';
  if (dateStr && typeof dateStr === 'string' && dateStr.includes('-')) {
    const parts = dateStr.split('-');
    if (parts.length >= 3) {
      mm = parts[1].padStart(2, '0');
      dd = parts[2].padStart(2, '0');
    }
  } else {
    const now = new Date();
    mm = String(now.getMonth() + 1).padStart(2, '0');
    dd = String(now.getDate()).padStart(2, '0');
  }

  const letter = getSpeciesCode(speciesName);
  return `LOTE-${mm}-${dd}-${letter}`;
}

function refreshSuggestedBatchCode() {
  const dateInput = document.getElementById('stocking-date');
  const speciesInput = document.getElementById('stocking-species');
  const batchInput = document.getElementById('stocking-batch-id');
  if (!batchInput) return;

  const dateVal = dateInput ? dateInput.value : '';
  const speciesVal = speciesInput ? speciesInput.value : '';
  batchInput.value = generateBatchCode(dateVal, speciesVal);
}

function getNextTransferBatchId(originBatch) {
  if (!originBatch) {
    return { destBatchId: 'LOTE-TR-1', rootBatchId: 'LOTE-TR', sequence: 1 };
  }

  // Root / Initial Batch:
  // Si el lote origen ya tiene rootBatchId, conservarlo; sino, quitar sufijo -(\d+)$
  let rootBatchId = originBatch.rootBatchId;
  if (!rootBatchId) {
    rootBatchId = (originBatch.id || 'LOTE').replace(/-\d+$/, '');
  }

  const escapedRoot = rootBatchId.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const regex = new RegExp(`^${escapedRoot}-(\\d+)$`);
  let maxIndex = 0;

  (appData.batches || []).forEach(b => {
    if (b && b.id) {
      const m = b.id.match(regex);
      if (m) {
        const val = parseInt(m[1], 10);
        if (val > maxIndex) maxIndex = val;
      }
    }
  });

  (appData.transfers || []).forEach(t => {
    if (t && t.destBatchId) {
      const m = t.destBatchId.match(regex);
      if (m) {
        const val = parseInt(m[1], 10);
        if (val > maxIndex) maxIndex = val;
      }
    }
  });

  const nextSeq = maxIndex + 1;
  return {
    destBatchId: `${rootBatchId}-${nextSeq}`,
    rootBatchId: rootBatchId,
    sequence: nextSeq
  };
}

function updateTransferResultingBatchPreview() {
  const originSelect = document.getElementById('transfer-origin-unit');
  const destSelect = document.getElementById('transfer-dest-unit');
  const previewEl = document.getElementById('transfer-resulting-batch-id');
  if (!originSelect || !previewEl) return;

  const originUnit = (appData.units || []).find(u => u.id === originSelect.value);
  if (!originUnit) {
    previewEl.innerText = '-';
    return;
  }
  const originMetrics = getUnitMetrics(originUnit);
  if (!originMetrics.hasBatch) {
    previewEl.innerText = '-';
    return;
  }

  const destUnit = destSelect ? (appData.units || []).find(u => u.id === destSelect.value) : null;
  const destMetrics = destUnit ? getUnitMetrics(destUnit) : null;

  if (destMetrics && destMetrics.hasBatch) {
    previewEl.innerText = `${destMetrics.batch.id} (Lote existente en destino)`;
    previewEl.className = 'px-3 py-1.5 bg-amber-50 font-bold text-amber-800 rounded-xl border border-amber-300 shadow-2xs text-xs';
  } else {
    const nextInfo = getNextTransferBatchId(originMetrics.batch);
    previewEl.innerText = nextInfo.destBatchId;
    previewEl.className = 'px-3 py-1.5 bg-emerald-50 font-black text-emerald-800 rounded-xl border border-emerald-300 shadow-2xs text-xs tracking-wider';
  }
}

// ----------------------------------------------------
// TRASLADO DE PECES ENTRE UNIDADES (Estanques y Geomembranas)
// ----------------------------------------------------
function openTransferModal(preselectedUnitId = null) {
  if (!isMasterUser()) {
    showNotification('Acceso de Solo Lectura: Tu cuenta es de perfil Lite. No tienes permisos para registrar o modificar datos.', 'warning');
    return;
  }

  const unitsWithFish = (appData.units || []).filter(u => {
    const m = getUnitMetrics(u);
    return m.hasBatch && m.fishCount > 0;
  });

  if (unitsWithFish.length === 0) {
    showNotification("No hay estanques o geomembranas con lotes de peces activos para trasladar. Debe haber al menos una unidad con siembra activa.", 'warning');
    return;
  }

  const originSelect = document.getElementById('transfer-origin-unit');
  if (!originSelect) return;

  originSelect.innerHTML = unitsWithFish.map(u => {
    const m = getUnitMetrics(u);
    const typeLabel = u.type === 'geomembrana' ? 'Geomembrana' : 'Estanque';
    return `<option value="${u.id}">${u.name} (${typeLabel}) - ${m.batch.species} (${formatNumber(m.fishCount, 0)} peces)</option>`;
  }).join('');

  if (preselectedUnitId && unitsWithFish.some(u => u.id === preselectedUnitId)) {
    originSelect.value = preselectedUnitId;
  } else {
    originSelect.value = unitsWithFish[0].id;
  }

  // Set date to today
  const dateInput = document.getElementById('transfer-date');
  if (dateInput) {
    dateInput.value = new Date().toISOString().slice(0, 10);
  }

  const notesInput = document.getElementById('transfer-notes');
  if (notesInput) notesInput.value = '';

  const qtyInput = document.getElementById('transfer-quantity');
  if (qtyInput) qtyInput.value = '';

  onTransferOriginChange(originSelect.value);
  openModal('modal-transfer-fish');
}

function onTransferOriginChange(originId) {
  const originUnit = (appData.units || []).find(u => u.id === originId);
  if (!originUnit) return;

  const m = getUnitMetrics(originUnit);

  const speciesEl = document.getElementById('transfer-origin-species');
  const availEl = document.getElementById('transfer-origin-available');
  const weightEl = document.getElementById('transfer-origin-weight');
  const qtyHelper = document.getElementById('transfer-qty-helper');
  const qtyInput = document.getElementById('transfer-quantity');
  const avgWeightInput = document.getElementById('transfer-avg-weight');

  if (speciesEl) speciesEl.innerText = m.batch ? m.batch.species : '-';
  if (availEl) availEl.innerText = `${formatNumber(m.fishCount, 0)} peces`;
  if (weightEl) weightEl.innerText = `${m.avgWeight} g`;
  if (qtyHelper) qtyHelper.innerText = `Máx disponible: ${formatNumber(m.fishCount, 0)} peces`;

  if (qtyInput) {
    qtyInput.max = m.fishCount;
    qtyInput.placeholder = `Hasta ${formatNumber(m.fishCount, 0)}`;
    if (parseInt(qtyInput.value, 10) > m.fishCount) {
      qtyInput.value = m.fishCount;
    }
  }

  if (avgWeightInput) {
    avgWeightInput.value = m.avgWeight || 50;
  }

  // Populate Destination select excluding origin unit
  const destSelect = document.getElementById('transfer-dest-unit');
  if (destSelect) {
    const candidateDestUnits = (appData.units || []).filter(u => u.id !== originId);
    destSelect.innerHTML = candidateDestUnits.map(u => {
      const dm = getUnitMetrics(u);
      const typeLabel = u.type === 'geomembrana' ? 'Geomembrana' : 'Estanque';
      const statusLabel = dm.hasBatch ? `Activo: ${dm.batch.species} (${formatNumber(dm.fishCount, 0)} peces)` : 'En Descanso (Vacío)';
      return `<option value="${u.id}">${u.name} (${typeLabel}) - [${statusLabel}]</option>`;
    }).join('');

    if (candidateDestUnits.length > 0) {
      destSelect.value = candidateDestUnits[0].id;
      onTransferDestChange(candidateDestUnits[0].id);
    }
  }

  calculateTransferBiomass();
  updateTransferResultingBatchPreview();
}

function onTransferDestChange(destId) {
  const destUnit = (appData.units || []).find(u => u.id === destId);
  if (!destUnit) return;

  const m = getUnitMetrics(destUnit);
  const statusEl = document.getElementById('transfer-dest-status');
  const currentFishEl = document.getElementById('transfer-dest-current-fish');
  const capacityEl = document.getElementById('transfer-dest-capacity');

  if (statusEl) {
    statusEl.innerHTML = m.hasBatch
      ? `<span class="text-sky-700 font-bold">${m.batch.species} (Lote ${m.batch.id})</span>`
      : `<span class="text-emerald-700 font-bold">En Descanso (Disponible)</span>`;
  }

  if (currentFishEl) {
    currentFishEl.innerText = m.hasBatch
      ? `${formatNumber(m.fishCount, 0)} peces (${m.avgWeight}g prom)`
      : '0 peces (Listo para recibir siembra)';
  }

  if (capacityEl) {
    capacityEl.innerText = destUnit.volumeM3 
      ? `${destUnit.volumeM3} m³ (${destUnit.type === 'geomembrana' ? `Ø ${destUnit.diameterM}m` : `${destUnit.areaM2} m²`})`
      : '0 m³ (Sin configurar)';
  }

  updateTransferResultingBatchPreview();
}

function calculateTransferBiomass() {
  const qtyInput = document.getElementById('transfer-quantity');
  const weightInput = document.getElementById('transfer-avg-weight');
  const preview = document.getElementById('transfer-biomass-preview');

  const qty = parseInt(qtyInput ? qtyInput.value : 0, 10) || 0;
  const weight = parseFloat(weightInput ? weightInput.value : 0) || 0;

  const biomassKg = Math.round(((qty * weight) / 1000) * 10) / 10;
  if (preview) {
    preview.innerText = `${biomassKg.toFixed(1)} kg`;
  }
}

async function submitFishTransfer(event) {
  if (event) event.preventDefault();

  if (!isMasterUser()) {
    showNotification('Acceso de Solo Lectura: Tu cuenta es de perfil Lite. No tienes permisos para registrar o modificar datos.', 'warning');
    return;
  }

  const originId = document.getElementById('transfer-origin-unit').value;
  const destId = document.getElementById('transfer-dest-unit').value;
  const qty = parseInt(document.getElementById('transfer-quantity').value, 10);
  const avgWeight = parseFloat(document.getElementById('transfer-avg-weight').value);
  const transferDate = document.getElementById('transfer-date').value;
  const reason = document.getElementById('transfer-reason').value;
  const notes = document.getElementById('transfer-notes').value.trim();

  if (!originId || !destId) {
    showNotification("Por favor seleccione tanto el estanque de origen como el estanque de destino.", 'warning');
    return;
  }

  if (originId === destId) {
    showNotification("El estanque de origen y destino deben ser diferentes.", 'warning');
    return;
  }

  const originUnit = (appData.units || []).find(u => u.id === originId);
  const destUnit = (appData.units || []).find(u => u.id === destId);

  if (!originUnit || !destUnit) {
    showNotification("Unidad de origen o destino no encontrada.", 'error');
    return;
  }

  const originMetrics = getUnitMetrics(originUnit);
  if (!originMetrics.hasBatch || originMetrics.fishCount <= 0) {
    showNotification("La unidad de origen seleccionada no tiene peces activos para trasladar.", 'warning');
    return;
  }

  if (!qty || qty <= 0) {
    showNotification("La cantidad de peces a trasladar debe ser mayor a cero.", 'warning');
    return;
  }

  if (qty > originMetrics.fishCount) {
    showNotification(`No es posible trasladar ${formatNumber(qty, 0)} peces. La unidad de origen solo tiene ${formatNumber(originMetrics.fishCount, 0)} peces disponibles.`, 'warning');
    return;
  }

  if (!avgWeight || avgWeight <= 0) {
    showNotification("El peso promedio debe ser mayor a 0 gramos.", 'warning');
    return;
  }

  if (!transferDate) {
    showNotification("Por favor ingrese la fecha del traslado.", 'warning');
    return;
  }

  const biomassKg = Math.round(((qty * avgWeight) / 1000) * 10) / 10;
  const isFullTransfer = (qty >= originMetrics.fishCount);

  const originBatch = originMetrics.batch;
  const destMetrics = getUnitMetrics(destUnit);

  // Calcular Lote en destino (mantiene el lote inicial del origen con -1, -2...)
  const transferInfo = getNextTransferBatchId(originBatch);
  const targetBatchLabel = destMetrics.hasBatch ? destMetrics.batch.id : transferInfo.destBatchId;

  const confirmMsg = `¿Confirmas el traslado de:\n` +
    `• ${formatNumber(qty, 0)} peces (${biomassKg} kg) de ${originMetrics.batch.species}\n` +
    `• DESDE: ${originUnit.name} (Lote: ${originBatch.id})\n` +
    `• HACIA: ${destUnit.name} (Lote en Destino: ${targetBatchLabel})\n` +
    `• Tipo: ${isFullTransfer ? 'Traslado Total (desocupa estanque origen)' : 'Traslado Parcial / Desdoble'}\n` +
    `• Fecha: ${transferDate}?`;

  if (!confirm(confirmMsg)) return;

  // 1. Process Destination
  let destBatchId = null;
  let transferSeq = 1;
  let rootBatchId = originBatch.rootBatchId || originBatch.id.replace(/-\d+$/, '');

  if (!destMetrics.hasBatch) {
    // Destination is empty: Create new active batch preserving origin batch root with -1, -2, etc.
    destBatchId = transferInfo.destBatchId;
    rootBatchId = transferInfo.rootBatchId;
    transferSeq = transferInfo.sequence;

    const newBatch = {
      id: destBatchId,
      rootBatchId: rootBatchId,
      originBatchId: originBatch.id,
      transferSequence: transferSeq,
      unitId: destUnit.id,
      species: originBatch.species,
      stockingDate: originBatch.stockingDate || transferDate, // Conserva fecha original para curva de edad
      transferDate: transferDate,
      initialQuantity: qty,
      currentQuantity: qty,
      initialWeightGrams: avgWeight,
      currentAvgWeightGrams: avgWeight,
      targetHarvestWeightGrams: originBatch.targetHarvestWeightGrams || 450,
      origin: `Traslado desde ${originUnit.name} (${originBatch.id})`,
      status: 'activo',
      notes: `Lote generado por traslado (${transferSeq}° traslado de linaje ${rootBatchId}) de ${formatNumber(qty, 0)} peces desde ${originUnit.name}. Motivo: ${reason}. ${notes}`.trim()
    };
    if (!appData.batches) appData.batches = [];
    appData.batches.push(newBatch);
    destUnit.activeBatchId = newBatch.id;
    destUnit.status = 'activo';
  } else {
    // Destination already has active batch: Add fish and recalculate weighted average weight
    const destBatch = destMetrics.batch;
    destBatchId = destBatch.id;
    const destCurQty = destMetrics.fishCount;
    const destCurWeight = destMetrics.avgWeight;
    const newTotalQty = destCurQty + qty;

    const weightedAvg = newTotalQty > 0
      ? Math.round(((destCurQty * destCurWeight) + (qty * avgWeight)) / newTotalQty * 10) / 10
      : avgWeight;

    destBatch.currentQuantity = newTotalQty;
    destBatch.currentAvgWeightGrams = weightedAvg;
    destBatch.notes = ((destBatch.notes || '') + ` | [${transferDate}] +${qty} peces trasl. desde ${originUnit.name} (Lote ${originBatch.id}, ${avgWeight}g)`).trim();
    destUnit.status = 'activo';
  }

  // 2. Process Origin
  const remainingInOrigin = originMetrics.fishCount - qty;
  if (remainingInOrigin <= 0) {
    // 100% transferred: mark origin batch as trasladado and unit as descanso
    originBatch.currentQuantity = 0;
    originBatch.status = 'trasladado';
    originBatch.harvestDate = transferDate;
    originBatch.notes = ((originBatch.notes || '') + ` | [${transferDate}] Traslado total de ${formatNumber(qty, 0)} peces a ${destUnit.name} (${destBatchId}). Estanque desocupado.`).trim();
    originUnit.activeBatchId = null;
    originUnit.status = 'descanso';
  } else {
    // Partial transfer
    originBatch.currentQuantity = remainingInOrigin;
    originBatch.notes = ((originBatch.notes || '') + ` | [${transferDate}] Traslado parcial: -${formatNumber(qty, 0)} peces a ${destUnit.name} (${destBatchId}). Quedan: ${formatNumber(remainingInOrigin, 0)}`).trim();
    originUnit.status = 'activo';
  }

  // 3. Log Transfer in appData.transfers
  if (!appData.transfers) appData.transfers = [];
  const transferLog = {
    id: `TR-${Date.now().toString().slice(-6)}`,
    date: transferDate,
    originUnitId: originUnit.id,
    originUnitName: originUnit.name,
    originBatchId: originBatch.id,
    destUnitId: destUnit.id,
    destUnitName: destUnit.name,
    destBatchId: destBatchId,
    species: originBatch.species,
    quantity: qty,
    avgWeightGrams: avgWeight,
    biomassKg: biomassKg,
    reason: reason,
    notes: notes,
    timestamp: new Date().toISOString()
  };
  appData.transfers.unshift(transferLog);

  // 4. Save and sync
  PiscicolaStorage.save(appData);
  PiscicolaStorage.syncPost('transfers', transferLog);

  // 5. Close modal & Notify
  closeModal('modal-transfer-fish');
  showNotification(`¡Traslado exitoso! Se movilizaron ${formatNumber(qty, 0)} peces (${biomassKg} kg) desde ${originUnit.name} hacia ${destUnit.name}.`, 'success');

  // 6. Refresh UI
  renderUnidades();
}

// ----------------------------------------------------
// EDICIÓN DE DIMENSIONES FÍSICAS Y CÁLCULO DE VOLUMEN
// ----------------------------------------------------
function openEditUnitDimensions(unitId) {
  if (!isMasterUser()) {
    showNotification('Acceso de Solo Lectura: Tu cuenta es de perfil Lite. No tienes permisos para registrar o modificar datos.', 'warning');
    return;
  }

  const unit = (appData.units || []).find(u => u.id === unitId);
  if (!unit) return;

  const isGeomembrane = (unit.type === 'geomembrana');

  const titleEl = document.getElementById('edit-unit-dim-title');
  const idInput = document.getElementById('edit-unit-id');
  const typeInput = document.getElementById('edit-unit-type');
  const nameInput = document.getElementById('edit-unit-name');
  const diameterCont = document.getElementById('edit-geomembrane-diameter-container');
  const diameterInput = document.getElementById('edit-unit-diameter');
  const areaInput = document.getElementById('edit-unit-area');
  const depthInput = document.getElementById('edit-unit-depth');
  const aerationInput = document.getElementById('edit-unit-aeration');
  const extraLabel = document.getElementById('edit-unit-extra-label');
  const extraVal = document.getElementById('edit-unit-extra-val');
  const formulaText = document.getElementById('edit-unit-formula-text');

  if (titleEl) titleEl.innerText = `Editar Nombre y Medidas: ${unit.name}`;
  if (idInput) idInput.value = unit.id;
  if (typeInput) typeInput.value = unit.type;
  if (nameInput) nameInput.value = unit.name || '';
  if (areaInput) areaInput.value = unit.areaM2 || '';
  if (depthInput) depthInput.value = unit.avgDepthM || '';
  if (aerationInput) aerationInput.value = unit.aeration || '';

  if (isGeomembrane) {
    if (diameterCont) diameterCont.classList.remove('hidden');
    if (diameterInput) diameterInput.value = unit.diameterM || '';
    if (extraLabel) extraLabel.innerText = 'Tipo / Calibre Geomembrana';
    if (extraVal) extraVal.value = unit.liner || 'HDPE 1.0mm';
    if (formulaText) formulaText.innerText = 'Fórmula Circular: π × (Diámetro / 2)² × Profundidad (m)';
  } else {
    if (diameterCont) diameterCont.classList.add('hidden');
    if (diameterInput) diameterInput.value = '';
    if (extraLabel) extraLabel.innerText = 'Tipo de Fondo / Suelo';
    if (extraVal) extraVal.value = unit.soilType || 'Arcilloso';
    if (formulaText) formulaText.innerText = 'Fórmula Estanque: Área Espejo (m²) × Profundidad Media (m)';
  }

  calculateUnitVolume();
  openModal('modal-edit-unit-dimensions');
}

function onGeomembraneDiameterChange() {
  const diameterInput = document.getElementById('edit-unit-diameter');
  const areaInput = document.getElementById('edit-unit-area');
  const d = parseFloat(diameterInput ? diameterInput.value : 0) || 0;

  if (d > 0) {
    const radius = d / 2;
    const computedArea = Math.round(Math.PI * radius * radius * 10) / 10;
    if (areaInput) areaInput.value = computedArea;
  }
  calculateUnitVolume();
}

function calculateUnitVolume() {
  const areaInput = document.getElementById('edit-unit-area');
  const depthInput = document.getElementById('edit-unit-depth');
  const volDisplay = document.getElementById('edit-unit-volume-display');
  const litDisplay = document.getElementById('edit-unit-liters-display');

  const area = parseFloat(areaInput ? areaInput.value : 0) || 0;
  const depth = parseFloat(depthInput ? depthInput.value : 0) || 0;

  const volume = Math.round(area * depth * 10) / 10;
  const liters = Math.round(volume * 1000);

  if (volDisplay) volDisplay.innerText = `${volume.toFixed(1)} m³`;
  if (litDisplay) litDisplay.innerText = `${formatNumber(liters, 0)} Litros`;
}

function saveUnitDimensions(event) {
  if (event) event.preventDefault();

  if (!isMasterUser()) {
    showNotification('Acceso de Solo Lectura: Tu cuenta es de perfil Lite. No tienes permisos para registrar o modificar datos.', 'warning');
    return;
  }

  const unitId = document.getElementById('edit-unit-id').value;
  const name = document.getElementById('edit-unit-name').value.trim();
  const area = parseFloat(document.getElementById('edit-unit-area').value) || 0;
  const depth = parseFloat(document.getElementById('edit-unit-depth').value) || 0;
  const aeration = document.getElementById('edit-unit-aeration').value.trim();
  const extraVal = document.getElementById('edit-unit-extra-val').value.trim();
  const diameterInput = document.getElementById('edit-unit-diameter');
  const diameter = diameterInput ? (parseFloat(diameterInput.value) || 0) : 0;

  const unit = (appData.units || []).find(u => u.id === unitId);
  if (!unit) {
    showNotification("Unidad no encontrada.", 'error');
    return;
  }

  const volume = Math.round(area * depth * 10) / 10;

  unit.name = name;
  unit.areaM2 = area;
  unit.avgDepthM = depth;
  unit.volumeM3 = volume;
  unit.aeration = aeration;

  if (unit.type === 'geomembrana') {
    unit.diameterM = diameter;
    unit.liner = extraVal;
  } else {
    unit.soilType = extraVal;
  }

  // 1. Sincronizar inmediatamente en el almacén de empresa activa si aplica
  if (appData.activeCompanyId && appData.companyStores && appData.companyStores[appData.activeCompanyId]) {
    const store = appData.companyStores[appData.activeCompanyId];
    if (!store.units) store.units = [];
    const uIdx = store.units.findIndex(u => u.id === unit.id);
    if (uIdx !== -1) {
      store.units[uIdx] = JSON.parse(JSON.stringify(unit));
    } else {
      store.units.push(JSON.parse(JSON.stringify(unit)));
    }
  }

  // 2. Persistir localmente y sincronizar en la nube
  PiscicolaStorage.save(appData);
  PiscicolaStorage.syncPut(`units/${unit.id}`, unit);

  // 3. Notificar y cerrar modal
  closeModal('modal-edit-unit-dimensions');
  showNotification(`¡"${unit.name}" actualizado correctamente! Nombre y medidas guardados en el sistema.`, 'success');

  // 4. Refrescar la vista actual (si está en Dashboard, refrescar Dashboard en vivo; si está en Unidades, Unidades)
  if (activeTab === 'dashboard') {
    renderDashboard();
  } else if (activeTab === 'unidades') {
    renderUnidades();
  } else {
    renderApp();
  }

  // 5. Si la ficha de detalle de la unidad estaba abierta, refrescarla con el nuevo nombre
  const detailModal = document.getElementById('modal-unit-detail');
  if (detailModal && !detailModal.classList.contains('hidden')) {
    openUnitDetail(unitId);
  }
}

if (typeof window !== 'undefined') {
  window.openTransferModal = openTransferModal;
  window.onTransferOriginChange = onTransferOriginChange;
  window.onTransferDestChange = onTransferDestChange;
  window.calculateTransferBiomass = calculateTransferBiomass;
  window.submitFishTransfer = submitFishTransfer;
  window.openEditUnitDimensions = openEditUnitDimensions;
  window.onGeomembraneDiameterChange = onGeomembraneDiameterChange;
  window.calculateUnitVolume = calculateUnitVolume;
  window.saveUnitDimensions = saveUnitDimensions;
}

