// ----------------------------------------------------
// 3.6. CALIDAD DEL AGUA (Oxígeno, Temp, pH, Semáforo y Alertas)
// ----------------------------------------------------
let activeWaterQualityFilter = 'todos'; // 'todos' | 'estanques' | 'geomembranas'
let activeWaterQualityPeriod = 'todos'; // 'todos' | 'manana' | 'tarde' | 'noche'
let activeWaterQualityStatus = 'todos'; // 'todos' | 'optimo' | 'alerta' | 'critico'
let activeWaterQualitySearch = '';

function getWaterQualityDiagnostic(wq) {
  if (!wq) {
    return {
      overallStatus: 'sin_datos',
      statusLabel: 'Sin Datos',
      badgeClass: 'bg-slate-100 text-slate-600 border-slate-200',
      cardBorder: 'border-slate-200',
      accentColor: 'slate',
      dotColor: 'bg-slate-400',
      recommendation: 'Registrar primer muestreo de oxígeno, temperatura y pH para monitoreo.',
      alerts: []
    };
  }

  const alerts = [];
  const doVal = parseFloat(wq.dissolvedOxygen);
  const tempVal = parseFloat(wq.temperature);
  const phVal = parseFloat(wq.ph);
  const ammoniaVal = wq.ammonia !== null && wq.ammonia !== undefined && wq.ammonia !== '' ? parseFloat(wq.ammonia) : null;
  const nitriteVal = wq.nitrite !== null && wq.nitrite !== undefined && wq.nitrite !== '' ? parseFloat(wq.nitrite) : null;
  const secchiVal = wq.secchi !== null && wq.secchi !== undefined && wq.secchi !== '' ? parseFloat(wq.secchi) : null;

  let isCritical = false;
  let isAlert = false;

  // 1. Oxígeno Disuelto (Parámetro Rey)
  if (!isNaN(doVal)) {
    if (doVal < 3.0) {
      isCritical = true;
      alerts.push({
        param: 'Oxígeno Disuelto (O₂)',
        val: `${doVal.toFixed(1)} mg/L`,
        level: 'critico',
        msg: 'CRÍTICO: Hipoxia severa (<3.0 mg/L). Peligro de muerte por asfixia. Encender aireadores o aumentar recambio urgente. Suspender alimentación.'
      });
    } else if (doVal < 4.5) {
      isAlert = true;
      alerts.push({
        param: 'Oxígeno Disuelto (O₂)',
        val: `${doVal.toFixed(1)} mg/L`,
        level: 'alerta',
        msg: 'ALERTA: Oxígeno bajo (3.0 - 4.5 mg/L). Activar aireación de apoyo y reducir ración de alimento en un 30-50%.'
      });
    }
  }

  // 2. Temperatura del Agua
  if (!isNaN(tempVal)) {
    if (tempVal < 24.0) {
      isAlert = true;
      alerts.push({
        param: 'Temperatura',
        val: `${tempVal.toFixed(1)} °C`,
        level: 'alerta',
        msg: 'Temperatura baja (<24°C). Ralentiza el metabolismo y apetito de los peces. Reducir ración.'
      });
    } else if (tempVal > 32.0) {
      isAlert = true;
      alerts.push({
        param: 'Temperatura',
        val: `${tempVal.toFixed(1)} °C`,
        level: 'alerta',
        msg: 'Temperatura elevada (>32°C). Disminuye la solubilidad del oxígeno y genera estrés metabólico.'
      });
    }
  }

  // 3. pH del Agua
  if (!isNaN(phVal)) {
    if (phVal < 6.5) {
      isAlert = true;
      alerts.push({
        param: 'pH',
        val: `${phVal.toFixed(1)}`,
        level: 'alerta',
        msg: 'pH Ácido (<6.5). Riesgo de acidosis e irritación de branquias. Evaluar encalado agrícola (CaCO₃).'
      });
    } else if (phVal > 8.5) {
      isAlert = true;
      alerts.push({
        param: 'pH',
        val: `${phVal.toFixed(1)}`,
        level: 'alerta',
        msg: 'pH Alcalino (>8.5). Multiplica la fracción de amoníaco no ionizado tóxico (NH₃). Realizar recambio.'
      });
    }
  }

  // 4. Amonio Total (NH3 / NH4)
  if (ammoniaVal !== null && !isNaN(ammoniaVal)) {
    if (ammoniaVal > 0.08) {
      isCritical = true;
      alerts.push({
        param: 'Amonio Total',
        val: `${ammoniaVal.toFixed(2)} mg/L`,
        level: 'critico',
        msg: 'Amonio tóxico (>0.08 mg/L). Daño severo en epitelio branquial. Aumentar flujo de agua de inmediato.'
      });
    } else if (ammoniaVal > 0.05) {
      isAlert = true;
      alerts.push({
        param: 'Amonio Total',
        val: `${ammoniaVal.toFixed(2)} mg/L`,
        level: 'alerta',
        msg: 'Amonio en alerta (>0.05 mg/L). Monitorear alimentación y programar recambio.'
      });
    }
  }

  // 5. Nitritos (NO2)
  if (nitriteVal !== null && !isNaN(nitriteVal)) {
    if (nitriteVal > 0.3) {
      isCritical = true;
      alerts.push({
        param: 'Nitritos (NO₂)',
        val: `${nitriteVal.toFixed(2)} mg/L`,
        level: 'critico',
        msg: 'Nitritos críticos (>0.3 mg/L). Riesgo de metahemoglobinemia (enfermedad de la sangre café). Aplicar cloruro de sodio (sal en grano).'
      });
    } else if (nitriteVal > 0.1) {
      isAlert = true;
      alerts.push({
        param: 'Nitritos (NO₂)',
        val: `${nitriteVal.toFixed(2)} mg/L`,
        level: 'alerta',
        msg: 'Nitritos en alerta (>0.1 mg/L). Aumentar tasa de renovación de agua.'
      });
    }
  }

  // 6. Disco Secchi (Transparencia / Fitoplancton)
  if (secchiVal !== null && !isNaN(secchiVal)) {
    if (secchiVal < 20.0) {
      isAlert = true;
      alerts.push({
        param: 'Disco Secchi',
        val: `${secchiVal.toFixed(0)} cm`,
        level: 'alerta',
        msg: 'Agua muy densa / hipereutrófica (<20 cm). Exceso de fitoplancton. Peligro de anoxia nocturna. Aumentar recambio.'
      });
    } else if (secchiVal > 45.0) {
      alerts.push({
        param: 'Disco Secchi',
        val: `${secchiVal.toFixed(0)} cm`,
        level: 'info',
        msg: 'Agua muy clara (>45 cm). Pobre productividad primaria y nutrientes naturales.'
      });
    }
  }

  // Dictamen global
  if (isCritical) {
    return {
      overallStatus: 'critico',
      statusLabel: 'CRÍTICO',
      badgeClass: 'bg-rose-100 text-rose-700 border-rose-200 animate-pulse',
      cardBorder: 'border-rose-400 bg-rose-50/20',
      accentColor: 'rose',
      dotColor: 'bg-rose-500',
      recommendation: alerts[0] ? alerts[0].msg : 'Atención inmediata requerida: encender aireación y suspender alimento.',
      alerts
    };
  } else if (isAlert) {
    return {
      overallStatus: 'alerta',
      statusLabel: 'EN ALERTA',
      badgeClass: 'bg-amber-100 text-amber-800 border-amber-200',
      cardBorder: 'border-amber-300 bg-amber-50/20',
      accentColor: 'amber',
      dotColor: 'bg-amber-500',
      recommendation: alerts[0] ? alerts[0].msg : 'Monitorear parámetros y ajustar ración de alimentación o recambio.',
      alerts
    };
  } else {
    return {
      overallStatus: 'optimo',
      statusLabel: 'ÓPTIMO',
      badgeClass: 'bg-emerald-100 text-emerald-700 border-emerald-200',
      cardBorder: 'border-emerald-300 bg-emerald-50/10',
      accentColor: 'emerald',
      dotColor: 'bg-emerald-500',
      recommendation: 'Parámetros fisicoquímicos en rango ideal para crecimiento y conversión alimenticia.',
      alerts
    };
  }
}

function onWaterQualityUnitChange(selectEl, batchNameInputId, batchIdInputId) {
  const unitId = selectEl.value;
  const nameInput = document.getElementById(batchNameInputId);
  const idInput = document.getElementById(batchIdInputId);

  if (!unitId) {
    if (nameInput) nameInput.value = 'Sin estanque seleccionado';
    if (idInput) idInput.value = '';
    return;
  }

  const activeBatch = (appData.batches || []).find(b => b.unitId === unitId && b.status === 'activo');
  if (activeBatch) {
    if (nameInput) nameInput.value = `${activeBatch.name || activeBatch.id} (${activeBatch.species || 'Tilapia'})`;
    if (idInput) idInput.value = activeBatch.id;
  } else {
    if (nameInput) nameInput.value = 'Estanque vacío / Sin lote activo';
    if (idInput) idInput.value = '';
  }
}

function updateLiveWqDiagnostic(prefix = '') {
  const doInput = document.getElementById(`${prefix}wq-do`);
  const tempInput = document.getElementById(`${prefix}wq-temp`);
  const phInput = document.getElementById(`${prefix}wq-ph`);
  const ammInput = document.getElementById(`${prefix}wq-ammonia`);
  const nitInput = document.getElementById(`${prefix}wq-nitrite`);
  const secchiInput = document.getElementById(`${prefix}wq-secchi`);
  const textEl = document.getElementById(`${prefix}wq-live-diagnostic-text`);
  const containerEl = document.getElementById(`${prefix}wq-live-diagnostic`);

  if (!textEl) return;

  const sample = {
    dissolvedOxygen: doInput && doInput.value !== '' ? parseFloat(doInput.value) : null,
    temperature: tempInput && tempInput.value !== '' ? parseFloat(tempInput.value) : null,
    ph: phInput && phInput.value !== '' ? parseFloat(phInput.value) : null,
    ammonia: ammInput && ammInput.value !== '' ? parseFloat(ammInput.value) : null,
    nitrite: nitInput && nitInput.value !== '' ? parseFloat(nitInput.value) : null,
    secchi: secchiInput && secchiInput.value !== '' ? parseFloat(secchiInput.value) : null
  };

  const diag = getWaterQualityDiagnostic(sample);

  if (diag.overallStatus === 'critico') {
    textEl.innerHTML = `<span class="text-rose-700 font-black"><i class="fa-solid fa-triangle-exclamation mr-1"></i>DIAGNÓSTICO CRÍTICO:</span> ${diag.recommendation}`;
    if (containerEl) {
      containerEl.className = 'p-3 rounded-xl border border-rose-300 bg-rose-50 text-xs text-rose-800 transition';
    }
  } else if (diag.overallStatus === 'alerta') {
    textEl.innerHTML = `<span class="text-amber-800 font-black"><i class="fa-solid fa-circle-exclamation mr-1"></i>DIAGNÓSTICO EN ALERTA:</span> ${diag.recommendation}`;
    if (containerEl) {
      containerEl.className = 'p-3 rounded-xl border border-amber-300 bg-amber-50 text-xs text-amber-900 transition';
    }
  } else {
    textEl.innerHTML = `<span class="text-emerald-700 font-black"><i class="fa-solid fa-circle-check mr-1"></i>CONDICIONES ÓPTIMAS:</span> Oxígeno, pH y temperatura favorables para alimentación y salud zootécnica.`;
    if (containerEl) {
      containerEl.className = 'p-3 rounded-xl border border-emerald-300 bg-emerald-50 text-xs text-emerald-800 transition';
    }
  }
}

function filterWaterQuality(filter) {
  activeWaterQualityFilter = filter;
  renderCalidadAgua();
}

function filterWaterQualityPeriod(period) {
  activeWaterQualityPeriod = period;
  renderCalidadAgua();
}

function filterWaterQualityStatus(status) {
  activeWaterQualityStatus = status;
  renderCalidadAgua();
}

function searchWaterQuality(term) {
  activeWaterQualitySearch = (term || '').trim().toLowerCase();
  renderCalidadAgua();
}

function renderCalidadAgua() {
  const container = document.getElementById('main-content');
  if (!container) return;

  if (!Array.isArray(appData.waterQuality)) appData.waterQuality = [];
  if (!Array.isArray(appData.units)) appData.units = [];
  if (!Array.isArray(appData.batches)) appData.batches = [];

  // Mapeo del último muestreo por unidad
  const lastSampleByUnit = {};
  appData.units.forEach(u => {
    const unitSamples = appData.waterQuality.filter(s => s.unitId === u.id);
    if (unitSamples.length > 0) {
      // Ordenar más reciente primero
      unitSamples.sort((a, b) => {
        const da = (a.date || '') + ' ' + (a.time || '');
        const db = (b.date || '') + ' ' + (b.time || '');
        return db.localeCompare(da);
      });
      lastSampleByUnit[u.id] = unitSamples[0];
    } else {
      lastSampleByUnit[u.id] = null;
    }
  });

  // Métricas Consolidadas (de las últimas lecturas de cada unidad)
  const sampledUnits = appData.units.filter(u => lastSampleByUnit[u.id] !== null);
  const totalUnits = appData.units.length;

  let sumDO = 0;
  let sumTemp = 0;
  let sumPH = 0;
  let optimalCount = 0;
  let alertCount = 0;
  let criticalCount = 0;

  sampledUnits.forEach(u => {
    const sample = lastSampleByUnit[u.id];
    const diag = getWaterQualityDiagnostic(sample);
    if (diag.overallStatus === 'optimo') optimalCount++;
    else if (diag.overallStatus === 'alerta') alertCount++;
    else if (diag.overallStatus === 'critico') criticalCount++;

    if (!isNaN(parseFloat(sample.dissolvedOxygen))) sumDO += parseFloat(sample.dissolvedOxygen);
    if (!isNaN(parseFloat(sample.temperature))) sumTemp += parseFloat(sample.temperature);
    if (!isNaN(parseFloat(sample.ph))) sumPH += parseFloat(sample.ph);
  });

  const avgDO = sampledUnits.length > 0 ? (sumDO / sampledUnits.length).toFixed(1) : '--';
  const avgTemp = sampledUnits.length > 0 ? (sumTemp / sampledUnits.length).toFixed(1) : '--';
  const avgPH = sampledUnits.length > 0 ? (sumPH / sampledUnits.length).toFixed(1) : '--';
  const optimalPercent = sampledUnits.length > 0 ? Math.round((optimalCount / sampledUnits.length) * 100) : 100;

  const waterBadge = document.getElementById('sidebar-water-alert-badge');
  if (waterBadge) {
    if (criticalCount > 0) {
      waterBadge.innerText = `${criticalCount} Crítico`;
      waterBadge.className = 'bg-rose-500/20 text-rose-300 text-[10px] px-1.5 py-0.5 rounded font-bold border border-rose-500/30 animate-pulse';
    } else if (alertCount > 0) {
      waterBadge.innerText = `${alertCount} Alerta`;
      waterBadge.className = 'bg-amber-500/20 text-amber-300 text-[10px] px-1.5 py-0.5 rounded font-bold border border-amber-500/30';
    } else {
      waterBadge.innerText = 'OD & pH';
      waterBadge.className = 'bg-sky-500/20 text-sky-300 text-[10px] px-1.5 py-0.5 rounded font-bold';
    }
  }

  // Filtrado de la cuadrícula de unidades
  let displayedUnits = appData.units.filter(u => {
    const sample = lastSampleByUnit[u.id];
    const diag = getWaterQualityDiagnostic(sample);

    // Filtro tipo unidad
    if (activeWaterQualityFilter === 'estanques' && u.type === 'geomembrana') return false;
    if (activeWaterQualityFilter === 'geomembranas' && u.type !== 'geomembrana') return false;

    // Filtro estado
    if (activeWaterQualityStatus !== 'todos' && diag.overallStatus !== activeWaterQualityStatus) return false;

    // Búsqueda
    if (activeWaterQualitySearch) {
      const uName = (u.name || '').toLowerCase();
      const uId = (u.id || '').toLowerCase();
      const batch = appData.batches.find(b => b.unitId === u.id && b.status === 'activo');
      const bName = batch ? (batch.name || batch.id).toLowerCase() : '';
      if (!uName.includes(activeWaterQualitySearch) && !uId.includes(activeWaterQualitySearch) && !bName.includes(activeWaterQualitySearch)) {
        return false;
      }
    }

    return true;
  });

  // Filtrado de la tabla de historial
  let filteredHistory = [...appData.waterQuality];
  filteredHistory.sort((a, b) => {
    const da = (a.date || '') + ' ' + (a.time || '');
    const db = (b.date || '') + ' ' + (b.time || '');
    return db.localeCompare(da);
  });

  if (activeWaterQualityFilter === 'estanques') {
    filteredHistory = filteredHistory.filter(h => {
      const u = appData.units.find(x => x.id === h.unitId);
      return u && u.type !== 'geomembrana';
    });
  } else if (activeWaterQualityFilter === 'geomembranas') {
    filteredHistory = filteredHistory.filter(h => {
      const u = appData.units.find(x => x.id === h.unitId);
      return u && u.type === 'geomembrana';
    });
  }

  if (activeWaterQualityPeriod !== 'todos') {
    filteredHistory = filteredHistory.filter(h => {
      const p = (h.period || '').toLowerCase();
      if (activeWaterQualityPeriod === 'manana' || activeWaterQualityPeriod === 'mañana') {
        return p === 'manana' || p === 'mañana';
      }
      return p === activeWaterQualityPeriod;
    });
  }

  if (activeWaterQualityStatus !== 'todos') {
    filteredHistory = filteredHistory.filter(h => {
      const diag = getWaterQualityDiagnostic(h);
      return diag.overallStatus === activeWaterQualityStatus;
    });
  }

  if (activeWaterQualitySearch) {
    filteredHistory = filteredHistory.filter(h => {
      const u = appData.units.find(x => x.id === h.unitId);
      const str = `${h.unitId || ''} ${u ? u.name : ''} ${h.operator || ''} ${h.notes || ''} ${h.correctiveAction || ''}`.toLowerCase();
      return str.includes(activeWaterQualitySearch);
    });
  }

  let html = `
    <div class="space-y-6">
      <!-- HEADER -->
      <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <div class="flex items-center gap-2">
            <span class="px-2.5 py-0.5 rounded-full text-[10px] font-black uppercase tracking-wider bg-cyan-100 text-cyan-800 border border-cyan-200">
              Monitoreo Fisicoquímico & Zootécnico
            </span>
            <span class="text-xs text-slate-400 font-semibold">• DC Piscícola Pro</span>
          </div>
          <h1 class="text-2xl font-black text-slate-800 mt-1 flex items-center gap-2.5">
            <i class="fa-solid fa-droplet text-cyan-500"></i> Calidad del Agua
          </h1>
          <p class="text-xs sm:text-sm text-slate-500">Monitoreo continuo de Oxígeno Disuelto, Temperatura, pH, Amonio y Turbidez en estanques y geomembranas con semáforo zootécnico y alertas en vivo.</p>
        </div>

        <div class="flex items-center gap-2 shrink-0 flex-wrap">
          <button onclick="exportWaterQualityCSV()" class="px-3.5 py-2.5 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-xl text-xs sm:text-sm font-bold border border-slate-200 flex items-center gap-2 transition cursor-pointer shadow-2xs">
            <i class="fa-solid fa-file-csv text-emerald-600"></i>
            <span>Exportar CSV</span>
          </button>
          ${isMasterUser() ? `
            <button onclick="openModalNewWaterQuality()" class="px-4 py-2.5 bg-gradient-to-r from-cyan-600 to-teal-600 hover:from-cyan-500 hover:to-teal-500 text-white rounded-xl text-xs sm:text-sm font-bold shadow-md shadow-cyan-600/20 flex items-center gap-2 transition cursor-pointer">
              <i class="fa-solid fa-plus-circle text-sm"></i>
              <span>+ Nuevo Muestreo de Agua</span>
            </button>
          ` : `
            <span class="text-xs bg-slate-100 text-slate-600 px-3 py-2 rounded-xl font-bold flex items-center gap-1.5 shadow-xs">
              <i class="fa-solid fa-eye text-cyan-600"></i> Solo Consulta
            </span>
          `}
        </div>
      </div>

      <!-- CARDS KPI METRICAS -->
      <div class="grid grid-cols-2 lg:grid-cols-4 gap-3 sm:gap-4">
        <!-- KPI 1: OXÍGENO PROMEDIO -->
        <div class="bg-white p-4 sm:p-5 rounded-2xl border border-slate-200/80 shadow-xs flex items-center gap-3.5">
          <div class="w-11 h-11 rounded-2xl bg-cyan-50 text-cyan-600 flex items-center justify-center text-lg shrink-0 border border-cyan-100">
            <i class="fa-solid fa-lungs"></i>
          </div>
          <div>
            <span class="text-xs text-slate-500 block font-semibold">O₂ Disuelto Promedio</span>
            <div class="flex items-baseline gap-1.5">
              <span class="text-xl sm:text-2xl font-black ${parseFloat(avgDO) < 3.0 ? 'text-rose-600' : parseFloat(avgDO) < 4.5 ? 'text-amber-600' : 'text-cyan-700'}">${avgDO}</span>
              <span class="text-xs text-slate-400 font-bold">mg/L</span>
            </div>
            <span class="text-[10px] text-slate-400 font-medium">${sampledUnits.length} de ${totalUnits} unidades medidas</span>
          </div>
        </div>

        <!-- KPI 2: SEMÁFORO ÓPTIMO -->
        <div class="bg-white p-4 sm:p-5 rounded-2xl border border-slate-200/80 shadow-xs flex items-center gap-3.5">
          <div class="w-11 h-11 rounded-2xl bg-emerald-50 text-emerald-600 flex items-center justify-center text-lg shrink-0 border border-emerald-100">
            <i class="fa-solid fa-circle-check"></i>
          </div>
          <div>
            <span class="text-xs text-slate-500 block font-semibold">Unidades en Rango Óptimo</span>
            <div class="flex items-baseline gap-1.5">
              <span class="text-xl sm:text-2xl font-black text-emerald-600">${optimalPercent}%</span>
              <span class="text-xs text-slate-400 font-bold">(${optimalCount}/${sampledUnits.length})</span>
            </div>
            <span class="text-[10px] text-emerald-600 font-bold">Condiciones ideales</span>
          </div>
        </div>

        <!-- KPI 3: ALERTAS / CRÍTICOS -->
        <div class="bg-white p-4 sm:p-5 rounded-2xl border border-slate-200/80 shadow-xs flex items-center gap-3.5">
          <div class="w-11 h-11 rounded-2xl ${criticalCount > 0 ? 'bg-rose-50 text-rose-600 border-rose-200' : alertCount > 0 ? 'bg-amber-50 text-amber-600 border-amber-200' : 'bg-slate-50 text-slate-400 border-slate-200'} border flex items-center justify-center text-lg shrink-0">
            <i class="fa-solid fa-triangle-exclamation"></i>
          </div>
          <div>
            <span class="text-xs text-slate-500 block font-semibold">Alertas & Críticos</span>
            <div class="flex items-baseline gap-1.5">
              <span class="text-xl sm:text-2xl font-black ${criticalCount > 0 ? 'text-rose-600' : alertCount > 0 ? 'text-amber-600' : 'text-slate-700'}">${alertCount + criticalCount}</span>
              <span class="text-xs text-slate-400 font-bold">unidades</span>
            </div>
            <span class="text-[10px] ${criticalCount > 0 ? 'text-rose-600 font-bold' : alertCount > 0 ? 'text-amber-600 font-bold' : 'text-slate-400'}">
              ${criticalCount > 0 ? `${criticalCount} críticas (actuar ya)` : alertCount > 0 ? `${alertCount} en atención preventiva` : 'Sin anomalías registradas'}
            </span>
          </div>
        </div>

        <!-- KPI 4: TEMPERATURA Y pH MEDIO -->
        <div class="bg-white p-4 sm:p-5 rounded-2xl border border-slate-200/80 shadow-xs flex items-center gap-3.5">
          <div class="w-11 h-11 rounded-2xl bg-indigo-50 text-indigo-600 flex items-center justify-center text-lg shrink-0 border border-indigo-100">
            <i class="fa-solid fa-temperature-half"></i>
          </div>
          <div>
            <span class="text-xs text-slate-500 block font-semibold">Temp & pH Medios</span>
            <div class="flex items-baseline gap-2">
              <span class="text-base sm:text-lg font-black text-slate-800">${avgTemp} °C</span>
              <span class="text-slate-300 font-bold">|</span>
              <span class="text-base sm:text-lg font-black text-slate-800">pH ${avgPH}</span>
            </div>
            <span class="text-[10px] text-slate-400 font-medium">Tilapia óptimo: 26-30°C / pH 6.8-8.2</span>
          </div>
        </div>
      </div>

      <!-- BARRA DE FILTROS Y BÚSQUEDA -->
      <div class="bg-white p-4 rounded-2xl border border-slate-200 shadow-xs space-y-3">
        <div class="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3">
          <!-- Input de búsqueda -->
          <div class="relative flex-1">
            <i class="fa-solid fa-magnifying-glass absolute left-3.5 top-3 text-slate-400 text-xs"></i>
            <input type="text" value="${escapeHtml(activeWaterQualitySearch)}" oninput="searchWaterQuality(this.value)" placeholder="Buscar por estanque (E-01), geomembrana (G-01), lote, operario o notas..." class="w-full pl-9 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-xs font-semibold focus:bg-white focus:ring-2 focus:ring-cyan-500 transition">
          </div>

          <div class="flex items-center gap-2 self-end sm:self-center">
            <span class="text-xs text-slate-500 font-bold whitespace-nowrap">
              ${displayedUnits.length} de ${totalUnits} unidades
            </span>
          </div>
        </div>

        <!-- Filtros Rápidos (Pills) -->
        <div class="flex flex-wrap items-center justify-between gap-2 pt-2 border-t border-slate-100 text-xs font-bold">
          <!-- Filtro de Unidad -->
          <div class="flex items-center gap-1.5 flex-wrap">
            <span class="text-[11px] text-slate-400 uppercase font-black mr-1">Unidades:</span>
            <button onclick="filterWaterQuality('todos')" class="px-2.5 py-1 rounded-lg transition cursor-pointer ${activeWaterQualityFilter === 'todos' ? 'bg-cyan-900 text-white shadow-2xs' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}">
              Todas (13)
            </button>
            <button onclick="filterWaterQuality('estanques')" class="px-2.5 py-1 rounded-lg transition cursor-pointer ${activeWaterQualityFilter === 'estanques' ? 'bg-cyan-900 text-white shadow-2xs' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}">
              <i class="fa-solid fa-water mr-1"></i> Solo Estanques (10)
            </button>
            <button onclick="filterWaterQuality('geomembranas')" class="px-2.5 py-1 rounded-lg transition cursor-pointer ${activeWaterQualityFilter === 'geomembranas' ? 'bg-cyan-900 text-white shadow-2xs' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}">
              <i class="fa-solid fa-circle-notch mr-1"></i> Geomembranas (3)
            </button>
          </div>

          <!-- Filtro de Estado -->
          <div class="flex items-center gap-1.5 flex-wrap">
            <span class="text-[11px] text-slate-400 uppercase font-black mr-1">Estado:</span>
            <button onclick="filterWaterQualityStatus('todos')" class="px-2.5 py-1 rounded-lg transition cursor-pointer ${activeWaterQualityStatus === 'todos' ? 'bg-slate-800 text-white' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}">
              Todos
            </button>
            <button onclick="filterWaterQualityStatus('optimo')" class="px-2.5 py-1 rounded-lg transition cursor-pointer ${activeWaterQualityStatus === 'optimo' ? 'bg-emerald-600 text-white' : 'bg-emerald-50 text-emerald-700 hover:bg-emerald-100 border border-emerald-200'}">
              <span class="w-1.5 h-1.5 rounded-full bg-emerald-400 inline-block mr-1"></span> Óptimo
            </button>
            <button onclick="filterWaterQualityStatus('alerta')" class="px-2.5 py-1 rounded-lg transition cursor-pointer ${activeWaterQualityStatus === 'alerta' ? 'bg-amber-600 text-white' : 'bg-amber-50 text-amber-800 hover:bg-amber-100 border border-amber-200'}">
              <span class="w-1.5 h-1.5 rounded-full bg-amber-400 inline-block mr-1"></span> Alerta
            </button>
            <button onclick="filterWaterQualityStatus('critico')" class="px-2.5 py-1 rounded-lg transition cursor-pointer ${activeWaterQualityStatus === 'critico' ? 'bg-rose-600 text-white' : 'bg-rose-50 text-rose-700 hover:bg-rose-100 border border-rose-200'}">
              <span class="w-1.5 h-1.5 rounded-full bg-rose-400 inline-block mr-1"></span> Crítico
            </button>
          </div>
        </div>
      </div>

      <!-- SECCIÓN 1: SEMÁFORO EN VIVO POR ESTANQUE / GEOMEMBRANA -->
      <div>
        <div class="flex items-center justify-between mb-3">
          <h2 class="text-base sm:text-lg font-black text-slate-800 flex items-center gap-2">
            <i class="fa-solid fa-chart-simple text-cyan-600"></i>
            <span>Semáforo Fisicoquímico en Vivo por Unidad (${displayedUnits.length})</span>
          </h2>
          <span class="text-xs text-slate-400 font-semibold hidden sm:inline">Último valor registrado de cada estanque</span>
        </div>

        <div class="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
          ${displayedUnits.map(unit => {
            const isGeo = unit.type === 'geomembrana';
            const sample = lastSampleByUnit[unit.id];
            const activeBatch = (appData.batches || []).find(b => b.unitId === unit.id && b.status === 'activo');
            const diag = getWaterQualityDiagnostic(sample);

            const doVal = sample && sample.dissolvedOxygen !== null && sample.dissolvedOxygen !== undefined ? parseFloat(sample.dissolvedOxygen).toFixed(1) : '--';
            const tempVal = sample && sample.temperature !== null && sample.temperature !== undefined ? parseFloat(sample.temperature).toFixed(1) : '--';
            const phVal = sample && sample.ph !== null && sample.ph !== undefined ? parseFloat(sample.ph).toFixed(1) : '--';
            const ammVal = sample && sample.ammonia !== null && sample.ammonia !== undefined ? parseFloat(sample.ammonia).toFixed(2) : '--';
            const secchiVal = sample && sample.secchi !== null && sample.secchi !== undefined ? parseFloat(sample.secchi).toFixed(0) : '--';

            return `
              <div class="bg-white rounded-2xl border ${diag.cardBorder} p-4 sm:p-5 shadow-xs flex flex-col justify-between transition hover:shadow-md">
                <!-- CABECERA DE UNIDAD -->
                <div>
                  <div class="flex items-start justify-between gap-3 mb-2.5">
                    <div class="flex items-center gap-2.5">
                      <div class="w-10 h-10 rounded-xl ${isGeo ? 'bg-cyan-50 text-cyan-700 border border-cyan-200' : 'bg-emerald-50 text-emerald-700 border border-emerald-200'} flex items-center justify-center font-black text-sm shrink-0">
                        <i class="fa-solid ${isGeo ? 'fa-circle-notch' : 'fa-water'}"></i>
                      </div>
                      <div>
                        <div class="flex items-center gap-2">
                          <h3 class="font-black text-slate-900 text-sm sm:text-base leading-tight whitespace-nowrap">${escapeHtml(unit.name)}</h3>
                          <span class="text-[10px] uppercase font-black px-1.5 py-0.5 rounded ${isGeo ? 'bg-cyan-100 text-cyan-800' : 'bg-emerald-100 text-emerald-800'}">
                            ${isGeo ? 'Geomembrana' : 'Estanque'}
                          </span>
                        </div>
                        <span class="text-xs text-slate-500 font-semibold block truncate">
                          ${activeBatch ? `<span class="text-cyan-700 font-bold">${escapeHtml(activeBatch.name || activeBatch.id)}</span> (${escapeHtml(activeBatch.species || 'Tilapia')})` : '<span class="text-slate-400 italic">Sin lote activo</span>'}
                        </span>
                      </div>
                    </div>

                    <!-- BADGE SEMÁFORO -->
                    <span class="px-2.5 py-1 rounded-full text-[10px] font-black border flex items-center gap-1.5 shrink-0 ${diag.badgeClass}">
                      <span class="w-2 h-2 rounded-full ${diag.dotColor}"></span>
                      ${diag.statusLabel}
                    </span>
                  </div>

                  <!-- TIEMPO DEL MUESTREO -->
                  <div class="flex items-center justify-between text-[11px] text-slate-400 font-medium py-1.5 border-y border-slate-100 mb-3">
                    <span><i class="fa-regular fa-clock mr-1 text-slate-300"></i> ${sample ? `${sample.date} • ${sample.time || ''} (${sample.period || 'Muestreo'})` : 'Sin mediciones'}</span>
                    <span>${sample && sample.operator ? `<i class="fa-regular fa-user mr-1 text-slate-300"></i>${escapeHtml(sample.operator)}` : ''}</span>
                  </div>

                  <!-- MATRIZ DE PARÁMETROS -->
                  <div class="grid grid-cols-4 gap-2 text-center mb-3">
                    <!-- O2 -->
                    <div class="p-2 rounded-xl bg-slate-50 border border-slate-100">
                      <span class="text-[10px] font-bold text-slate-400 uppercase block">O₂ Disuelto</span>
                      <span class="text-sm font-black ${sample && parseFloat(doVal) < 3.0 ? 'text-rose-600' : sample && parseFloat(doVal) < 4.5 ? 'text-amber-600' : 'text-slate-800'}">${doVal}</span>
                      <span class="text-[9px] text-slate-400 block font-semibold">mg/L</span>
                    </div>

                    <!-- Temp -->
                    <div class="p-2 rounded-xl bg-slate-50 border border-slate-100">
                      <span class="text-[10px] font-bold text-slate-400 uppercase block">Temp</span>
                      <span class="text-sm font-black text-slate-800">${tempVal}</span>
                      <span class="text-[9px] text-slate-400 block font-semibold">°C</span>
                    </div>

                    <!-- pH -->
                    <div class="p-2 rounded-xl bg-slate-50 border border-slate-100">
                      <span class="text-[10px] font-bold text-slate-400 uppercase block">pH</span>
                      <span class="text-sm font-black text-slate-800">${phVal}</span>
                      <span class="text-[9px] text-slate-400 block font-semibold">unid</span>
                    </div>

                    <!-- Secchi o Amonio -->
                    <div class="p-2 rounded-xl bg-slate-50 border border-slate-100">
                      <span class="text-[10px] font-bold text-slate-400 uppercase block">${isGeo ? 'Amonio' : 'Secchi'}</span>
                      <span class="text-sm font-black text-slate-800">${isGeo ? ammVal : secchiVal}</span>
                      <span class="text-[9px] text-slate-400 block font-semibold">${isGeo ? 'mg/L' : 'cm'}</span>
                    </div>
                  </div>

                  <!-- RECOMENDACIÓN ZOOTÉCNICA / ALERTA -->
                  <div class="p-2.5 rounded-xl text-xs mb-3 font-medium ${diag.overallStatus === 'critico' ? 'bg-rose-50 text-rose-800 border border-rose-200' : diag.overallStatus === 'alerta' ? 'bg-amber-50 text-amber-800 border border-amber-200' : 'bg-emerald-50/60 text-emerald-800 border border-emerald-100'}">
                    <p class="leading-relaxed text-[11px]">
                      <strong class="font-bold block mb-0.5">${diag.overallStatus === 'critico' ? '🚨 Acción Zootécnica Inmediata:' : diag.overallStatus === 'alerta' ? '⚠️ Precaución Técnica:' : '✅ Estado Sanitario:'}</strong>
                      ${diag.recommendation}
                    </p>
                  </div>
                </div>

                <!-- ACCIONES INFERIORES -->
                <div class="pt-3 border-t border-slate-100 flex items-center justify-end gap-2">
                  <div class="flex items-center gap-2">
                    ${sample && isMasterUser() ? `
                      <button onclick="openEditWaterQualityModal('${sample.id}')" class="p-1.5 text-slate-400 hover:text-cyan-600 transition cursor-pointer" title="Editar último muestreo">
                        <i class="fa-solid fa-pen text-xs"></i>
                      </button>
                    ` : ''}
                    ${isMasterUser() ? `
                      <button onclick="openModalNewWaterQuality('${unit.id}')" class="px-3.5 py-1.5 bg-cyan-600 hover:bg-cyan-500 text-white rounded-xl text-xs font-bold transition flex items-center gap-1.5 shadow-2xs cursor-pointer">
                        <i class="fa-solid fa-plus text-[10px]"></i> Medir O₂ / pH
                      </button>
                    ` : ''}
                  </div>
                </div>
              </div>
            `;
          }).join('')}
        </div>
      </div>

      <!-- SECCIÓN 2: HISTORIAL COMPLETO DE MUESTREOS -->
      <div class="bg-white rounded-2xl border border-slate-200 shadow-xs overflow-hidden">
        <div class="p-4 sm:p-5 border-b border-slate-200 flex flex-col sm:flex-row sm:items-center justify-between gap-3">
          <div>
            <h2 class="text-base sm:text-lg font-black text-slate-900 flex items-center gap-2">
              <i class="fa-solid fa-table-list text-cyan-600"></i>
              <span>Historial de Mediciones & Monitoreos de Campo</span>
            </h2>
            <p class="text-xs text-slate-500">Planilla cronológica de toma de datos fisicoquímicos en campo</p>
          </div>

          <div class="flex items-center gap-2">
            <span class="text-xs text-slate-400 font-bold">${filteredHistory.length} registros</span>
          </div>
        </div>

        <div class="overflow-x-auto">
          <table class="w-full text-xs text-left">
            <thead class="bg-slate-50 text-slate-600 uppercase font-bold border-b border-slate-200 tracking-wider">
              <tr>
                <th class="p-3">Fecha / Hora</th>
                <th class="p-3">Unidad / Lote</th>
                <th class="p-3 text-center">Período</th>
                <th class="p-3 text-center">O₂ (mg/L)</th>
                <th class="p-3 text-center">Temp (°C)</th>
                <th class="p-3 text-center">pH</th>
                <th class="p-3 text-center">Amonio</th>
                <th class="p-3 text-center">Nitritos</th>
                <th class="p-3 text-center">Secchi</th>
                <th class="p-3">Estado</th>
                <th class="p-3">Operario / Notas</th>
                <th class="p-3 text-right">Acciones</th>
              </tr>
            </thead>
            <tbody class="divide-y divide-slate-100">
              ${filteredHistory.length === 0 ? `
                <tr>
                  <td colspan="12" class="p-8 text-center text-slate-400">
                    <i class="fa-solid fa-droplet-slash text-3xl mb-2 text-slate-300 block"></i>
                    No se encontraron registros de calidad de agua con los filtros aplicados.
                  </td>
                </tr>
              ` : filteredHistory.map(row => {
                const u = appData.units.find(x => x.id === row.unitId);
                const b = appData.batches.find(x => x.id === row.batchId);
                const diag = getWaterQualityDiagnostic(row);
                const doNum = parseFloat(row.dissolvedOxygen);

                return `
                  <tr class="hover:bg-slate-50/80 transition">
                    <td class="p-3 font-bold text-slate-800 whitespace-nowrap">
                      ${row.date}
                      <span class="text-[10px] text-slate-400 block font-normal">${row.time || '--'}</span>
                    </td>
                    <td class="p-3 whitespace-nowrap">
                      <span class="font-extrabold text-slate-900">${u ? escapeHtml(u.name) : row.unitId}</span>
                      <span class="text-[10px] text-cyan-700 block font-semibold truncate">${b ? escapeHtml(b.name || b.id) : '<span class="text-slate-400 italic">Sin lote</span>'}</span>
                    </td>
                    <td class="p-3 text-center whitespace-nowrap">
                      <span class="px-2 py-0.5 rounded-full text-[10px] font-bold ${(row.period === 'manana' || row.period === 'mañana') ? 'bg-sky-50 text-sky-700 border border-sky-200' : row.period === 'tarde' ? 'bg-amber-50 text-amber-700 border border-amber-200' : 'bg-indigo-50 text-indigo-700 border border-indigo-200'}">
                        ${(row.period === 'manana' || row.period === 'mañana') ? 'Mañana (06h)' : row.period === 'tarde' ? 'Tarde (16h)' : row.period === 'noche' ? 'Noche' : 'General'}
                      </span>
                    </td>
                    <td class="p-3 text-center whitespace-nowrap">
                      <span class="font-black ${doNum < 3.0 ? 'text-rose-600 bg-rose-50 px-2 py-0.5 rounded' : doNum < 4.5 ? 'text-amber-600 font-bold' : 'text-emerald-700 font-black'}">
                        ${row.dissolvedOxygen !== null && row.dissolvedOxygen !== undefined ? `${parseFloat(row.dissolvedOxygen).toFixed(1)}` : '--'}
                      </span>
                    </td>
                    <td class="p-3 text-center font-bold text-slate-700 whitespace-nowrap">
                      ${row.temperature !== null && row.temperature !== undefined ? `${parseFloat(row.temperature).toFixed(1)}°` : '--'}
                    </td>
                    <td class="p-3 text-center font-bold text-slate-700 whitespace-nowrap">
                      ${row.ph !== null && row.ph !== undefined ? `${parseFloat(row.ph).toFixed(1)}` : '--'}
                    </td>
                    <td class="p-3 text-center text-slate-600 whitespace-nowrap">
                      ${row.ammonia !== null && row.ammonia !== undefined && row.ammonia !== '' ? `${parseFloat(row.ammonia).toFixed(2)}` : '--'}
                    </td>
                    <td class="p-3 text-center text-slate-600 whitespace-nowrap">
                      ${row.nitrite !== null && row.nitrite !== undefined && row.nitrite !== '' ? `${parseFloat(row.nitrite).toFixed(2)}` : '--'}
                    </td>
                    <td class="p-3 text-center text-slate-600 whitespace-nowrap">
                      ${row.secchi !== null && row.secchi !== undefined && row.secchi !== '' ? `${parseFloat(row.secchi).toFixed(0)} cm` : '--'}
                    </td>
                    <td class="p-3 whitespace-nowrap">
                      <span class="px-2 py-0.5 rounded-full text-[10px] font-black border ${diag.badgeClass}">
                        ${diag.statusLabel}
                      </span>
                    </td>
                    <td class="p-3 max-w-[200px]">
                      <span class="font-bold text-slate-700 block text-[11px] truncate">${escapeHtml(row.operator || 'Operario')}</span>
                      ${row.correctiveAction ? `<span class="text-[10px] text-cyan-800 font-semibold block truncate" title="${escapeHtml(row.correctiveAction)}"><i class="fa-solid fa-wrench mr-1 text-cyan-600"></i>${escapeHtml(row.correctiveAction)}</span>` : ''}
                      ${row.notes ? `<span class="text-[10px] text-slate-400 block truncate" title="${escapeHtml(row.notes)}">${escapeHtml(row.notes)}</span>` : ''}
                    </td>
                    <td class="p-3 text-right whitespace-nowrap">
                      ${isMasterUser() ? `
                        <button onclick="openEditWaterQualityModal('${row.id}')" class="p-1.5 text-slate-400 hover:text-cyan-600 transition cursor-pointer" title="Editar">
                          <i class="fa-solid fa-pen"></i>
                        </button>
                        <button onclick="deleteWaterQuality('${row.id}')" class="p-1.5 text-slate-400 hover:text-rose-600 transition cursor-pointer ml-1" title="Eliminar">
                          <i class="fa-solid fa-trash"></i>
                        </button>
                      ` : `
                        <span class="text-slate-300 text-xs">—</span>
                      `}
                    </td>
                  </tr>
                `;
              }).join('')}
            </tbody>
          </table>
        </div>
      </div>

      <!-- SECCIÓN 3: GUÍA TÉCNICA Y SEMÁFORO ZOOTÉCNICO DE REFERENCIA -->
      <div class="bg-gradient-to-br from-slate-900 to-slate-800 text-white p-5 sm:p-6 rounded-2xl shadow-sm space-y-4">
        <div class="flex items-center gap-3">
          <div class="w-10 h-10 rounded-xl bg-cyan-500/20 text-cyan-300 border border-cyan-500/30 flex items-center justify-center text-lg">
            <i class="fa-solid fa-book-bookmark"></i>
          </div>
          <div>
            <h3 class="text-base font-black text-white">Guía de Parámetros Zootécnicos Óptimos para Piscicultura Continental</h3>
            <p class="text-xs text-slate-300">Estándares para cultivo intensivo y semi-intensivo de Tilapia Roja, Plateada y Peces Nativos</p>
          </div>
        </div>

        <div class="grid grid-cols-1 md:grid-cols-3 gap-4 text-xs pt-2">
          <div class="p-3.5 bg-slate-800/80 rounded-xl border border-slate-700/80 space-y-1.5">
            <div class="flex items-center justify-between text-cyan-300 font-black">
              <span><i class="fa-solid fa-lungs mr-1"></i> Oxígeno Disuelto (O₂)</span>
              <span class="text-[10px] bg-cyan-900/50 px-2 py-0.5 rounded border border-cyan-700/60">> 4.5 mg/L</span>
            </div>
            <p class="text-[11px] text-slate-300 leading-relaxed">
              <strong>Óptimo:</strong> > 4.5 mg/L.<br>
              <strong>Alerta (3.0 - 4.5 mg/L):</strong> Reducir alimento al 50%.<br>
              <strong>Crítico (&lt; 3.0 mg/L):</strong> Asfixia inminente. Activar aireadores ya.
            </p>
          </div>

          <div class="p-3.5 bg-slate-800/80 rounded-xl border border-slate-700/80 space-y-1.5">
            <div class="flex items-center justify-between text-amber-300 font-black">
              <span><i class="fa-solid fa-temperature-half mr-1"></i> Temperatura & pH</span>
              <span class="text-[10px] bg-amber-900/50 px-2 py-0.5 rounded border border-amber-700/60">26-30°C | pH 6.8-8.2</span>
            </div>
            <p class="text-[11px] text-slate-300 leading-relaxed">
              <strong>Temperatura:</strong> 26 a 30 °C ideal para apetito y conversión. Por debajo de 22°C se detiene el crecimiento.<br>
              <strong>pH:</strong> 6.8 a 8.2. Valores > 8.5 vuelven tóxico el amoníaco.
            </p>
          </div>

          <div class="p-3.5 bg-slate-800/80 rounded-xl border border-slate-700/80 space-y-1.5">
            <div class="flex items-center justify-between text-emerald-300 font-black">
              <span><i class="fa-solid fa-flask-vial mr-1"></i> Nitrógeno & Turbidez</span>
              <span class="text-[10px] bg-emerald-900/50 px-2 py-0.5 rounded border border-emerald-700/60">Secchi 25-40 cm</span>
            </div>
            <p class="text-[11px] text-slate-300 leading-relaxed">
              <strong>Amonio Total:</strong> Mantener &lt; 0.05 mg/L.<br>
              <strong>Nitritos (NO₂):</strong> &lt; 0.1 mg/L (letal &gt; 0.3 mg/L).<br>
              <strong>Disco Secchi:</strong> 25 a 40 cm (equilibrio de fitoplancton).
            </p>
          </div>
        </div>
      </div>
    </div>
  `;

  container.innerHTML = html;
}

// ----------------------------------------------------
// ACCIONES DE FORMULARIOS Y MODALES: CALIDAD DEL AGUA
// ----------------------------------------------------
function openModalNewWaterQuality(preselectedUnitId = null) {
  const modal = document.getElementById('modal-new-water-quality');
  const unitSelect = document.getElementById('wq-unit-id');
  const dateInput = document.getElementById('wq-date');
  const timeInput = document.getElementById('wq-time');
  const periodSelect = document.getElementById('wq-period');

  if (!modal || !unitSelect) return;

  // Poblar select de unidades
  unitSelect.innerHTML = '<option value="">-- Seleccionar Estanque / Geomembrana --</option>' + 
    (appData.units || []).map(u => `<option value="${u.id}">${escapeHtml(u.name)} (${u.type === 'geomembrana' ? 'Geomembrana' : 'Estanque'})</option>`).join('');

  if (preselectedUnitId) {
    unitSelect.value = preselectedUnitId;
  } else if (appData.units && appData.units.length > 0) {
    unitSelect.value = appData.units[0].id;
  }

  onWaterQualityUnitChange(unitSelect, 'wq-batch-name', 'wq-batch-id');

  // Asignar fecha y hora actual local
  const now = new Date();
  const todayStr = now.toLocaleDateString('sv'); // 'YYYY-MM-DD'
  const timeStr = now.toTimeString().slice(0, 5); // 'HH:MM'
  const currentHour = now.getHours();

  if (dateInput) dateInput.value = todayStr;
  if (timeInput) timeInput.value = timeStr;

  if (periodSelect) {
    if (currentHour < 12) periodSelect.value = 'manana';
    else if (currentHour < 18) periodSelect.value = 'tarde';
    else periodSelect.value = 'noche';
  }

  // Pre-llenar valores típicos para rapidez
  const doInput = document.getElementById('wq-do');
  const tempInput = document.getElementById('wq-temp');
  const phInput = document.getElementById('wq-ph');
  const ammInput = document.getElementById('wq-ammonia');
  const nitInput = document.getElementById('wq-nitrite');
  const secchiInput = document.getElementById('wq-secchi');
  const alkInput = document.getElementById('wq-alkalinity');
  const opInput = document.getElementById('wq-operator');
  const actInput = document.getElementById('wq-action');
  const notesInput = document.getElementById('wq-notes');

  if (doInput) doInput.value = '5.4';
  if (tempInput) tempInput.value = '27.5';
  if (phInput) phInput.value = '7.5';
  if (ammInput) ammInput.value = '0.02';
  if (nitInput) nitInput.value = '0.02';
  if (secchiInput) secchiInput.value = '32';
  if (alkInput) alkInput.value = '80';
  if (opInput) opInput.value = (currentUser && currentUser.name) ? currentUser.name : 'Operario';
  if (actInput) actInput.value = '';
  if (notesInput) notesInput.value = '';

  updateLiveWqDiagnostic('');
  openModal('modal-new-water-quality');
}

function submitNewWaterQuality(e) {
  e.preventDefault();
  const unitId = document.getElementById('wq-unit-id').value;
  const batchId = document.getElementById('wq-batch-id').value;
  const date = document.getElementById('wq-date').value;
  const time = document.getElementById('wq-time').value;
  const period = document.getElementById('wq-period').value;
  const doVal = document.getElementById('wq-do').value;
  const tempVal = document.getElementById('wq-temp').value;
  const phVal = document.getElementById('wq-ph').value;
  const ammVal = document.getElementById('wq-ammonia').value;
  const nitVal = document.getElementById('wq-nitrite').value;
  const secchiVal = document.getElementById('wq-secchi').value;
  const alkVal = document.getElementById('wq-alkalinity').value;
  const operator = document.getElementById('wq-operator').value;
  const correctiveAction = document.getElementById('wq-action').value;
  const notes = document.getElementById('wq-notes').value;

  if (!unitId) {
    showNotification('Selecciona una unidad o estanque.', 'error');
    return;
  }
  if (!date) {
    showNotification('Indica la fecha de la medición.', 'error');
    return;
  }
  if (doVal === '') {
    showNotification('Ingresa el valor de Oxígeno Disuelto.', 'error');
    return;
  }

  if (!Array.isArray(appData.waterQuality)) appData.waterQuality = [];

  const newRecord = {
    id: 'wq_' + Date.now(),
    unitId,
    batchId: batchId || null,
    date,
    time: time || '08:00',
    period: period || 'manana',
    dissolvedOxygen: parseFloat(doVal),
    temperature: tempVal !== '' ? parseFloat(tempVal) : 27.0,
    ph: phVal !== '' ? parseFloat(phVal) : 7.2,
    ammonia: ammVal !== '' ? parseFloat(ammVal) : null,
    nitrite: nitVal !== '' ? parseFloat(nitVal) : null,
    secchi: secchiVal !== '' ? parseFloat(secchiVal) : null,
    alkalinity: alkVal !== '' ? parseFloat(alkVal) : null,
    correctiveAction: correctiveAction.trim(),
    notes: notes.trim(),
    operator: operator.trim() || 'Operario de Campo',
    createdAt: new Date().toISOString()
  };

  appData.waterQuality.unshift(newRecord);
  PiscicolaStorage.save(appData);

  closeModal('modal-new-water-quality');
  showNotification('Muestreo de Calidad del Agua guardado con éxito.', 'success');
  renderCalidadAgua();
}

function openEditWaterQualityModal(id) {
  const record = (appData.waterQuality || []).find(r => r.id === id);
  if (!record) {
    showNotification('Registro no encontrado.', 'error');
    return;
  }

  const modal = document.getElementById('modal-edit-water-quality');
  const unitSelect = document.getElementById('edit-wq-unit-id');
  if (!modal || !unitSelect) return;

  unitSelect.innerHTML = '<option value="">-- Seleccionar Unidad --</option>' + 
    (appData.units || []).map(u => `<option value="${u.id}">${escapeHtml(u.name)} (${u.type === 'geomembrana' ? 'Geomembrana' : 'Estanque'})</option>`).join('');

  document.getElementById('edit-wq-id').value = record.id;
  unitSelect.value = record.unitId;
  onWaterQualityUnitChange(unitSelect, 'edit-wq-batch-name', 'edit-wq-batch-id');

  if (record.batchId) {
    document.getElementById('edit-wq-batch-id').value = record.batchId;
  }

  document.getElementById('edit-wq-date').value = record.date || '';
  document.getElementById('edit-wq-time').value = record.time || '';
  document.getElementById('edit-wq-period').value = record.period || 'manana';
  document.getElementById('edit-wq-do').value = record.dissolvedOxygen !== null && record.dissolvedOxygen !== undefined ? record.dissolvedOxygen : '';
  document.getElementById('edit-wq-temp').value = record.temperature !== null && record.temperature !== undefined ? record.temperature : '';
  document.getElementById('edit-wq-ph').value = record.ph !== null && record.ph !== undefined ? record.ph : '';
  document.getElementById('edit-wq-ammonia').value = record.ammonia !== null && record.ammonia !== undefined ? record.ammonia : '';
  document.getElementById('edit-wq-nitrite').value = record.nitrite !== null && record.nitrite !== undefined ? record.nitrite : '';
  document.getElementById('edit-wq-secchi').value = record.secchi !== null && record.secchi !== undefined ? record.secchi : '';
  document.getElementById('edit-wq-alkalinity').value = record.alkalinity !== null && record.alkalinity !== undefined ? record.alkalinity : '';
  document.getElementById('edit-wq-operator').value = record.operator || '';
  document.getElementById('edit-wq-action').value = record.correctiveAction || '';
  document.getElementById('edit-wq-notes').value = record.notes || '';

  updateLiveWqDiagnostic('edit-');
  openModal('modal-edit-water-quality');
}

function submitEditWaterQuality(e) {
  e.preventDefault();
  const id = document.getElementById('edit-wq-id').value;
  const record = (appData.waterQuality || []).find(r => r.id === id);
  if (!record) {
    showNotification('Registro no encontrado.', 'error');
    return;
  }

  const unitId = document.getElementById('edit-wq-unit-id').value;
  const batchId = document.getElementById('edit-wq-batch-id').value;
  const date = document.getElementById('edit-wq-date').value;
  const time = document.getElementById('edit-wq-time').value;
  const period = document.getElementById('edit-wq-period').value;
  const doVal = document.getElementById('edit-wq-do').value;
  const tempVal = document.getElementById('edit-wq-temp').value;
  const phVal = document.getElementById('edit-wq-ph').value;
  const ammVal = document.getElementById('edit-wq-ammonia').value;
  const nitVal = document.getElementById('edit-wq-nitrite').value;
  const secchiVal = document.getElementById('edit-wq-secchi').value;
  const alkVal = document.getElementById('edit-wq-alkalinity').value;
  const operator = document.getElementById('edit-wq-operator').value;
  const correctiveAction = document.getElementById('edit-wq-action').value;
  const notes = document.getElementById('edit-wq-notes').value;

  record.unitId = unitId;
  record.batchId = batchId || null;
  record.date = date;
  record.time = time;
  record.period = period;
  record.dissolvedOxygen = parseFloat(doVal);
  record.temperature = tempVal !== '' ? parseFloat(tempVal) : record.temperature;
  record.ph = phVal !== '' ? parseFloat(phVal) : record.ph;
  record.ammonia = ammVal !== '' ? parseFloat(ammVal) : null;
  record.nitrite = nitVal !== '' ? parseFloat(nitVal) : null;
  record.secchi = secchiVal !== '' ? parseFloat(secchiVal) : null;
  record.alkalinity = alkVal !== '' ? parseFloat(alkVal) : null;
  record.operator = operator.trim();
  record.correctiveAction = correctiveAction.trim();
  record.notes = notes.trim();
  record.updatedAt = new Date().toISOString();

  PiscicolaStorage.save(appData);
  closeModal('modal-edit-water-quality');
  showNotification('Muestreo actualizado correctamente.', 'success');
  renderCalidadAgua();
}

function deleteWaterQuality(id) {
  if (!isMasterUser()) {
    showNotification('Solo usuarios Master pueden eliminar registros.', 'error');
    return;
  }
  if (!confirm('¿Deseas eliminar este registro de calidad del agua?')) return;

  appData.waterQuality = (appData.waterQuality || []).filter(r => r.id !== id);
  PiscicolaStorage.save(appData);
  showNotification('Registro eliminado.', 'info');
  renderCalidadAgua();
}

function exportWaterQualityCSV() {
  const records = appData.waterQuality || [];
  if (records.length === 0) {
    showNotification('No hay registros de calidad del agua para exportar.', 'info');
    return;
  }

  let csv = 'ID,Fecha,Hora,Periodo,Unidad,Tipo,Lote,Oxigeno_mg_L,Temperatura_C,pH,Amonio_mg_L,Nitritos_mg_L,Secchi_cm,Alcalinidad,Operario,Accion_Correctiva,Notas\n';

  records.forEach(r => {
    const u = (appData.units || []).find(x => x.id === r.unitId);
    const b = (appData.batches || []).find(x => x.id === r.batchId);
    const unitName = u ? u.name : (r.unitId || '');
    const unitType = u ? u.type : '';
    const batchName = b ? (b.name || b.id) : (r.batchId || '');

    const line = [
      r.id,
      r.date || '',
      r.time || '',
      r.period || '',
      `"${unitName.replace(/"/g, '""')}"`,
      unitType,
      `"${batchName.replace(/"/g, '""')}"`,
      r.dissolvedOxygen !== null && r.dissolvedOxygen !== undefined ? r.dissolvedOxygen : '',
      r.temperature !== null && r.temperature !== undefined ? r.temperature : '',
      r.ph !== null && r.ph !== undefined ? r.ph : '',
      r.ammonia !== null && r.ammonia !== undefined ? r.ammonia : '',
      r.nitrite !== null && r.nitrite !== undefined ? r.nitrite : '',
      r.secchi !== null && r.secchi !== undefined ? r.secchi : '',
      r.alkalinity !== null && r.alkalinity !== undefined ? r.alkalinity : '',
      `"${(r.operator || '').replace(/"/g, '""')}"`,
      `"${(r.correctiveAction || '').replace(/"/g, '""')}"`,
      `"${(r.notes || '').replace(/"/g, '""')}"`
    ];
    csv += line.join(',') + '\n';
  });

  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `calidad_del_agua_${new Date().toLocaleDateString('sv')}.csv`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
  showNotification('Reporte CSV descargado con éxito.', 'success');
}

