function deleteFeedingRecord(feedId) {
  if (!isMasterUser()) {
    showNotification('Acceso de Solo Lectura: Tu cuenta es de perfil Lite.', 'warning');
    return;
  }
  const feed = (appData.feedings || []).find(f => f.id === feedId);
  if (!feed) return;

  if (!confirm(`¿Desea eliminar el suministro de ${feed.kg} kg en ${feed.unitId} (${formatDate(feed.date)})?\n\nAl eliminarlo, se reintegrarán automáticamente ${feed.kg} kg al inventario en bodega y se ajustará el Kárdex.`)) {
    return;
  }

  // 1. Restituir inventario
  let invItem = (appData.inventory || []).find(i =>
    (i.name && i.name.toLowerCase().trim() === (feed.feedBrand || '').toLowerCase().trim()) ||
    (isAlimentoCategory(i.category) && i.name.toLowerCase().includes((feed.feedBrand || '').toLowerCase()))
  );
  if (invItem) {
    invItem.currentStockKg = (invItem.currentStockKg || 0) + (feed.kg || 0);
    invItem.currentStock = invItem.currentStockKg;
  }

  // 2. Eliminar movimiento en Kardex
  appData.inventoryMovements = (appData.inventoryMovements || []).filter(m =>
    !(m.reference && m.reference.includes(feed.id))
  );

  // 3. Eliminar de feedings
  appData.feedings = (appData.feedings || []).filter(f => f.id !== feedId);

  recalculateKardexBalances();
  PiscicolaStorage.save(appData);
  showNotification(`Registro de alimentación eliminado y ${feed.kg} kg reintegrados a bodega.`, 'info');
  renderAlimentacion();
}

