function switchFinanceSubTab(subTab) {
  activeFinanceSubTab = subTab;
  renderFinanzas();
}

function renderPurchasesTable() {
  const allPurchases = appData.purchases || [];
  const filtered = allPurchases.filter(p => matchesFinanceFilter(p, 'purchases'));
  const grouped = groupRecordsByDate(filtered);

  const totalFilteredAmount = filtered.reduce((sum, p) => sum + (parseFloat(p.totalAmount) || 0), 0);
  const totalFilteredKg = filtered.reduce((sum, p) => {
    const items = (p.items && p.items.length > 0) ? p.items : [p];
    return sum + items.reduce((iSum, it) => {
      let q = parseFloat(it.quantity) || 0;
      if (it.unit && String(it.unit).toLowerCase().includes('bulto')) q *= 40;
      return iSum + q;
    }, 0);
  }, 0);

  const isFiltered = Boolean(financeFilterMonth || financeFilterDate || financeFilterSearch);

  return `
    <div class="space-y-4">
      <!-- Active Filter Pill Indicator if Filtered -->
      ${isFiltered ? `
        <div class="flex flex-col sm:flex-row sm:items-center justify-between bg-sky-50/90 border border-sky-200 px-4 py-2.5 rounded-xl text-xs text-sky-900 gap-2">
          <div class="flex items-center gap-2">
            <span class="w-2 h-2 rounded-full bg-sky-500 animate-pulse"></span>
            <span>Filtro activo: <strong>${financeFilterDate ? `Día ${formatDate(financeFilterDate)}` : (financeFilterMonth ? formatMonthName(financeFilterMonth) : '')}${financeFilterSearch ? ` (Búsqueda: "${escapeHtml(financeFilterSearch)}")` : ''}</strong></span>
          </div>
          <div class="flex items-center gap-3">
            <span class="font-black text-sky-950">${filtered.length} compras | Total: ${formatCurrency(totalFilteredAmount)}</span>
            <button onclick="resetFinanceFilters()" class="text-sky-700 hover:text-sky-950 font-bold underline cursor-pointer">Ver Todo</button>
          </div>
        </div>
      ` : ''}

      <div class="overflow-x-auto">
        <table class="w-full text-left text-xs">
          <thead class="bg-slate-50 text-slate-500 uppercase text-[10px] font-bold border-b border-slate-100">
            <tr>
              <th class="p-3">Fecha</th>
              <th class="p-3">Factura</th>
              <th class="p-3">Proveedor</th>
              <th class="p-3">Productos / Insumos</th>
              <th class="p-3 text-right">Cantidad Total</th>
              <th class="p-3 text-right">Total Pagado</th>
              <th class="p-3 text-center">Acciones</th>
            </tr>
          </thead>
          <tbody class="divide-y divide-slate-100">
            ${filtered.length === 0 ? `
              <tr>
                <td colspan="7" class="py-12 px-6 text-center">
                  <div class="max-w-xs mx-auto flex flex-col items-center">
                    <div class="w-12 h-12 bg-sky-50 text-sky-600 rounded-2xl flex items-center justify-center text-lg mb-2">
                      <i class="fa-solid fa-cart-shopping"></i>
                    </div>
                    <h4 class="text-xs font-bold text-slate-800">No hay compras en este periodo</h4>
                    <p class="text-[11px] text-slate-400 mt-0.5">No se encontraron facturas para el mes o día seleccionado.</p>
                    ${isFiltered ? `
                      <button onclick="resetFinanceFilters()" class="mt-3 px-3 py-1.5 bg-sky-600 hover:bg-sky-500 text-white rounded-xl text-xs font-bold transition shadow-xs cursor-pointer">
                        Restablecer Filtros y Ver Todo
                      </button>
                    ` : ''}
                  </div>
                </td>
              </tr>
            ` : grouped.map(group => `
              <!-- Group Date Header (Día específico con subtotal del día) -->
              <tr class="bg-slate-100/80 border-y border-slate-200">
                <td colspan="7" class="py-2 px-3 text-xs font-bold text-slate-800">
                  <div class="flex items-center justify-between flex-wrap gap-2">
                    <span class="flex items-center gap-1.5 text-sky-950 font-black">
                      <i class="fa-regular fa-calendar-days text-sky-600"></i>
                      <span>${formatFullDateName(group.date)}</span>
                    </span>
                    <span class="text-[11px] font-black text-slate-700 bg-white px-2.5 py-0.5 rounded-full border border-slate-200 shadow-2xs">
                      Subtotal Día: <strong class="text-sky-900">${formatCurrency(group.daySubtotal)}</strong> (${group.items.length} compra${group.items.length > 1 ? 's' : ''})
                    </span>
                  </div>
                </td>
              </tr>
              ${group.items.map(p => {
                const items = (p.items && p.items.length > 0) ? p.items : [{
                  description: p.description || 'Insumo',
                  quantity: p.quantity || 1,
                  unit: p.unit || 'kg',
                  unitPrice: p.unitPrice || 0,
                  totalAmount: p.totalAmount || 0,
                  category: p.category || 'Alimento Concentrado'
                }];

                const firstItem = items[0];
                const hasMultiple = items.length > 1;
                const totalQty = items.reduce((sum, it) => sum + (parseFloat(it.quantity) || 0), 0);
                const mainUnit = (items.every(it => it.unit === firstItem.unit)) ? firstItem.unit : 'unid';

                return `
                  <tr class="hover:bg-slate-50 transition group">
                    <td class="p-3 font-semibold text-slate-700 whitespace-nowrap">${formatDate(p.date)}</td>
                    <td class="p-3 whitespace-nowrap">
                      <button onclick="openViewPurchaseModal('${p.id}')" title="Ver detalle de factura" class="font-extrabold text-sky-700 hover:text-sky-900 hover:underline flex items-center gap-1.5 cursor-pointer">
                        <i class="fa-solid fa-file-invoice text-xs text-sky-500"></i>
                        <span>${escapeHtml(p.invoice || p.id)}</span>
                      </button>
                    </td>
                    <td class="p-3 font-bold text-slate-800 whitespace-nowrap">
                      <span class="truncate max-w-[150px] inline-block" title="${escapeHtml(p.supplier || '')}">${escapeHtml(p.supplier || 'N/A')}</span>
                    </td>
                    <td class="p-3 text-slate-700">
                      <div class="flex items-center gap-1.5 flex-wrap">
                        <span class="font-semibold text-slate-800">${escapeHtml(firstItem.description)}</span>
                        ${hasMultiple ? `
                          <button onclick="openViewPurchaseModal('${p.id}')" class="px-2 py-0.5 rounded-full text-[10px] bg-sky-100 text-sky-800 font-extrabold border border-sky-200 hover:bg-sky-200 transition cursor-pointer" title="Ver los ${items.length} productos comprados">
                            +${items.length - 1} producto${items.length - 1 > 1 ? 's' : ''} más
                          </button>
                        ` : ''}
                      </div>
                    </td>
                    <td class="p-3 font-bold text-right text-slate-800 whitespace-nowrap">
                      ${hasMultiple ? `${formatNumber(totalQty, 1)} ${mainUnit}` : `${formatNumber(firstItem.quantity, 1)} ${firstItem.unit}`}
                    </td>
                    <td class="p-3 font-black text-right text-slate-900 whitespace-nowrap">
                      ${formatCurrency(p.totalAmount)}
                    </td>
                    <td class="p-3 text-center whitespace-nowrap">
                      <div class="flex items-center justify-center gap-1.5">
                        <button onclick="openViewPurchaseModal('${p.id}')" title="Visualizar Factura Completa" class="px-2 py-1 rounded-lg bg-sky-50 hover:bg-sky-100 text-sky-700 flex items-center gap-1 text-[11px] font-bold transition cursor-pointer">
                          <i class="fa-solid fa-eye text-xs"></i> Ver
                        </button>
                        ${isMasterUser() ? `
                          <button onclick="openEditPurchaseModal('${p.id}')" title="Editar Factura y Productos" class="px-2 py-1 rounded-lg bg-amber-50 hover:bg-amber-100 text-amber-700 flex items-center gap-1 text-[11px] font-bold transition cursor-pointer">
                            <i class="fa-solid fa-pen-to-square text-xs"></i> Editar
                          </button>
                          <button onclick="deletePurchase('${p.id}')" title="Eliminar Compra" class="p-1 rounded-lg text-slate-300 hover:text-rose-600 transition cursor-pointer">
                            <i class="fa-solid fa-trash-can text-xs"></i>
                          </button>
                        ` : ''}
                      </div>
                    </td>
                  </tr>
                `;
              }).join('')}
            `).join('')}
          </tbody>
          ${filtered.length > 0 ? `
            <tfoot class="bg-slate-50 border-t-2 border-slate-200 text-xs font-black">
              <tr>
                <td colspan="4" class="p-3 text-slate-800 uppercase text-[11px]">
                  Total Compras ${isFiltered ? 'en Periodo Filtrado' : 'Histórico General'} (${filtered.length} facturas)
                </td>
                <td class="p-3 text-right text-slate-700">${totalFilteredKg > 0 ? `${formatNumber(totalFilteredKg, 1)} kg equiv.` : '-'}</td>
                <td class="p-3 text-right text-sky-900 text-sm font-black">${formatCurrency(totalFilteredAmount)}</td>
                <td></td>
              </tr>
            </tfoot>
          ` : ''}
        </table>
      </div>
    </div>
  `;
}

// ----------------------------------------------------
// MULTI-PRODUCT PURCHASES MANAGEMENT FUNCTIONS
// ----------------------------------------------------

function buildPurchaseInventoryOptions(selectedValue = '') {
  const inventory = (appData.inventory && appData.inventory.length > 0)
    ? appData.inventory
    : ((typeof DEFAULT_DATA !== 'undefined' && DEFAULT_DATA.inventory) ? DEFAULT_DATA.inventory : []);

  let html = `<option value="">-- Seleccionar Insumo del Catálogo * --</option>`;

  const feeds = inventory.filter(i => isAlimentoCategory(i.category));
  const meds = inventory.filter(i => isMedicamentoCategory(i.category));
  const alevinos = inventory.filter(i => isAlevinoCategory(i.category) || (!isAlimentoCategory(i.category) && !isMedicamentoCategory(i.category) && String(i.name || '').toLowerCase().includes('alevin')));
  const others = inventory.filter(i => !isAlimentoCategory(i.category) && !isMedicamentoCategory(i.category) && !isAlevinoCategory(i.category) && !String(i.name || '').toLowerCase().includes('alevin'));

  if (feeds.length > 0) {
    html += `<optgroup label="🌾 Alimentos Concentrados">`;
    html += feeds.map(i => {
      const detail = i.presentation || (i.proteinPct ? `${i.proteinPct}% PB` : '') || '';
      const label = `${i.name}${detail ? ' (' + detail + ')' : ''}`;
      const isSel = (selectedValue && selectedValue.trim().toLowerCase() === i.name.trim().toLowerCase()) ? 'selected' : '';
      return `<option value="${escapeHtml(i.name)}" data-id="${escapeHtml(i.id)}" data-category="Alimento Concentrado" data-unit="${escapeHtml(i.unit || 'kg')}" data-cost="${i.costPerKg || i.costPerUnit || 0}" ${isSel}>${escapeHtml(label)}</option>`;
    }).join('');
    html += `</optgroup>`;
  }

  if (meds.length > 0) {
    html += `<optgroup label="💊 Medicamentos y Sanidad">`;
    html += meds.map(i => {
      const detail = i.presentation || (i.activeIngredient ? i.activeIngredient : '') || '';
      const label = `${i.name}${detail ? ' (' + detail + ')' : ''}`;
      const isSel = (selectedValue && selectedValue.trim().toLowerCase() === i.name.trim().toLowerCase()) ? 'selected' : '';
      return `<option value="${escapeHtml(i.name)}" data-id="${escapeHtml(i.id)}" data-category="Medicamentos y Químicos" data-unit="${escapeHtml(i.unit || 'kg')}" data-cost="${i.costPerUnit || i.costPerKg || 0}" ${isSel}>${escapeHtml(label)}</option>`;
    }).join('');
    html += `</optgroup>`;
  }

  if (alevinos.length > 0) {
    html += `<optgroup label="🐟 Alevinos y Genética">`;
    html += alevinos.map(i => {
      const detail = i.presentation || '';
      const label = `${i.name}${detail ? ' (' + detail + ')' : ''}`;
      const isSel = (selectedValue && selectedValue.trim().toLowerCase() === i.name.trim().toLowerCase()) ? 'selected' : '';
      return `<option value="${escapeHtml(i.name)}" data-id="${escapeHtml(i.id)}" data-category="Alevinos y Genética" data-unit="${escapeHtml(i.unit || 'unidades')}" data-cost="${i.costPerUnit || i.costPerKg || 0}" ${isSel}>${escapeHtml(label)}</option>`;
    }).join('');
    html += `</optgroup>`;
  }

  if (others.length > 0) {
    html += `<optgroup label="📦 Otros Insumos y Equipos">`;
    html += others.map(i => {
      const detail = i.presentation || '';
      const label = `${i.name}${detail ? ' (' + detail + ')' : ''}`;
      const isSel = (selectedValue && selectedValue.trim().toLowerCase() === i.name.trim().toLowerCase()) ? 'selected' : '';
      const catVal = i.category || 'Insumos Varios';
      return `<option value="${escapeHtml(i.name)}" data-id="${escapeHtml(i.id)}" data-category="${escapeHtml(catVal)}" data-unit="${escapeHtml(i.unit || 'unid')}" data-cost="${i.costPerUnit || 0}" ${isSel}>${escapeHtml(label)}</option>`;
    }).join('');
    html += `</optgroup>`;
  }

  const isCustom = selectedValue && !inventory.some(i => i.name.trim().toLowerCase() === selectedValue.trim().toLowerCase());
  html += `<option value="__custom__" ${isCustom ? 'selected' : ''}>+ Escribir otro producto / insumo...</option>`;

  return html;
}

function createPurchaseItemRowHtml(rowId, rowNum = 1, itemData = null) {
  const desc = itemData ? (itemData.description || '') : '';
  const cat = itemData ? (itemData.category || 'Alimento Concentrado') : 'Alimento Concentrado';
  const qty = itemData ? (parseFloat(itemData.quantity) || 1) : 1;
  const unit = itemData ? (itemData.unit || 'kg') : 'kg';
  const price = itemData ? (parseFloat(itemData.unitPrice) || 0) : 0;
  const subtotal = Math.round(qty * price);

  const inventory = (appData.inventory && appData.inventory.length > 0)
    ? appData.inventory
    : ((typeof DEFAULT_DATA !== 'undefined' && DEFAULT_DATA.inventory) ? DEFAULT_DATA.inventory : []);

  const matchedInv = inventory.find(i => i.name.trim().toLowerCase() === desc.trim().toLowerCase());
  const isCustom = desc && !matchedInv;
  const optionsHtml = buildPurchaseInventoryOptions(desc);

  return `
    <div class="purchase-item-row bg-slate-50/90 p-3 sm:p-3.5 rounded-2xl border border-slate-200/90 shadow-2xs space-y-2.5 transition" data-row-id="${rowId}">
      <div class="flex items-center justify-between pb-1 border-b border-slate-200/60">
        <div class="flex items-center gap-2">
          <span class="pur-row-number-badge w-5 h-5 rounded-full bg-slate-200 text-slate-700 font-black text-[10px] flex items-center justify-center">${rowNum}</span>
          <span class="font-bold text-slate-700 text-xs pur-row-title">Producto #${rowNum}</span>
        </div>
        <button type="button" onclick="removePurchaseItemRow(this)" class="px-2 py-1 rounded-lg text-slate-400 hover:text-rose-600 hover:bg-rose-50 transition cursor-pointer flex items-center gap-1 text-[11px] font-semibold" title="Quitar este producto de la factura">
          <i class="fa-solid fa-trash-can text-xs"></i> <span>Quitar</span>
        </button>
      </div>

      <div class="grid grid-cols-1 sm:grid-cols-12 gap-2.5 items-start">
        <div class="sm:col-span-4">
          <label class="block font-semibold text-slate-600 text-[11px] mb-1">Insumo del Catálogo / Nombre *</label>
          <div class="relative">
            <input type="text" class="pur-item-search w-full p-2 pl-7.5 bg-white border border-slate-200 rounded-xl text-xs font-bold text-slate-800 focus:border-sky-500 focus:ring-1 focus:ring-sky-500 focus:outline-hidden" list="purchase-inventory-datalist" placeholder="Escribe para buscar o ingresar insumo..." value="${escapeHtml(desc)}" oninput="onPurchaseRowSearchInput(this)" onchange="onPurchaseRowSearchInput(this)" autocomplete="off" required>
            <i class="fa-solid fa-magnifying-glass absolute left-2.5 top-1/2 -translate-y-1/2 text-slate-400 text-[11px] pointer-events-none"></i>
          </div>
          <input type="hidden" class="pur-item-desc" value="${escapeHtml(desc)}">
          <input type="hidden" class="pur-item-id" value="${escapeHtml(matchedInv ? matchedInv.id : (itemData && itemData.itemId ? itemData.itemId : ''))}">
        </div>

        <div class="sm:col-span-2">
          <label class="block font-semibold text-slate-600 text-[11px] mb-1">Categoría *</label>
          <select class="pur-item-cat w-full p-2 bg-white border border-slate-200 rounded-xl text-xs font-semibold text-slate-800">
            <option value="Alimento Concentrado" ${cat === 'Alimento Concentrado' ? 'selected' : ''}>Alimento</option>
            <option value="Medicamentos y Químicos" ${cat === 'Medicamentos y Químicos' ? 'selected' : ''}>Medicamentos</option>
            <option value="Alevinos y Genética" ${cat === 'Alevinos y Genética' ? 'selected' : ''}>Alevinos</option>
            <option value="Equipos y Aireación" ${cat === 'Equipos y Aireación' ? 'selected' : ''}>Equipos</option>
            <option value="Mantenimiento y Obra" ${cat === 'Mantenimiento y Obra' ? 'selected' : ''}>Mantenimiento</option>
            <option value="Insumos Varios" ${cat === 'Insumos Varios' ? 'selected' : ''}>Insumos Varios</option>
          </select>
        </div>

        <div class="sm:col-span-2">
          <label class="block font-semibold text-slate-600 text-[11px] mb-1">Cantidad *</label>
          <input type="number" step="0.01" min="0.01" class="pur-item-qty w-full p-2 bg-white border border-slate-200 rounded-xl text-xs font-black text-slate-900" placeholder="1" value="${qty}" oninput="onPurchaseRowCalculation(this)" required>
        </div>

        <div class="sm:col-span-1">
          <label class="block font-semibold text-slate-600 text-[11px] mb-1">Unidad *</label>
          <select class="pur-item-unit w-full p-2 bg-white border border-slate-200 rounded-xl text-xs font-semibold text-slate-800">
            <option value="kg" ${unit === 'kg' ? 'selected' : ''}>kg</option>
            <option value="bulto (40kg)" ${unit === 'bulto (40kg)' ? 'selected' : ''}>bulto</option>
            <option value="litros" ${unit === 'litros' ? 'selected' : ''}>L</option>
            <option value="unidades" ${unit === 'unidades' ? 'selected' : ''}>unid</option>
            <option value="dosis" ${unit === 'dosis' ? 'selected' : ''}>dosis</option>
            <option value="gramos" ${unit === 'gramos' ? 'selected' : ''}>g</option>
            <option value="galones" ${unit === 'galones' ? 'selected' : ''}>gal</option>
          </select>
        </div>

        <div class="sm:col-span-2">
          <label class="block font-semibold text-slate-600 text-[11px] mb-1">Precio Unit. ($) *</label>
          <input type="number" step="1" min="0" class="pur-item-price w-full p-2 bg-white border border-slate-200 rounded-xl text-xs font-black text-slate-900" placeholder="0" value="${price}" oninput="onPurchaseRowCalculation(this)" required>
        </div>

        <div class="sm:col-span-1 text-right">
          <label class="block font-semibold text-slate-400 text-[10px] mb-1">Subtotal</label>
          <div class="pur-item-subtotal-display font-black text-xs text-sky-800 py-2 truncate">${formatCurrency(subtotal)}</div>
          <input type="hidden" class="pur-item-subtotal" value="${subtotal}">
        </div>
      </div>
    </div>
  `;
}

function addPurchaseItemRow(containerId, itemData = null) {
  const container = document.getElementById(containerId);
  if (!container) return;

  const rowId = 'pur-row-' + Date.now() + '-' + Math.floor(Math.random() * 1000);
  const currentCount = container.querySelectorAll('.purchase-item-row').length;
  const rowHtml = createPurchaseItemRowHtml(rowId, currentCount + 1, itemData);

  const tempDiv = document.createElement('div');
  tempDiv.innerHTML = rowHtml.trim();
  const rowEl = tempDiv.firstChild;
  container.appendChild(rowEl);

  reindexPurchaseRows(containerId);
  calculatePurchaseTotal(containerId);
}

function removePurchaseItemRow(btn) {
  if (!btn) return;
  const row = btn.closest('.purchase-item-row');
  if (!row) return;
  const container = row.parentElement;
  if (!container) return;

  const totalRows = container.querySelectorAll('.purchase-item-row').length;
  if (totalRows <= 1) {
    showNotification('La factura debe tener al menos un producto registrado.', 'warning');
    return;
  }

  row.remove();
  const containerId = container.id;
  reindexPurchaseRows(containerId);
  calculatePurchaseTotal(containerId);
}

function reindexPurchaseRows(containerId) {
  const container = document.getElementById(containerId);
  if (!container) return;

  const rows = container.querySelectorAll('.purchase-item-row');
  rows.forEach((row, idx) => {
    const num = idx + 1;
    const badge = row.querySelector('.pur-row-number-badge');
    const title = row.querySelector('.pur-row-title');
    if (badge) badge.innerText = num;
    if (title) title.innerText = `Producto #${num}`;
  });

  const isEdit = containerId.startsWith('edit');
  const countBadgeId = isEdit ? 'edit-pur-items-count-badge' : 'pur-items-count-badge';
  const summaryTextId = isEdit ? 'edit-pur-summary-items-text' : 'pur-summary-items-text';

  const countBadge = document.getElementById(countBadgeId);
  const summaryText = document.getElementById(summaryTextId);
  const count = rows.length;
  const plural = count === 1 ? '1 producto' : `${count} productos`;

  if (countBadge) countBadge.innerText = plural;
  if (summaryText) summaryText.innerText = `${plural} registrado${count === 1 ? '' : 's'}`;
}

function onPurchaseRowSearchInput(inputEl) {
  if (!inputEl) return;
  const row = inputEl.closest('.purchase-item-row');
  if (!row) return;

  const descVal = inputEl.value.trim();
  const descHidden = row.querySelector('.pur-item-desc');
  const idHidden = row.querySelector('.pur-item-id');
  const catSelect = row.querySelector('.pur-item-cat');
  const unitSelect = row.querySelector('.pur-item-unit');
  const priceInput = row.querySelector('.pur-item-price');

  if (descHidden) descHidden.value = descVal;

  const inventory = (appData.inventory && appData.inventory.length > 0)
    ? appData.inventory
    : ((typeof DEFAULT_DATA !== 'undefined' && DEFAULT_DATA.inventory) ? DEFAULT_DATA.inventory : []);

  const matched = inventory.find(i => (i.name || '').trim().toLowerCase() === descVal.toLowerCase());
  if (matched) {
    if (idHidden) idHidden.value = matched.id || '';
    const cat = matched.category || '';
    const unit = matched.unit || '';
    const cost = isAlimentoCategory(cat) ? (matched.costPerKg || matched.costPerUnit || 0) : (matched.costPerUnit || matched.costPerKg || 0);

    if (catSelect && cat) {
      const hasOpt = Array.from(catSelect.options).some(o => o.value.toLowerCase() === cat.toLowerCase());
      if (hasOpt) {
        catSelect.value = cat;
      } else {
        catSelect.value = isAlimentoCategory(cat) ? 'Alimento Concentrado' : isMedicamentoCategory(cat) ? 'Medicamentos y Químicos' : isAlevinoCategory(cat) ? 'Alevinos y Genética' : 'Insumos Varios';
      }
    }
    if (unitSelect && unit) {
      const optExists = Array.from(unitSelect.options).some(o => o.value.toLowerCase() === unit.toLowerCase());
      if (optExists) unitSelect.value = unit;
      else unitSelect.value = isAlimentoCategory(cat) ? 'kg' : 'unidades';
    }
    if (priceInput && (!priceInput.value || parseFloat(priceInput.value) === 0) && cost > 0) {
      priceInput.value = cost;
    }
  } else {
    if (idHidden) idHidden.value = '';
  }

  onPurchaseRowCalculation(inputEl);
}

function onPurchaseRowProductChange(selectEl) {
  if (!selectEl) return;
  const row = selectEl.closest('.purchase-item-row');
  if (!row) return;

  const customBox = row.querySelector('.pur-item-custom-box');
  const customInput = row.querySelector('.pur-item-desc-custom');
  const descHidden = row.querySelector('.pur-item-desc');
  const idHidden = row.querySelector('.pur-item-id');
  const catSelect = row.querySelector('.pur-item-cat');
  const unitSelect = row.querySelector('.pur-item-unit');
  const priceInput = row.querySelector('.pur-item-price');

  if (selectEl.value === '__custom__') {
    if (customBox) customBox.classList.remove('hidden');
    if (customInput) {
      customInput.focus();
      descHidden.value = customInput.value.trim();
    }
    if (idHidden) idHidden.value = '';
  } else {
    if (customBox) customBox.classList.add('hidden');
    descHidden.value = selectEl.value;

    const selectedOpt = selectEl.options[selectEl.selectedIndex];
    if (selectedOpt && selectEl.value) {
      if (idHidden) idHidden.value = selectedOpt.getAttribute('data-id') || '';
      const cat = selectedOpt.getAttribute('data-category');
      const unit = selectedOpt.getAttribute('data-unit');
      const cost = parseFloat(selectedOpt.getAttribute('data-cost')) || 0;

      if (catSelect && cat) {
        const hasOpt = Array.from(catSelect.options).some(o => o.value === cat);
        if (hasOpt) {
          catSelect.value = cat;
        } else {
          catSelect.value = isAlimentoCategory(cat) ? 'Alimento Concentrado' : isMedicamentoCategory(cat) ? 'Medicamentos y Químicos' : isAlevinoCategory(cat) ? 'Alevinos y Genética' : 'Insumos Varios';
        }
      }
      if (unitSelect && unit) {
        const optExists = Array.from(unitSelect.options).some(o => o.value === unit);
        if (optExists) unitSelect.value = unit;
        else unitSelect.value = isAlimentoCategory(cat) ? 'kg' : 'unidades';
      }
      if (priceInput && (!priceInput.value || parseFloat(priceInput.value) === 0)) {
        priceInput.value = cost;
      }
    }
  }

  onPurchaseRowCalculation(selectEl);
}

function onPurchaseRowCalculation(el) {
  if (!el) return;
  const row = el.closest('.purchase-item-row');
  if (!row) return;

  const searchInput = row.querySelector('.pur-item-search');
  const selectEl = row.querySelector('.pur-item-select');
  const customInput = row.querySelector('.pur-item-desc-custom');
  const descHidden = row.querySelector('.pur-item-desc');

  if (searchInput) {
    if (descHidden) descHidden.value = searchInput.value.trim();
  } else if (selectEl && selectEl.value === '__custom__' && customInput) {
    if (descHidden) descHidden.value = customInput.value.trim();
  } else if (selectEl) {
    if (descHidden) descHidden.value = selectEl.value;
  }

  const qty = parseFloat(row.querySelector('.pur-item-qty').value) || 0;
  const price = parseFloat(row.querySelector('.pur-item-price').value) || 0;
  const subtotal = Math.round(qty * price);

  const subtotalDisplay = row.querySelector('.pur-item-subtotal-display');
  const subtotalHidden = row.querySelector('.pur-item-subtotal');

  if (subtotalDisplay) subtotalDisplay.innerText = formatCurrency(subtotal);
  if (subtotalHidden) subtotalHidden.value = subtotal;

  const container = row.parentElement;
  if (container) {
    calculatePurchaseTotal(container.id);
  }
}

function calculatePurchaseTotal(containerId) {
  const container = document.getElementById(containerId);
  if (!container) return;

  const rows = container.querySelectorAll('.purchase-item-row');
  let total = 0;
  rows.forEach(r => {
    const sub = parseFloat(r.querySelector('.pur-item-subtotal').value) || 0;
    total += sub;
  });

  const isEdit = containerId.startsWith('edit');
  const displayId = isEdit ? 'edit-pur-total-display' : 'pur-total-display';
  const displayEl = document.getElementById(displayId);
  if (displayEl) {
    displayEl.innerText = formatCurrency(total);
  }
  return total;
}

function submitNewPurchase(event) {
  if (event) event.preventDefault();

  if (!isMasterUser()) {
    showNotification('Acceso de Solo Lectura: Tu cuenta es de perfil Lite. No tienes permisos para registrar compras.', 'warning');
    return;
  }

  const dateVal = document.getElementById('pur-date') ? document.getElementById('pur-date').value : '';
  const supplierSelect = document.getElementById('pur-supplier');
  const customSupplierBox = document.getElementById('pur-custom-supplier-box');
  const customSupplierInput = document.getElementById('pur-custom-supplier');

  let supplierVal = '';
  if (supplierSelect) {
    if (supplierSelect.tagName === 'INPUT') {
      supplierVal = supplierSelect.value.trim();
    } else if (supplierSelect.value === '__custom__' && customSupplierInput) {
      supplierVal = customSupplierInput.value.trim();
    } else {
      supplierVal = supplierSelect.value.trim();
    }
  }

  const invoiceVal = (document.getElementById('pur-invoice') ? document.getElementById('pur-invoice').value.trim() : '') || ('FAC-' + Date.now().toString().slice(-4));

  if (!dateVal) {
    showNotification('Por favor ingrese la fecha de emisión de la compra.', 'warning');
    return;
  }
  if (!supplierVal) {
    showNotification('Por favor seleccione o ingrese el proveedor de la factura.', 'warning');
    return;
  }

  const container = document.getElementById('pur-items-container');
  if (!container) return;

  const rows = container.querySelectorAll('.purchase-item-row');
  const items = [];

  rows.forEach(row => {
    const searchInput = row.querySelector('.pur-item-search');
    const descHidden = row.querySelector('.pur-item-desc');
    const selectEl = row.querySelector('.pur-item-select');
    const customInput = row.querySelector('.pur-item-desc-custom');
    const idHidden = row.querySelector('.pur-item-id');

    let desc = '';
    if (searchInput && searchInput.value) {
      desc = searchInput.value.trim();
    } else if (selectEl && selectEl.value === '__custom__' && customInput) {
      desc = customInput.value.trim();
    } else if (descHidden && descHidden.value) {
      desc = descHidden.value.trim();
    } else if (selectEl) {
      desc = selectEl.value.trim();
    }

    const selectedOpt = (selectEl && selectEl.selectedIndex >= 0) ? selectEl.options[selectEl.selectedIndex] : null;
    const itemId = (idHidden && idHidden.value) || (selectedOpt ? selectedOpt.getAttribute('data-id') : null);

    const cat = row.querySelector('.pur-item-cat').value;
    const qty = parseFloat(row.querySelector('.pur-item-qty').value) || 0;
    const unit = row.querySelector('.pur-item-unit').value;
    const unitPrice = parseFloat(row.querySelector('.pur-item-price').value) || 0;
    const subtotal = Math.round(qty * unitPrice);

    if (desc && qty > 0) {
      items.push({
        itemId: itemId || undefined,
        description: desc,
        category: cat,
        quantity: qty,
        unit: unit,
        unitPrice: unitPrice,
        totalAmount: subtotal
      });
    }
  });

  if (items.length === 0) {
    showNotification('Por favor agregue al menos un producto con descripción y cantidad válida.', 'warning');
    return;
  }

  const totalAmount = items.reduce((sum, it) => sum + it.totalAmount, 0);
  const totalQty = items.reduce((sum, it) => sum + it.quantity, 0);
  const summaryDesc = items.length === 1
    ? items[0].description
    : `${items[0].description} (+${items.length - 1} producto${items.length - 1 > 1 ? 's' : ''} más)`;

  const newPurchase = {
    id: 'PUR-' + Date.now().toString().slice(-6),
    date: dateVal,
    supplier: supplierVal,
    invoice: invoiceVal,
    category: items[0].category || 'Alimento Concentrado',
    description: summaryDesc,
    quantity: totalQty,
    unit: items[0].unit,
    unitPrice: items.length === 1 ? items[0].unitPrice : Math.round(totalAmount / (totalQty || 1)),
    totalAmount: totalAmount,
    items: items,
    inventorySynced: true,
    createdAt: new Date().toISOString()
  };

  // Recarga automática y sincronización de stock en inventario y kárdex para TODOS los productos
  items.forEach(it => {
    let invItem = null;
    if (it.itemId) {
      invItem = (appData.inventory || []).find(inv => inv.id === it.itemId);
    }
    if (!invItem && it.description) {
      invItem = (appData.inventory || []).find(inv =>
        inv.name && inv.name.toLowerCase().trim() === it.description.toLowerCase().trim()
      );
    }

    const isFeed = isAlimentoCategory(it.category) || (invItem && isAlimentoCategory(invItem.category));
    const isMed = isMedicamentoCategory(it.category) || (invItem && isMedicamentoCategory(invItem.category));
    const isAlevino = isAlevinoCategory(it.category) || (invItem && isAlevinoCategory(invItem.category));

    let qtyToAdd = it.quantity;
    let costPerUnitVal = it.unitPrice;

    if (isFeed && it.unit && it.unit.toLowerCase().includes('bulto')) {
      const bultoWeight = (invItem && invItem.unitWeightKg) ? invItem.unitWeightKg : 40;
      qtyToAdd = it.quantity * bultoWeight;
      if (it.unitPrice > 0) {
        costPerUnitVal = Math.round(it.unitPrice / bultoWeight);
      }
    }

    if (invItem) {
      if (isAlevino) {
        const b = (invItem.brand || '').toLowerCase().trim();
        if (!invItem.brand || b.includes('italcol') || b.includes('solla') || b.includes('finca') || b === 'general') {
          invItem.brand = invItem.hatchery || invItem.origin || ((supplierVal && !supplierVal.toLowerCase().includes('italcol')) ? supplierVal : 'Criadero Certificado');
        }
        if (invItem.supplier && invItem.supplier.toLowerCase().includes('italcol')) {
          invItem.supplier = 'Criadero Certificado';
        }
      }
      if (isFeed) {
        invItem.currentStockKg = (invItem.currentStockKg || 0) + qtyToAdd;
        invItem.currentStock = invItem.currentStockKg;
        if (costPerUnitVal > 0) {
          invItem.costPerKg = costPerUnitVal;
          invItem.costPerUnit = costPerUnitVal;
        }
      } else {
        invItem.currentStock = (invItem.currentStock || 0) + qtyToAdd;
        invItem.currentStockKg = invItem.currentStock;
        if (costPerUnitVal > 0) {
          invItem.costPerUnit = costPerUnitVal;
          invItem.costPerKg = costPerUnitVal;
        }
      }
      invItem.lastPurchaseDate = dateVal;
    } else {
      // Auto-crear producto en bodega para que el usuario no pierda el stock
      const newId = `INV-${isFeed ? 'ALI' : isMed ? 'MED' : isAlevino ? 'ALE' : 'INS'}-${Date.now().toString().slice(-4)}-${Math.floor(Math.random() * 100)}`;
      const alevinoSupplier = (supplierVal && !supplierVal.toLowerCase().includes('italcol') && !supplierVal.toLowerCase().includes('solla') && !supplierVal.toLowerCase().includes('finca')) ? supplierVal : 'Criadero Certificado';
      invItem = {
        id: newId,
        category: it.category || (isFeed ? 'Alimento Concentrado' : isMed ? 'Medicamentos y Químicos' : isAlevino ? 'Alevinos y Genética' : 'Insumos Varios'),
        name: it.description,
        brand: isAlevino ? alevinoSupplier : (supplierVal || 'General'),
        type: isFeed ? 'Engorde' : isMed ? 'Sanitario' : (isAlevino ? 'Siembra' : 'General'),
        proteinPct: isFeed ? 32 : 0,
        presentation: (it.unit && it.unit.toLowerCase().includes('bulto')) ? 'Bulto 40 kg' : (it.unit || 'kg'),
        unit: isFeed ? 'kg' : (it.unit || (isAlevino ? 'unidades' : 'kg')),
        currentStock: qtyToAdd,
        currentStockKg: isFeed ? qtyToAdd : 0,
        minStock: isFeed ? 400 : (isAlevino ? 500 : 10),
        minStockKg: isFeed ? 400 : 0,
        costPerUnit: costPerUnitVal,
        costPerKg: isFeed ? costPerUnitVal : 0,
        supplier: isAlevino ? alevinoSupplier : supplierVal,
        hatchery: isAlevino ? alevinoSupplier : '',
        location: 'Bodega Principal',
        status: 'activo',
        lastPurchaseDate: dateVal,
        notes: `Registrado automáticamente desde Factura ${invoiceVal}`
      };
      if (!appData.inventory) appData.inventory = [];
      appData.inventory.push(invItem);
    }

    // Registrar en Kárdex
    if (!appData.inventoryMovements) appData.inventoryMovements = [];
    appData.inventoryMovements.push({
      id: `MOV-${Date.now().toString().slice(-6)}-${Math.floor(Math.random() * 1000)}`,
      date: dateVal,
      type: 'entrada',
      category: invItem.category || it.category,
      itemId: invItem.id,
      itemName: invItem.name,
      quantity: qtyToAdd,
      unit: isFeed ? 'kg' : (invItem.unit || it.unit || 'kg'),
      unitCost: costPerUnitVal,
      totalCost: it.totalAmount,
      reference: `Factura ${invoiceVal}`,
      destination: invItem.location || 'Bodega Principal',
      balanceAfter: isFeed ? invItem.currentStockKg : invItem.currentStock,
      notes: `Compra a ${supplierVal}: ${it.quantity} ${it.unit} (${invItem.name})`
    });
  });

  if (!appData.purchases) appData.purchases = [];
  appData.purchases.push(newPurchase);

  PiscicolaStorage.save(appData);
  closeModal('modal-new-purchase');

  // Reset modal form
  const formPurchase = document.getElementById('form-add-purchase');
  if (formPurchase) formPurchase.reset();
  container.innerHTML = '';

  renderFinanzas();
  populateSupplierDropdowns();
  populateInventoryDropdowns();

  showNotification(`¡Factura ${newPurchase.invoice} guardada exitosamente con ${items.length} producto${items.length > 1 ? 's' : ''}!`, 'success');
}

function openViewPurchaseModal(purchaseId) {
  const purchase = (appData.purchases || []).find(p => p.id === purchaseId);
  if (!purchase) {
    showNotification('No se encontró la factura de compra solicitada.', 'error');
    return;
  }

  const items = (purchase.items && purchase.items.length > 0) ? purchase.items : [{
    description: purchase.description || 'Insumo',
    category: purchase.category || 'Alimento Concentrado',
    quantity: purchase.quantity || 1,
    unit: purchase.unit || 'kg',
    unitPrice: purchase.unitPrice || 0,
    totalAmount: purchase.totalAmount || 0
  }];

  const badgeEl = document.getElementById('view-pur-badge');
  const invoiceEl = document.getElementById('view-pur-invoice');
  const dateEl = document.getElementById('view-pur-date');
  const supplierEl = document.getElementById('view-pur-supplier');
  const tableBody = document.getElementById('view-pur-items-table');
  const summaryEl = document.getElementById('view-pur-items-summary');
  const totalEl = document.getElementById('view-pur-total');
  const editBtn = document.getElementById('btn-view-pur-edit');

  if (badgeEl) badgeEl.innerText = purchase.invoice || purchase.id;
  if (invoiceEl) invoiceEl.innerText = purchase.invoice || purchase.id;
  if (dateEl) dateEl.innerText = formatDate(purchase.date);
  if (supplierEl) supplierEl.innerText = purchase.supplier || 'N/A';

  if (tableBody) {
    tableBody.innerHTML = items.map((it, idx) => `
      <tr class="hover:bg-slate-50 transition">
        <td class="p-3 font-bold text-slate-400">${idx + 1}</td>
        <td class="p-3">
          <div class="font-extrabold text-slate-800 text-xs">${escapeHtml(it.description)}</div>
          <span class="inline-block mt-0.5 px-2 py-0.5 rounded-full text-[9px] font-bold bg-slate-100 text-slate-600">${escapeHtml(it.category || 'Insumo')}</span>
        </td>
        <td class="p-3 text-right font-black text-slate-900">${formatNumber(it.quantity, 1)}</td>
        <td class="p-3 font-semibold text-slate-600">${escapeHtml(it.unit || 'kg')}</td>
        <td class="p-3 text-right font-semibold text-slate-700">${formatCurrency(it.unitPrice)}</td>
        <td class="p-3 text-right font-black text-sky-900">${formatCurrency(it.totalAmount)}</td>
      </tr>
    `).join('');
  }

  const totalCalculated = items.reduce((sum, it) => sum + (parseFloat(it.totalAmount) || 0), 0);
  const itemsText = items.length === 1 ? '1 producto registrado' : `${items.length} productos registrados`;

  if (summaryEl) summaryEl.innerText = itemsText;
  if (totalEl) totalEl.innerText = formatCurrency(purchase.totalAmount || totalCalculated);

  if (editBtn) {
    if (isMasterUser()) {
      editBtn.classList.remove('hidden');
      editBtn.onclick = () => {
        closeModal('modal-view-purchase');
        openEditPurchaseModal(purchase.id);
      };
    } else {
      editBtn.classList.add('hidden');
    }
  }

  openModal('modal-view-purchase');
}

function openEditPurchaseModal(purchaseId) {
  if (!isMasterUser()) {
    showNotification('Acceso de Solo Lectura: Tu cuenta es de perfil Lite. No tienes permisos para editar compras.', 'warning');
    return;
  }

  const purchase = (appData.purchases || []).find(p => p.id === purchaseId);
  if (!purchase) {
    showNotification('No se encontró la compra a editar.', 'error');
    return;
  }

  document.getElementById('edit-pur-id').value = purchase.id;
  document.getElementById('edit-pur-date').value = purchase.date || '';
  document.getElementById('edit-pur-invoice').value = purchase.invoice || '';
  document.getElementById('edit-pur-badge').innerText = purchase.invoice || purchase.id;

  // Poblar dropdown de proveedores si existe
  populateSupplierDropdowns();
  const suppSelect = document.getElementById('edit-pur-supplier');
  const customBox = document.getElementById('edit-pur-custom-supplier-box');
  const customInput = document.getElementById('edit-pur-custom-supplier');

  if (suppSelect) {
    if (suppSelect.tagName === 'INPUT') {
      suppSelect.value = purchase.supplier || '';
    } else {
      const hasOpt = Array.from(suppSelect.options).some(o => o.value === purchase.supplier);
      if (hasOpt) {
        suppSelect.value = purchase.supplier;
        if (customBox) customBox.classList.add('hidden');
      } else {
        suppSelect.value = '__custom__';
        if (customBox) customBox.classList.remove('hidden');
        if (customInput) customInput.value = purchase.supplier || '';
      }
    }
  }

  // Poblar filas de productos
  const container = document.getElementById('edit-pur-items-container');
  if (container) {
    container.innerHTML = '';
    const items = (purchase.items && purchase.items.length > 0) ? purchase.items : [{
      description: purchase.description || 'Insumo',
      category: purchase.category || 'Alimento Concentrado',
      quantity: purchase.quantity || 1,
      unit: purchase.unit || 'kg',
      unitPrice: purchase.unitPrice || 0,
      totalAmount: purchase.totalAmount || 0
    }];

    items.forEach(it => {
      addPurchaseItemRow('edit-pur-items-container', it);
    });

    reindexPurchaseRows('edit-pur-items-container');
    calculatePurchaseTotal('edit-pur-items-container');
  }

  openModal('modal-edit-purchase');
}

function submitEditPurchase(event) {
  if (event) event.preventDefault();

  if (!isMasterUser()) {
    showNotification('Acceso de Solo Lectura: Tu cuenta es de perfil Lite. No tienes permisos para editar compras.', 'warning');
    return;
  }

  const purchaseId = document.getElementById('edit-pur-id').value;
  const purIndex = (appData.purchases || []).findIndex(p => p.id === purchaseId);
  if (purIndex === -1) {
    showNotification('No se encontró el registro original de la compra.', 'error');
    return;
  }

  const dateVal = document.getElementById('edit-pur-date').value;
  const supplierSelect = document.getElementById('edit-pur-supplier');
  const customSupplierInput = document.getElementById('edit-pur-custom-supplier');

  let supplierVal = '';
  if (supplierSelect) {
    if (supplierSelect.tagName === 'INPUT') {
      supplierVal = supplierSelect.value.trim();
    } else if (supplierSelect.value === '__custom__' && customSupplierInput) {
      supplierVal = customSupplierInput.value.trim();
    } else {
      supplierVal = supplierSelect.value.trim();
    }
  }

  const invoiceVal = (document.getElementById('edit-pur-invoice').value.trim()) || ('FAC-' + Date.now().toString().slice(-4));

  if (!dateVal) {
    showNotification('Por favor ingrese la fecha de emisión de la compra.', 'warning');
    return;
  }
  if (!supplierVal) {
    showNotification('Por favor seleccione o ingrese el proveedor de la factura.', 'warning');
    return;
  }

  const container = document.getElementById('edit-pur-items-container');
  if (!container) return;

  const rows = container.querySelectorAll('.purchase-item-row');
  const items = [];

  rows.forEach(row => {
    const searchInput = row.querySelector('.pur-item-search');
    const descHidden = row.querySelector('.pur-item-desc');
    const selectEl = row.querySelector('.pur-item-select');
    const customInput = row.querySelector('.pur-item-desc-custom');

    let desc = '';
    if (searchInput && searchInput.value) {
      desc = searchInput.value.trim();
    } else if (selectEl && selectEl.value === '__custom__' && customInput) {
      desc = customInput.value.trim();
    } else if (descHidden && descHidden.value) {
      desc = descHidden.value.trim();
    } else if (selectEl) {
      desc = selectEl.value.trim();
    }

    const selectedOpt = (selectEl && selectEl.selectedIndex >= 0) ? selectEl.options[selectEl.selectedIndex] : null;
    const itemId = (row.querySelector('.pur-item-id') ? row.querySelector('.pur-item-id').value : '') || (selectedOpt ? selectedOpt.getAttribute('data-id') : null);

    const cat = row.querySelector('.pur-item-cat').value;
    const qty = parseFloat(row.querySelector('.pur-item-qty').value) || 0;
    const unit = row.querySelector('.pur-item-unit').value;
    const unitPrice = parseFloat(row.querySelector('.pur-item-price').value) || 0;
    const subtotal = Math.round(qty * unitPrice);

    if (desc && qty > 0) {
      items.push({
        itemId: itemId || undefined,
        description: desc,
        category: cat,
        quantity: qty,
        unit: unit,
        unitPrice: unitPrice,
        totalAmount: subtotal
      });
    }
  });

  if (items.length === 0) {
    showNotification('Por favor agregue al menos un producto con descripción y cantidad válida.', 'warning');
    return;
  }

  const totalAmount = items.reduce((sum, it) => sum + it.totalAmount, 0);
  const totalQty = items.reduce((sum, it) => sum + it.quantity, 0);
  const summaryDesc = items.length === 1
    ? items[0].description
    : `${items[0].description} (+${items.length - 1} producto${items.length - 1 > 1 ? 's' : ''} más)`;

  const originalPurchase = appData.purchases[purIndex];

  appData.purchases[purIndex] = {
    ...originalPurchase,
    date: dateVal,
    supplier: supplierVal,
    invoice: invoiceVal,
    category: items[0].category || 'Alimento Concentrado',
    description: summaryDesc,
    quantity: totalQty,
    unit: items[0].unit,
    unitPrice: items.length === 1 ? items[0].unitPrice : Math.round(totalAmount / (totalQty || 1)),
    totalAmount: totalAmount,
    items: items,
    inventorySynced: false,
    updatedAt: new Date().toISOString()
  };

  PiscicolaStorage.save(appData);
  closeModal('modal-edit-purchase');
  
  // Sincronizar cambios en inventario
  syncInventoryWithPurchases(false);

  renderFinanzas();
  showNotification(`¡Factura ${invoiceVal} actualizada con éxito!`, 'success');
}

function deletePurchase(purchaseId) {
  if (!isMasterUser()) {
    showNotification('Acceso de Solo Lectura: Tu cuenta es de perfil Lite. No tienes permisos para eliminar compras.', 'warning');
    return;
  }

  const purchase = (appData.purchases || []).find(p => p.id === purchaseId);
  if (!purchase) return;

  const confirmMsg = `¿Está seguro de eliminar la compra ${purchase.invoice || purchase.id} por valor de ${formatCurrency(purchase.totalAmount)}?\nEsta acción no se puede deshacer.`;
  if (!confirm(confirmMsg)) return;

  // Revertir existencias acreditadas
  const invRef = purchase.invoice || purchase.id;
  const items = (purchase.items && purchase.items.length > 0) ? purchase.items : [{
    description: purchase.description,
    quantity: purchase.quantity,
    unit: purchase.unit,
    category: purchase.category
  }];

  items.forEach(it => {
    let invItem = (appData.inventory || []).find(inv =>
      inv.name && inv.name.toLowerCase().trim() === (it.description || '').toLowerCase().trim()
    );
    if (invItem) {
      const isFeed = isAlimentoCategory(invItem.category);
      let qtyKg = it.quantity || 0;
      if (isFeed && it.unit && it.unit.toLowerCase().includes('bulto')) {
        qtyKg = (it.quantity || 0) * (invItem.unitWeightKg || 40);
      }
      if (isFeed) {
        invItem.currentStockKg = Math.max(0, (invItem.currentStockKg || 0) - qtyKg);
        invItem.currentStock = invItem.currentStockKg;
      } else {
        invItem.currentStock = Math.max(0, (invItem.currentStock || 0) - (it.quantity || 0));
        invItem.currentStockKg = invItem.currentStock;
      }
    }
  });

  // Eliminar movimiento correspondiente del Kárdex de forma exacta
  appData.inventoryMovements = (appData.inventoryMovements || []).filter(m => {
    if (m.purchaseId && m.purchaseId === purchaseId) return false;
    if (invRef && (m.reference === `Factura ${invRef}` || m.reference === `Compra Factura ${invRef}` || m.reference === invRef)) return false;
    return true;
  });

  recalculateKardexBalances();
  appData.purchases = (appData.purchases || []).filter(p => p.id !== purchaseId);
  PiscicolaStorage.save(appData);
  renderFinanzas();
  showNotification('Factura de compra eliminada correctamente y stock revertido.', 'info');
}

function renderExpensesTable() {
  const allExpenses = appData.expenses || [];
  const filtered = allExpenses.filter(e => matchesFinanceFilter(e, 'expenses'));
  const grouped = groupRecordsByDate(filtered);
  const totalFilteredAmount = filtered.reduce((sum, e) => sum + (parseFloat(e.amount) || 0), 0);
  const isFiltered = Boolean(financeFilterMonth || financeFilterDate || financeFilterSearch);

  return `
    <div class="space-y-4">
      <!-- Active Filter Pill Indicator if Filtered -->
      ${isFiltered ? `
        <div class="flex flex-col sm:flex-row sm:items-center justify-between bg-amber-50/90 border border-amber-200 px-4 py-2.5 rounded-xl text-xs text-amber-900 gap-2">
          <div class="flex items-center gap-2">
            <span class="w-2 h-2 rounded-full bg-amber-500 animate-pulse"></span>
            <span>Filtro activo: <strong>${financeFilterDate ? `Día ${formatDate(financeFilterDate)}` : (financeFilterMonth ? formatMonthName(financeFilterMonth) : '')}${financeFilterSearch ? ` (Búsqueda: "${escapeHtml(financeFilterSearch)}")` : ''}</strong></span>
          </div>
          <div class="flex items-center gap-3">
            <span class="font-black text-amber-950">${filtered.length} gastos | Total: ${formatCurrency(totalFilteredAmount)}</span>
            <button onclick="resetFinanceFilters()" class="text-amber-700 hover:text-amber-950 font-bold underline cursor-pointer">Ver Todo</button>
          </div>
        </div>
      ` : ''}

      <div class="overflow-x-auto">
        <table class="w-full text-left text-xs">
          <thead class="bg-slate-50 text-slate-500 uppercase text-[10px] font-bold border-b border-slate-100">
            <tr>
              <th class="p-3">Fecha</th>
              <th class="p-3">ID / Recibo</th>
              <th class="p-3">Categoría</th>
              <th class="p-3">Beneficiario</th>
              <th class="p-3">Concepto</th>
              <th class="p-3">Forma de Pago</th>
              <th class="p-3 text-right">Valor Pagado</th>
              <th class="p-3 text-center">Acciones</th>
            </tr>
          </thead>
          <tbody class="divide-y divide-slate-100">
            ${filtered.length === 0 ? `
              <tr>
                <td colspan="8" class="py-12 px-6 text-center">
                  <div class="max-w-xs mx-auto flex flex-col items-center">
                    <div class="w-12 h-12 bg-amber-50 text-amber-600 rounded-2xl flex items-center justify-center text-lg mb-2">
                      <i class="fa-solid fa-receipt"></i>
                    </div>
                    <h4 class="text-xs font-bold text-slate-800">No hay gastos en este periodo</h4>
                    <p class="text-[11px] text-slate-400 mt-0.5">No se encontraron recibos o gastos operativos para el mes o día seleccionado.</p>
                    ${isFiltered ? `
                      <button onclick="resetFinanceFilters()" class="mt-3 px-3 py-1.5 bg-amber-600 hover:bg-amber-500 text-white rounded-xl text-xs font-bold transition shadow-xs cursor-pointer">
                        Restablecer Filtros y Ver Todo
                      </button>
                    ` : ''}
                  </div>
                </td>
              </tr>
            ` : grouped.map(group => `
              <!-- Group Date Header (Día específico con subtotal del día) -->
              <tr class="bg-slate-100/80 border-y border-slate-200">
                <td colspan="8" class="py-2 px-3 text-xs font-bold text-slate-800">
                  <div class="flex items-center justify-between flex-wrap gap-2">
                    <span class="flex items-center gap-1.5 text-amber-950 font-black">
                      <i class="fa-regular fa-calendar-days text-amber-600"></i>
                      <span>${formatFullDateName(group.date)}</span>
                    </span>
                    <span class="text-[11px] font-black text-slate-700 bg-white px-2.5 py-0.5 rounded-full border border-slate-200 shadow-2xs">
                      Subtotal Día: <strong class="text-amber-900">${formatCurrency(group.daySubtotal)}</strong> (${group.items.length} gasto${group.items.length > 1 ? 's' : ''})
                    </span>
                  </div>
                </td>
              </tr>
              ${group.items.map(e => `
                <tr class="hover:bg-slate-50 transition group">
                  <td class="p-3 font-semibold text-slate-700 whitespace-nowrap">${formatDate(e.date)}</td>
                  <td class="p-3 whitespace-nowrap">
                    <button onclick="openViewExpenseModal('${e.id}')" title="Ver comprobante de gasto" class="font-extrabold text-amber-800 hover:text-amber-950 hover:underline flex items-center gap-1.5 cursor-pointer">
                      <i class="fa-solid fa-receipt text-xs text-amber-600"></i>
                      <span>${escapeHtml(e.receiptRef || e.id)}</span>
                    </button>
                  </td>
                  <td class="p-3 whitespace-nowrap">
                    <span class="px-2 py-0.5 rounded bg-amber-50 text-amber-800 font-semibold text-[11px]">${escapeHtml(e.category)}</span>
                  </td>
                  <td class="p-3 font-bold text-slate-800 whitespace-nowrap">
                    <span class="truncate max-w-[150px] inline-block" title="${escapeHtml(e.recipient || '')}">${escapeHtml(e.recipient || 'N/A')}</span>
                  </td>
                  <td class="p-3 text-slate-700">
                    <span class="font-medium text-slate-800">${escapeHtml(e.description || '--')}</span>
                  </td>
                  <td class="p-3 text-slate-600 whitespace-nowrap">${escapeHtml(e.paymentMethod || 'Transferencia Bancaria')}</td>
                  <td class="p-3 font-black text-right text-slate-900 whitespace-nowrap">${formatCurrency(e.amount)}</td>
                  <td class="p-3 text-center whitespace-nowrap">
                    <div class="flex items-center justify-center gap-1.5">
                      <button onclick="openViewExpenseModal('${e.id}')" title="Visualizar Comprobante Completo" class="px-2 py-1 rounded-lg bg-sky-50 hover:bg-sky-100 text-sky-700 flex items-center gap-1 text-[11px] font-bold transition cursor-pointer">
                        <i class="fa-solid fa-eye text-xs"></i> Ver
                      </button>
                      ${isMasterUser() ? `
                        <button onclick="openEditExpenseModal('${e.id}')" title="Editar Gasto Operativo" class="px-2 py-1 rounded-lg bg-amber-50 hover:bg-amber-100 text-amber-700 flex items-center gap-1 text-[11px] font-bold transition cursor-pointer">
                          <i class="fa-solid fa-pen-to-square text-xs"></i> Editar
                        </button>
                        <button onclick="deleteExpense('${e.id}')" title="Eliminar Gasto" class="p-1 rounded-lg text-slate-300 hover:text-rose-600 transition cursor-pointer">
                          <i class="fa-solid fa-trash-can text-xs"></i>
                        </button>
                      ` : ''}
                    </div>
                  </td>
                </tr>
              `).join('')}
            `).join('')}
          </tbody>
          ${filtered.length > 0 ? `
            <tfoot class="bg-slate-50 border-t-2 border-slate-200 text-xs font-black">
              <tr>
                <td colspan="6" class="p-3 text-slate-800 uppercase text-[11px]">
                  Total Gastos Operativos ${isFiltered ? 'en Periodo Filtrado' : 'Histórico General'} (${filtered.length} gastos)
                </td>
                <td class="p-3 text-right text-amber-900 text-sm font-black">${formatCurrency(totalFilteredAmount)}</td>
                <td></td>
              </tr>
            </tfoot>
          ` : ''}
        </table>
      </div>
    </div>
  `;
}

// ----------------------------------------------------
// EXPENSES MANAGEMENT FUNCTIONS (VIEW, EDIT, DELETE)
// ----------------------------------------------------

function openViewExpenseModal(expenseId) {
  const expense = (appData.expenses || []).find(e => e.id === expenseId);
  if (!expense) {
    showNotification('No se encontró el comprobante del gasto.', 'error');
    return;
  }

  const badgeEl = document.getElementById('view-exp-badge');
  const idEl = document.getElementById('view-exp-id-display');
  const dateEl = document.getElementById('view-exp-date');
  const categoryEl = document.getElementById('view-exp-category');
  const methodEl = document.getElementById('view-exp-method');
  const recipientEl = document.getElementById('view-exp-recipient');
  const descEl = document.getElementById('view-exp-description');
  const totalEl = document.getElementById('view-exp-total');
  const editBtn = document.getElementById('btn-view-exp-edit');

  const refNumber = expense.receiptRef || expense.id;
  if (badgeEl) badgeEl.innerText = refNumber;
  if (idEl) idEl.innerText = refNumber;
  if (dateEl) dateEl.innerText = formatDate(expense.date);
  if (categoryEl) categoryEl.innerText = expense.category || 'Otros Gastos';
  if (methodEl) methodEl.innerText = expense.paymentMethod || 'Transferencia Bancaria';
  if (recipientEl) recipientEl.innerText = expense.recipient || 'N/A';
  if (descEl) descEl.innerText = expense.description || 'Sin detalle especificado';
  if (totalEl) totalEl.innerText = formatCurrency(expense.amount || 0);

  if (editBtn) {
    if (isMasterUser()) {
      editBtn.classList.remove('hidden');
      editBtn.onclick = () => {
        closeModal('modal-view-expense');
        openEditExpenseModal(expense.id);
      };
    } else {
      editBtn.classList.add('hidden');
    }
  }

  openModal('modal-view-expense');
}

function openEditExpenseModal(expenseId) {
  if (!isMasterUser()) {
    showNotification('Acceso de Solo Lectura: Tu cuenta es de perfil Lite. No tienes permisos para editar gastos.', 'warning');
    return;
  }

  const expense = (appData.expenses || []).find(e => e.id === expenseId);
  if (!expense) {
    showNotification('No se encontró el gasto operativo a editar.', 'error');
    return;
  }

  const idInput = document.getElementById('edit-exp-id');
  const dateInput = document.getElementById('edit-exp-date');
  const categorySelect = document.getElementById('edit-exp-category');
  const recipientInput = document.getElementById('edit-exp-recipient');
  const methodSelect = document.getElementById('edit-exp-method');
  const receiptRefInput = document.getElementById('edit-exp-receipt-ref');
  const descInput = document.getElementById('edit-exp-description');
  const amountInput = document.getElementById('edit-exp-amount');
  const badgeEl = document.getElementById('edit-exp-badge');

  populateExpenseCategoryDropdowns(expense.category);
  if (idInput) idInput.value = expense.id;
  if (dateInput) dateInput.value = expense.date || '';
  if (categorySelect) categorySelect.value = expense.category || 'Otros Gastos';
  if (recipientInput) recipientInput.value = expense.recipient || '';
  if (methodSelect) methodSelect.value = expense.paymentMethod || 'Transferencia Bancaria';
  if (receiptRefInput) receiptRefInput.value = expense.receiptRef || expense.id;
  if (descInput) descInput.value = expense.description || '';
  if (amountInput) amountInput.value = expense.amount || 0;
  if (badgeEl) badgeEl.innerText = expense.receiptRef || expense.id;

  openModal('modal-edit-expense');
}

function submitEditExpense(event) {
  event.preventDefault();
  if (!isMasterUser()) {
    showNotification('Acceso de Solo Lectura: Tu cuenta es de perfil Lite. No tienes permisos para modificar gastos.', 'warning');
    return;
  }

  const id = document.getElementById('edit-exp-id').value;
  const expense = (appData.expenses || []).find(e => e.id === id);
  if (!expense) {
    showNotification('Error al ubicar el gasto a modificar.', 'error');
    return;
  }

  const date = document.getElementById('edit-exp-date').value || expense.date;
  const category = document.getElementById('edit-exp-category').value;
  const recipient = document.getElementById('edit-exp-recipient').value.trim();
  const paymentMethod = document.getElementById('edit-exp-method').value;
  const receiptRef = document.getElementById('edit-exp-receipt-ref').value.trim();
  const description = document.getElementById('edit-exp-description').value.trim();
  const amount = parseFloat(document.getElementById('edit-exp-amount').value) || 0;

  // Actualización no destructiva de los datos del gasto existente
  expense.date = date;
  expense.category = category;
  expense.recipient = recipient;
  expense.paymentMethod = paymentMethod;
  expense.receiptRef = receiptRef || expense.id;
  expense.description = description;
  expense.amount = amount;

  // Guardado persistente seguro
  PiscicolaStorage.save(appData);
  PiscicolaStorage.syncPost('expenses', expense);

  closeModal('modal-edit-expense');
  renderFinanzas();
  showNotification('¡Gasto operativo actualizado exitosamente!', 'success');
}

function deleteExpense(expenseId) {
  if (!isMasterUser()) {
    showNotification('Acceso de Solo Lectura: Tu cuenta es de perfil Lite. No tienes permisos para eliminar gastos.', 'warning');
    return;
  }

  const expense = (appData.expenses || []).find(e => e.id === expenseId);
  if (!expense) {
    showNotification('Gasto no encontrado.', 'error');
    return;
  }

  const confirmMsg = `¿Estás seguro de que deseas eliminar este gasto de ${formatCurrency(expense.amount)} (${expense.description || expense.category})?`;
  if (!confirm(confirmMsg)) return;

  appData.expenses = appData.expenses.filter(e => e.id !== expenseId);
  PiscicolaStorage.save(appData);
  PiscicolaStorage.syncDelete('expenses', expenseId);

  renderFinanzas();
  showNotification('Gasto operativo eliminado correctamente.', 'info');
}

window.openViewExpenseModal = openViewExpenseModal;
window.openEditExpenseModal = openEditExpenseModal;
window.submitEditExpense = submitEditExpense;
window.deleteExpense = deleteExpense;


