function openEditSaleModal(saleId) {
  if (!isMasterUser()) {
    showNotification('Acceso de Solo Lectura: Tu cuenta es de perfil Lite. No tienes permisos para registrar o modificar datos.', 'warning');
    return;
  }
  const sale = (appData.sales || []).find(s => s.id === saleId);
  if (!sale) {
    showNotification('No se encontró la venta seleccionada.', 'error');
    return;
  }

  const setVal = (id, val) => {
    const el = document.getElementById(id);
    if (el) el.value = (val !== undefined && val !== null) ? val : '';
  };

  setVal('edit-sale-id', sale.id);
  const badge = document.getElementById('edit-sale-badge');
  if (badge) badge.innerText = sale.id;

  setVal('edit-sale-date', sale.date ? sale.date.slice(0, 10) : '');
  setVal('edit-sale-invoice', sale.invoiceNumber || '');
  setVal('edit-sale-client-name', sale.clientName || '');

  // Populate harvests select
  const harvestSelect = document.getElementById('edit-sale-harvest-id');
  if (harvestSelect) {
    const harvests = appData.harvests || [];
    harvestSelect.innerHTML = `<option value="">-- Sin Cosecha Específica --</option>` +
      harvests.map(h => `<option value="${h.id}">${h.id} - ${h.unitName} (${h.species}) - ${h.totalKg} kg</option>`).join('');
    harvestSelect.value = sale.harvestId || '';
  }

  setVal('edit-sale-product', sale.product || '');
  setVal('edit-sale-quantity', sale.quantityKg || 0);
  setVal('edit-sale-price-per-kg', sale.unitPrice || 0);
  setVal('edit-sale-cost-per-kg', sale.productionCostPerKg || 0);
  setVal('edit-sale-payment-method', sale.paymentMethod || 'contado');
  setVal('edit-sale-payment-status', sale.paymentStatus || 'pagado');
  setVal('edit-sale-notes', sale.notes || '');

  calculateEditSaleFinancials();
  openModal('modal-edit-sale');
}

function onEditSaleHarvestSelectChange(harvestId) {
  const harvest = (appData.harvests || []).find(h => h.id === harvestId);
  if (harvest) {
    const prodInput = document.getElementById('edit-sale-product');
    if (prodInput && !prodInput.value) {
      prodInput.value = `${harvest.species} fresca`;
    }
    const costInput = document.getElementById('edit-sale-cost-per-kg');
    if (costInput && (!costInput.value || parseFloat(costInput.value) === 0)) {
      costInput.value = Math.round(harvest.costPerKg || 0);
    }
  }
  calculateEditSaleFinancials();
}

function calculateEditSaleFinancials() {
  const qty = parseFloat(document.getElementById('edit-sale-quantity')?.value) || 0;
  const price = parseFloat(document.getElementById('edit-sale-price-per-kg')?.value) || 0;
  const cost = parseFloat(document.getElementById('edit-sale-cost-per-kg')?.value) || 0;

  const total = qty * price;
  const totalCost = qty * cost;
  const profit = total - totalCost;
  const marginPct = total > 0 ? ((profit / total) * 100).toFixed(1) : '0.0';

  const totalEl = document.getElementById('edit-sale-preview-total');
  const costEl = document.getElementById('edit-sale-preview-cost');
  const profitEl = document.getElementById('edit-sale-preview-profit');
  const badgeEl = document.getElementById('edit-sale-preview-margin-badge');

  if (totalEl) totalEl.innerText = formatCurrency(total);
  if (costEl) costEl.innerText = formatCurrency(totalCost);
  if (profitEl) profitEl.innerText = formatCurrency(profit);
  if (badgeEl) {
    badgeEl.innerText = `Margen: ${marginPct}%`;
    badgeEl.className = profit >= 0 
      ? 'px-2 py-0.5 rounded-full text-[10px] font-black bg-emerald-100 text-emerald-800'
      : 'px-2 py-0.5 rounded-full text-[10px] font-black bg-rose-100 text-rose-800';
  }
}

function submitEditSale(event) {
  if (event) event.preventDefault();
  if (!isMasterUser()) {
    showNotification('Acceso de Solo Lectura: Tu cuenta es de perfil Lite. No tienes permisos para registrar o modificar datos.', 'warning');
    return;
  }

  const saleId = document.getElementById('edit-sale-id').value;
  if (!saleId) return;

  const saleIndex = (appData.sales || []).findIndex(s => s.id === saleId);
  if (saleIndex === -1) {
    showNotification('Error: La venta no existe en la base de datos.', 'error');
    return;
  }

  const sale = appData.sales[saleIndex];
  const date = document.getElementById('edit-sale-date').value || sale.date;
  const invoice = document.getElementById('edit-sale-invoice').value.trim();
  const clientName = document.getElementById('edit-sale-client-name').value.trim() || sale.clientName;
  const harvestId = document.getElementById('edit-sale-harvest-id').value;
  const product = document.getElementById('edit-sale-product').value.trim();
  const quantityKg = parseFloat(document.getElementById('edit-sale-quantity').value) || 0;
  const unitPrice = parseFloat(document.getElementById('edit-sale-price-per-kg').value) || 0;
  const costPerKg = parseFloat(document.getElementById('edit-sale-cost-per-kg').value) || 0;
  const paymentMethod = document.getElementById('edit-sale-payment-method').value || 'contado';
  const paymentStatus = document.getElementById('edit-sale-payment-status').value || 'pagado';
  const notes = document.getElementById('edit-sale-notes').value.trim();

  if (quantityKg <= 0 || unitPrice <= 0) {
    showNotification('Por favor ingrese kilos y precio de venta válidos.', 'warning');
    return;
  }

  const totalAmount = Math.round(quantityKg * unitPrice);
  const totalCost = Math.round(quantityKg * costPerKg);
  const grossProfit = totalAmount - totalCost;
  const profitMarginPct = totalAmount > 0 ? Math.round(((grossProfit / totalAmount) * 100) * 10) / 10 : 0;

  sale.date = date;
  sale.invoiceNumber = invoice;
  sale.clientName = clientName;
  sale.harvestId = harvestId || null;
  sale.product = product;
  sale.quantityKg = quantityKg;
  sale.unitPrice = unitPrice;
  sale.productionCostPerKg = costPerKg;
  sale.totalAmount = totalAmount;
  sale.totalCost = totalCost;
  sale.grossProfit = grossProfit;
  sale.profitMarginPct = profitMarginPct;
  sale.paymentMethod = paymentMethod;
  sale.paymentStatus = paymentStatus;
  sale.notes = notes;

  // Sync isolated company store
  if (appData.activeCompanyId && appData.companyStores && appData.companyStores[appData.activeCompanyId]) {
    const store = appData.companyStores[appData.activeCompanyId];
    if (store.sales) {
      const idx = store.sales.findIndex(s => s.id === saleId);
      if (idx !== -1) {
        store.sales[idx] = { ...sale };
      }
    }
  }

  PiscicolaStorage.save(appData);
  PiscicolaStorage.syncPut('sales', sale);

  closeModal('modal-edit-sale');
  renderApp();
  showNotification(`¡Venta "${saleId}" actualizada correctamente!`, 'success');
}

