function renderCatalogoProveedores(container) {
  let list = appData.suppliers || [];

  if (catalogoSearchTerm) {
    list = list.filter(s => {
      const q = catalogoSearchTerm;
      return (s.name || '').toLowerCase().includes(q) ||
             (s.category || '').toLowerCase().includes(q) ||
             (s.contact || '').toLowerCase().includes(q) ||
             (s.nit || '').toLowerCase().includes(q) ||
             (s.city || '').toLowerCase().includes(q) ||
             (s.phone || '').toLowerCase().includes(q);
    });
  }

  if (list.length === 0) {
    container.innerHTML = `
      <div class="p-12 text-center bg-slate-50 rounded-2xl border border-dashed border-slate-200">
        <div class="w-14 h-14 mx-auto rounded-2xl bg-purple-100 text-purple-700 flex items-center justify-center text-2xl mb-3 shadow-inner">
          <i class="fa-solid fa-truck-field"></i>
        </div>
        <h3 class="font-extrabold text-base text-slate-800">No se encontraron proveedores</h3>
        <p class="text-xs text-slate-500 mt-1 max-w-md mx-auto">
          ${catalogoSearchTerm ? 'No hay proveedores que coincidan con la búsqueda. Intente con otro término.' : 'Agregue sus empresas proveedoras de alimento concentrado, alevinos, fármacos o equipos para contactarlos fácilmente.'}
        </p>
        ${isMasterUser() ? `
          <button onclick="openModal('modal-new-supplier')" class="mt-4 px-4 py-2 bg-purple-700 hover:bg-purple-600 text-white rounded-xl font-bold text-xs shadow-md transition cursor-pointer">
            <i class="fa-solid fa-plus mr-1"></i> Registrar Primer Proveedor
          </button>
        ` : ''}
      </div>
    `;
    return;
  }

  const farmName = (appData.farmInfo && appData.farmInfo.name) ? appData.farmInfo.name : 'Piscícola';

  container.innerHTML = `
    <div class="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
      ${list.map(s => {
        const cleanPhone = (s.whatsapp || s.phone || '').replace(/\D/g, '');
        const waLink = cleanPhone ? `https://wa.me/57${cleanPhone}?text=Hola%20${encodeURIComponent(s.name)},%20le%20escribimos%20desde%20la%20pisc%C3%ADcola%20${encodeURIComponent(farmName)}%20para%20solicitar%20cotizaci%C3%B3n/pedido.` : '#';

        return `
          <div class="bg-white rounded-2xl p-4 sm:p-5 border border-slate-100 shadow-sm hover:shadow-md transition flex flex-col justify-between group">
            <div>
              <!-- Cabecera de la tarjeta -->
              <div class="flex items-start justify-between gap-2 mb-3">
                <div>
                  <span class="inline-block px-2 py-0.5 rounded-lg text-[10px] font-extrabold bg-purple-50 text-purple-800 border border-purple-200/60 mb-1">
                    ${escapeHtml(s.category || 'Insumos Varios')}
                  </span>
                  <h3 class="font-black text-base text-slate-900 leading-tight">${escapeHtml(s.name)}</h3>
                  <div class="text-[11px] text-slate-400 font-semibold mt-0.5">NIT / ID: ${escapeHtml(s.nit || 'No registrado')}</div>
                </div>
                <div class="w-10 h-10 rounded-xl bg-purple-100 text-purple-700 flex items-center justify-center shrink-0">
                  <i class="fa-solid fa-truck-field text-base"></i>
                </div>
              </div>

              <!-- Datos de contacto -->
              <div class="space-y-2 py-3 border-y border-slate-100 text-xs">
                <div class="flex items-center gap-2 text-slate-700">
                  <i class="fa-solid fa-user-tie text-purple-600 w-4"></i>
                  <span class="font-bold">${escapeHtml(s.contact || 'Asesor Comercial')}</span>
                </div>
                <div class="flex items-center gap-2 text-slate-700">
                  <i class="fa-solid fa-phone text-slate-400 w-4"></i>
                  <a href="tel:${escapeHtml(s.phone)}" class="hover:text-purple-700 font-bold">${escapeHtml(s.phone)}</a>
                </div>
                ${s.email ? `
                  <div class="flex items-center gap-2 text-slate-600">
                    <i class="fa-solid fa-envelope text-slate-400 w-4"></i>
                    <a href="mailto:${escapeHtml(s.email)}" class="hover:text-purple-700 truncate">${escapeHtml(s.email)}</a>
                  </div>
                ` : ''}
                <div class="flex items-center gap-2 text-slate-600">
                  <i class="fa-solid fa-location-dot text-slate-400 w-4"></i>
                  <span>${escapeHtml(s.city || 'Colombia')}</span>
                </div>
                <div class="flex items-center gap-2 text-slate-600">
                  <i class="fa-solid fa-clock-rotate-left text-slate-400 w-4"></i>
                  <span>Pago: <strong class="text-purple-800 font-bold">${escapeHtml(s.paymentTerms || 'Contado')}</strong></span>
                </div>
                ${s.notes ? `
                  <div class="p-2.5 bg-slate-50 rounded-xl text-[11px] text-slate-500 italic mt-1 border border-slate-100">
                    "${escapeHtml(s.notes)}"
                  </div>
                ` : ''}
              </div>
            </div>

            <!-- Botones de Acción -->
            <div class="pt-3 flex items-center justify-between gap-2 mt-2">
              <div class="flex items-center gap-2">
                ${cleanPhone ? `
                  <a href="${waLink}" target="_blank" class="px-3 py-1.5 bg-emerald-600 hover:bg-emerald-500 text-white rounded-xl font-bold text-xs flex items-center gap-1.5 shadow-sm transition">
                    <i class="fa-brands fa-whatsapp text-sm"></i> WhatsApp
                  </a>
                ` : ''}
                <a href="tel:${escapeHtml(s.phone)}" class="px-3 py-1.5 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-xl font-bold text-xs flex items-center gap-1.5 transition">
                  <i class="fa-solid fa-phone text-xs"></i> Llamar
                </a>
              </div>
              ${isMasterUser() ? `
                <div class="flex items-center gap-1">
                  <button onclick="openEditSupplierModal('${s.id}')" title="Editar Proveedor" class="p-2 text-slate-400 hover:text-purple-600 hover:bg-purple-50 rounded-lg transition cursor-pointer">
                    <i class="fa-solid fa-pen-to-square"></i>
                  </button>
                  <button onclick="deleteSupplier('${s.id}')" title="Eliminar Proveedor" class="p-2 text-slate-300 hover:text-rose-600 hover:bg-rose-50 rounded-lg transition cursor-pointer">
                    <i class="fa-solid fa-trash-can"></i>
                  </button>
                </div>
              ` : ''}
            </div>
          </div>
        `;
      }).join('')}
    </div>
  `;
}

