function deleteCategory(catId) {
  if (!isMasterUser()) {
    showNotification('Acceso de Solo Lectura: Tu cuenta es de perfil Lite. No tienes permisos para registrar o modificar datos.', 'warning');
    return;
  }
  const cat = (appData.categoriesCatalog || []).find(c => c.id === catId);
  if (!cat) return;

  const countInUse = (appData.inventory || []).filter(i => (i.category || '').toLowerCase() === (cat.name || '').toLowerCase()).length;
  const countInUseExpenses = (appData.expenses || []).filter(e => (e.category || '').toLowerCase() === (cat.name || '').toLowerCase()).length;

  if (countInUse > 0) {
    if (!confirm(`La categoría "${cat.name}" está en uso por ${countInUse} insumo(s) en inventario. ¿Desea eliminarla de todos modos?`)) {
      return;
    }
  } else if (countInUseExpenses > 0) {
    if (!confirm(`La categoría "${cat.name}" está en uso por ${countInUseExpenses} gasto(s) operativo(s) registrado(s). ¿Desea eliminarla de todos modos?`)) {
      return;
    }
  } else {
    if (!confirm(`¿Confirma que desea eliminar la categoría "${cat.name}" del catálogo?`)) {
      return;
    }
  }

  appData.categoriesCatalog = (appData.categoriesCatalog || []).filter(c => c.id !== catId);
  PiscicolaStorage.save(appData);

  activeCatalogoSubTab = 'categorias';
  renderApp();
  populateBrandCategorySelects();
  populateInventoryCategoryDropdowns();
  populateExpenseCategoryDropdowns();
  populateInventoryDropdowns();

  showNotification(`Categoría "${cat.name}" eliminada del catálogo.`, 'info');
}

