function submitNewSupplier(event) {
  if (event) event.preventDefault();
  if (!isMasterUser()) {
    showNotification('Acceso de Solo Lectura: Tu cuenta es de perfil Lite. No tienes permisos para registrar o modificar datos.', 'warning');
    return;
  }
  const name = document.getElementById('supp-name') ? document.getElementById('supp-name').value.trim() : '';
  const nit = document.getElementById('supp-nit') ? document.getElementById('supp-nit').value.trim() : '';
  const category = document.getElementById('supp-category') ? document.getElementById('supp-category').value : 'Insumos Varios';
  const contact = document.getElementById('supp-contact') ? document.getElementById('supp-contact').value.trim() : '';
  const phone = document.getElementById('supp-phone') ? document.getElementById('supp-phone').value.trim() : '';
  const whatsapp = document.getElementById('supp-whatsapp') ? document.getElementById('supp-whatsapp').value.trim() : '';
  const email = document.getElementById('supp-email') ? document.getElementById('supp-email').value.trim() : '';
  const city = document.getElementById('supp-city') ? document.getElementById('supp-city').value.trim() : '';
  const terms = document.getElementById('supp-terms') ? document.getElementById('supp-terms').value : 'Contado';
  const notes = document.getElementById('supp-notes') ? document.getElementById('supp-notes').value.trim() : '';

  if (!name || !phone) {
    showNotification('Por favor complete los campos obligatorios: Nombre del Proveedor y Teléfono.', 'warning');
    return;
  }

  const newSupplier = {
    id: `SUPP-${Date.now().toString().slice(-4)}`,
    name,
    nit: nit || 'No registrado',
    category,
    contact: contact || 'Contacto Comercial',
    phone,
    whatsapp: whatsapp || phone.replace(/\D/g, ''),
    email: email || '',
    city: city || 'Colombia',
    paymentTerms: terms,
    notes: notes || '',
    status: 'activo',
    createdAt: new Date().toISOString().slice(0, 10)
  };

  if (!appData.suppliers) appData.suppliers = [];
  appData.suppliers.push(newSupplier);

  PiscicolaStorage.save(appData);
  PiscicolaStorage.syncPost('suppliers', newSupplier);

  closeModal('modal-new-supplier');
  const form = document.getElementById('form-add-supplier');
  if (form) form.reset();

  populateSupplierDropdowns();
  const purSupplier = document.getElementById('pur-supplier');
  if (purSupplier) {
    purSupplier.value = name;
    onSupplierSelectChange(purSupplier);
  }

  activeCatalogoSubTab = 'proveedores';
  renderApp();
  showNotification(`¡Proveedor "${name}" registrado exitosamente en el catálogo!`, 'success');
}

