function toggleEditInventoryCategoryFields(category) {
  const feedFields = document.getElementById('edit-inv-feed-extra-fields');
  const medFields = document.getElementById('edit-inv-med-extra-fields');
  const alevinoFields = document.getElementById('edit-inv-alevino-extra-fields');

  const isFeed = isAlimentoCategory(category);
  const isMed = isMedicamentoCategory(category);
  const isAlevino = isAlevinoCategory(category);

  if (isFeed) {
    if (feedFields) feedFields.classList.remove('hidden');
    if (medFields) medFields.classList.add('hidden');
    if (alevinoFields) alevinoFields.classList.add('hidden');
  } else if (isMed) {
    if (feedFields) feedFields.classList.add('hidden');
    if (medFields) medFields.classList.remove('hidden');
    if (alevinoFields) alevinoFields.classList.add('hidden');
  } else if (isAlevino) {
    if (feedFields) feedFields.classList.add('hidden');
    if (medFields) medFields.classList.add('hidden');
    if (alevinoFields) alevinoFields.classList.remove('hidden');
  } else {
    if (feedFields) feedFields.classList.add('hidden');
    if (medFields) medFields.classList.add('hidden');
    if (alevinoFields) alevinoFields.classList.add('hidden');
  }
}

function openEditInventoryItemModal(itemId) {
  if (!isMasterUser()) {
    showNotification('Acceso de Solo Lectura: Tu cuenta es de perfil Lite. No tienes permisos para registrar o modificar datos.', 'warning');
    return;
  }
  const item = (appData.inventory || []).find(i => i.id === itemId);
  if (!item) return;

  populateInventoryCategoryDropdowns();

  const idEl = document.getElementById('edit-inv-item-id');
  const catEl = document.getElementById('edit-inv-item-category');
  const nameEl = document.getElementById('edit-inv-item-name');
  const presEl = document.getElementById('edit-inv-item-presentation');
  const unitEl = document.getElementById('edit-inv-item-unit');
  const stockEl = document.getElementById('edit-inv-item-stock');
  const minStockEl = document.getElementById('edit-inv-item-min-stock');
  const costEl = document.getElementById('edit-inv-item-cost');
  const brandEl = document.getElementById('edit-inv-item-brand');
  const hatchEl = document.getElementById('edit-inv-item-hatchery');
  const lineEl = document.getElementById('edit-inv-item-lineage');
  const proteinEl = document.getElementById('edit-inv-item-protein');
  const actEl = document.getElementById('edit-inv-item-active-ingredient');
  const withEl = document.getElementById('edit-inv-item-withdrawal');
  const suppEl = document.getElementById('edit-inv-item-supplier');
  const locEl = document.getElementById('edit-inv-item-location');
  const notesEl = document.getElementById('edit-inv-item-notes');

  if (idEl) idEl.value = item.id;
  if (catEl) {
    const targetCat = item.category || 'Alimento Concentrado';
    let matchFound = false;
    for (let i = 0; i < catEl.options.length; i++) {
      if (catEl.options[i].value === targetCat || 
          (targetCat.toLowerCase().includes('alimento') && catEl.options[i].value.toLowerCase().includes('alimento')) ||
          (targetCat.toLowerCase().includes('medicamento') && catEl.options[i].value.toLowerCase().includes('medicamento'))) {
        catEl.selectedIndex = i;
        matchFound = true;
        break;
      }
    }
    if (!matchFound) {
      const opt = document.createElement('option');
      opt.value = targetCat;
      opt.textContent = `${targetCat} (Actual)`;
      catEl.appendChild(opt);
      catEl.value = targetCat;
    }
  }
  if (nameEl) nameEl.value = item.name || '';
  if (presEl) presEl.value = item.presentation || '';
  if (unitEl) unitEl.value = item.unit || 'kg';
  const currentActualStock = item.currentStock != null ? item.currentStock : (item.currentStockKg || 0);
  const currentActualMinStock = item.minStock != null ? item.minStock : (item.minStockKg || 0);
  const currentActualCost = (item.costPerUnit != null && item.costPerUnit > 0) ? item.costPerUnit : (item.costPerKg || 0);
  if (stockEl) stockEl.value = currentActualStock;
  if (minStockEl) minStockEl.value = currentActualMinStock;
  if (costEl) costEl.value = currentActualCost;
  if (brandEl) brandEl.value = item.brand || '';
  if (hatchEl) hatchEl.value = item.hatchery || (isAlevinoCategory(item.category) ? getAlevinoOriginLabel(item) : '');
  if (lineEl) lineEl.value = item.lineage || '';
  if (proteinEl) proteinEl.value = item.proteinPct !== undefined ? item.proteinPct : '';
  if (actEl) actEl.value = item.activeIngredient || '';
  if (withEl) withEl.value = item.withdrawalDays !== undefined ? item.withdrawalDays : 0;
  toggleEditInventoryCategoryFields(catEl ? catEl.value : 'alimento');
  openModal('modal-edit-inventory-item');

  if (suppEl) {
    const rawSupp = item.supplier || '';
    if (rawSupp && !Array.from(suppEl.options).some(o => o.value === rawSupp)) {
      const opt = document.createElement('option');
      opt.value = rawSupp;
      opt.textContent = `${rawSupp} (Actual)`;
      suppEl.appendChild(opt);
    }
    suppEl.value = rawSupp;
    onSupplierSelectChange(suppEl);
  }
}

function submitEditInventoryItem(event) {
  if (event) event.preventDefault();
  if (!isMasterUser()) {
    showNotification('Acceso de Solo Lectura: Tu cuenta es de perfil Lite. No tienes permisos para registrar o modificar datos.', 'warning');
    return;
  }

  const id = document.getElementById('edit-inv-item-id') ? document.getElementById('edit-inv-item-id').value : '';
  const item = (appData.inventory || []).find(i => i.id === id);
  if (!item) {
    showNotification('No se encontró el insumo a editar.', 'error');
    return;
  }

  const category = document.getElementById('edit-inv-item-category').value;
  const name = document.getElementById('edit-inv-item-name').value.trim();
  const presentation = document.getElementById('edit-inv-item-presentation').value.trim();
  const unit = document.getElementById('edit-inv-item-unit').value;
  const stock = parseFloat(document.getElementById('edit-inv-item-stock').value) || 0;
  const minStock = parseFloat(document.getElementById('edit-inv-item-min-stock').value) || 0;
  const cost = parseFloat(document.getElementById('edit-inv-item-cost').value) || 0;
  const brand = document.getElementById('edit-inv-item-brand').value.trim();
  const hatchery = document.getElementById('edit-inv-item-hatchery') ? document.getElementById('edit-inv-item-hatchery').value.trim() : '';
  const lineage = document.getElementById('edit-inv-item-lineage') ? document.getElementById('edit-inv-item-lineage').value.trim() : '';
  const protein = parseFloat(document.getElementById('edit-inv-item-protein').value) || 0;
  const activeIngredient = document.getElementById('edit-inv-item-active-ingredient').value.trim();
  const withdrawal = parseInt(document.getElementById('edit-inv-item-withdrawal').value, 10) || 0;
  const supplier = getSelectedSupplierValue('edit-inv-item-supplier', 'edit-inv-item-custom-supplier', 'Proveedor Local');
  const location = document.getElementById('edit-inv-item-location').value.trim();
  const notes = document.getElementById('edit-inv-item-notes').value.trim();

  if (!name) {
    showNotification('El nombre comercial del insumo es obligatorio.', 'warning');
    return;
  }

  const isFeed = isAlimentoCategory(category);
  const isAlevino = isAlevinoCategory(category) || name.toLowerCase().includes('alevin');

  item.category = category;
  item.name = name;
  item.presentation = presentation;
  item.unit = unit;
  item.currentStock = stock;
  item.currentStockKg = isFeed ? stock : stock;
  item.minStock = minStock;
  item.minStockKg = isFeed ? minStock : minStock;
  item.costPerUnit = cost;
  item.costPerKg = isFeed ? cost : cost;

  if (isAlevino) {
    item.hatchery = hatchery || 'Criadero Certificado';
    item.lineage = lineage;
    item.brand = item.hatchery;
    if (supplier && supplier.toLowerCase().includes('italcol')) {
      item.supplier = item.hatchery;
    } else {
      item.supplier = supplier;
    }
  } else {
    item.brand = brand;
    item.supplier = supplier;
  }

  item.proteinPct = protein;
  item.activeIngredient = activeIngredient;
  item.withdrawalDays = withdrawal;
  item.location = location;
  item.notes = notes;
  item.lastUpdate = new Date().toISOString();

  PiscicolaStorage.save(appData);
  PiscicolaStorage.syncPut(`inventory/${id}`, item);

  closeModal('modal-edit-inventory-item');
  populateInventoryDropdowns();
  renderApp();
  showNotification(`¡Insumo "${name}" actualizado con éxito en el catálogo!`, 'success');
}

