function submitNewSpeciesCatalog(event) {
  if (event) event.preventDefault();
  if (!isMasterUser()) {
    showNotification('Acceso de Solo Lectura: Tu cuenta es de perfil Lite. No tienes permisos para registrar o modificar datos.', 'warning');
    return;
  }
  const name = document.getElementById('spec-name') ? document.getElementById('spec-name').value.trim() : '';
  const code = document.getElementById('spec-code') ? document.getElementById('spec-code').value.trim().toUpperCase() : 'R';
  const scientific = document.getElementById('spec-scientific') ? document.getElementById('spec-scientific').value.trim() : '';
  const weightMin = parseFloat(document.getElementById('spec-weight-min') ? document.getElementById('spec-weight-min').value : 450) || 450;
  const weightMax = parseFloat(document.getElementById('spec-weight-max') ? document.getElementById('spec-weight-max').value : 600) || 600;
  const days = parseInt(document.getElementById('spec-days') ? document.getElementById('spec-days').value : 180, 10) || 180;
  const category = document.getElementById('spec-category') ? document.getElementById('spec-category').value : 'Cultivo Comercial';
  const notes = document.getElementById('spec-notes') ? document.getElementById('spec-notes').value.trim() : '';

  if (!name || !code) {
    showNotification('Por favor ingrese el Nombre de la Especie y el Código de Lote de 1 letra.', 'warning');
    return;
  }

  const newSpecies = {
    id: `ESP-${Date.now().toString().slice(-4)}`,
    name,
    code,
    scientificName: scientific || name,
    harvestWeightGramsMin: weightMin,
    harvestWeightGramsMax: weightMax,
    estimatedCycleDays: days,
    category,
    active: true,
    notes: notes || '',
    createdAt: new Date().toISOString().slice(0, 10)
  };

  if (!appData.speciesCatalog) appData.speciesCatalog = [];
  appData.speciesCatalog.push(newSpecies);

  PiscicolaStorage.save(appData);

  closeModal('modal-new-species-catalog');
  const form = document.getElementById('form-new-species-catalog');
  if (form) form.reset();

  populateModalSelects();
  activeCatalogoSubTab = 'especies';
  renderApp();
  showNotification(`¡Especie "${name}" [${code}] registrada exitosamente! Ya está disponible en siembras, lotes y traslados.`, 'success');
}

