// Feeding Calculator Tool
function calculateFeedingRation() {
  const weight = parseFloat(document.getElementById('calc-fish-weight').value) || 0;
  const count = parseInt(document.getElementById('calc-fish-count').value) || 0;
  const temp = parseFloat(document.getElementById('calc-water-temp').value) || 26;

  if (!weight || !count) {
    showNotification("Por favor ingrese el peso promedio y el número de peces.", 'warning');
    return;
  }

  const biomassKg = (count * weight) / 1000;
  let ratePct = getRecommendedFeedRate(weight);

  // Temperature correction factor
  if (temp < 22) ratePct *= 0.75; // Low temp slows metabolism
  else if (temp > 31) ratePct *= 0.85; // High temp causes stress

  const dailyKg = (biomassKg * (ratePct / 100)).toFixed(1);
  const rations = weight < 20 ? 5 : weight < 100 ? 4 : 3;
  const perRationKg = (dailyKg / rations).toFixed(2);

  const resEl = document.getElementById('calc-result');
  if (resEl) {
    resEl.innerHTML = `
      <div class="bg-sky-50 p-4 rounded-xl border border-sky-200 text-xs space-y-2">
        <div class="flex justify-between font-bold text-slate-800">
          <span>Biomasa Total Estimada:</span>
          <span class="text-cyan-800">${formatNumber(biomassKg, 0)} kg</span>
        </div>
        <div class="flex justify-between font-bold text-slate-800">
          <span>Tasa de Alimentación Sugerida:</span>
          <span class="text-emerald-700">${ratePct.toFixed(2)}% del peso vivo diario</span>
        </div>
        <div class="flex justify-between font-black text-slate-900 text-sm border-t border-sky-200 pt-2">
          <span>Ración Diaria Total:</span>
          <span class="text-cyan-700">${dailyKg} kg / día</span>
        </div>
        <div class="flex justify-between text-slate-600">
          <span>Frecuencia recomendada:</span>
          <span>${rations} comidas al día (${perRationKg} kg por ración)</span>
        </div>
      </div>
    `;
  }
}

